# ================= LOGIN =================

@bp.route(
    "/login",
    methods=["GET", "POST"]
)
def login():

    # ========================================================
    # ALREADY LOGGED IN IN CURRENT BROWSER SESSION
    # ========================================================

    if current_user.is_authenticated:

        flash(
            "You are already logged in.",
            "info"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # GET
    # ========================================================

    if request.method == "GET":

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # FORM DATA
    # ========================================================

    username_or_email = request.form.get(
        "username",
        ""
    ).strip()

    password = request.form.get(
        "password",
        ""
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    if not username_or_email:

        flash(
            "Username or email is required.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    if not password:

        flash(
            "Password is required.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # FIND USER
    # ========================================================

    user = User.query.filter(
        db.or_(
            User.username == username_or_email,
            User.email == username_or_email.lower()
        )
    ).first()

    # ========================================================
    # USER NOT FOUND
    # ========================================================

    if not user:

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # CHECK PASSWORD
    # ========================================================

    if not user.check_password(password):

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # CHECK ACCOUNT STATUS
    # ========================================================

    if not user.status:

        flash(
            "Your account is inactive. "
            "Please contact the administrator.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # NORMALIZE ROLE
    # ========================================================

    role = (
        getattr(user, "role", None) or ""
    ).strip().lower()

    # ========================================================
    # IMPORTANT
    #
    # DO NOT BLOCK USER IF auth_status == "login"
    #
    # User can login from another browser/device/session.
    # Old session will remain valid unless you implement
    # global session invalidation.
    # ========================================================

    # NO CHECK LIKE:
    #
    # if user.auth_status == "login":
    #     ...
    #
    # This has intentionally been removed.
    #

    # ========================================================
    # LOGIN USER
    # ========================================================

    login_user(
        user,
        remember=True
    )

    # ========================================================
    # CREATE NEW LOGIN SESSION
    # ========================================================

    now = datetime.utcnow()

    user.auth_status = "login"

    user.login_time = now

    user.last_active = now

    user.last_seen = now

    # ========================================================
    # GENERATE NEW SESSION TOKEN
    #
    # This token represents the latest login.
    # ========================================================

    user.session_token = secrets.token_hex(32)

    # ========================================================
    # CLEAR OLD LOGOUT TIME
    # ========================================================

    if hasattr(
        user,
        "logout_time"
    ):

        user.logout_time = None

    # ========================================================
    # SAVE LOGIN INFORMATION
    # ========================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "Login update error"
        )

        logout_user()

        flash(
            "Unable to complete login. "
            "Please try again.",
            "danger"
        )

        return render_template(
            "backend/auth/login.html"
        )

    # ========================================================
    # SUCCESS MESSAGE
    # ========================================================

    flash(
        f"Welcome back, "
        f"{user.fullname or user.username}!",
        "success"
    )

    # ========================================================
    # REDIRECT BASED ON ROLE
    # ========================================================

    if role == "superadmin":
        return redirect(
            url_for("main.dashboard")
        )

    elif role == "school_admin":
        return redirect(
            url_for("main.dashboard")
        )

    elif role == "branch_admin":
        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # FALLBACK
    # ========================================================

    return redirect(
        url_for("main.dashboard")
    )

