@bp.route(
    "/teacher/login",
    methods=["GET", "POST"]
)
def teacher_login():

    # ========================================================
    # ALREADY LOGGED IN AS TEACHER
    # ========================================================

    if session.get("teacher_id"):

        flash(
            "You are already logged in.",
            "info"
        )

        return redirect(
            url_for("main.teacher_dashboard")
        )

    # ========================================================
    # GET
    # ========================================================

    if request.method == "GET":

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # FORM DATA
    # ========================================================

    username_or_email = request.form.get(
        "username",
        ""
    ).strip()

    password = request.form.get(
        "password",
        ""
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    if not username_or_email:

        flash(
            "Username or email is required.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    if not password:

        flash(
            "Password is required.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # FIND TEACHER
    # ========================================================

    teacher = Teacher.query.filter(
        db.or_(
            Teacher.username == username_or_email,
            Teacher.email == username_or_email.lower()
        )
    ).first()

    # ========================================================
    # TEACHER NOT FOUND
    # ========================================================

    if not teacher:

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK PASSWORD
    # ========================================================

    if not teacher.check_password(password):

        flash(
            "Invalid username/email or password.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK ACCOUNT ACTIVE
    # ========================================================

    if not teacher.is_active:

        flash(
            "Your teacher account is inactive. "
            "Please contact the administrator.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK TEACHER STATUS
    # ========================================================

    if teacher.status != "active":

        if teacher.status == "suspended":

            message = (
                "Your teacher account has been suspended. "
                "Please contact the administrator."
            )

        elif teacher.status == "resigned":

            message = (
                "This teacher account is no longer active."
            )

        else:

            message = (
                "Your teacher account is inactive. "
                "Please contact the administrator."
            )

        flash(
            message,
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CHECK ROLE
    # ========================================================

    if teacher.role != "teacher":

        flash(
            "This account is not registered as a teacher account.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # CREATE TEACHER SESSION
    #
    # IMPORTANT:
    # No database auth_status/session_token check here.
    #
    # The same teacher can login from:
    # - another browser
    # - another computer
    # - another device
    #
    # ========================================================

    session["teacher_id"] = teacher.id

    session["teacher_role"] = "teacher"

    session["teacher_institution_id"] = (
        teacher.institution_id
    )

    session["teacher_branch_id"] = (
        teacher.branch_id
    )

    # ========================================================
    # UPDATE LOGIN INFORMATION
    # ========================================================

    now = datetime.utcnow()

    teacher.login_time = now

    teacher.last_login = now

    teacher.last_active = now

    # ========================================================
    # SAVE LOGIN INFORMATION
    # ========================================================

    try:

        db.session.commit()

    except Exception:

        db.session.rollback()

        # Remove only teacher session values
        session.pop(
            "teacher_id",
            None
        )

        session.pop(
            "teacher_role",
            None
        )

        session.pop(
            "teacher_institution_id",
            None
        )

        session.pop(
            "teacher_branch_id",
            None
        )

        current_app.logger.exception(
            "Teacher login update error"
        )

        flash(
            "Unable to complete teacher login. "
            "Please try again.",
            "danger"
        )

        return render_template(
            "backend/auth/teacher_login.html"
        )

    # ========================================================
    # SUCCESS MESSAGE
    # ========================================================

    flash(
        f"Welcome back, {teacher.full_name}!",
        "success"
    )

    # ========================================================
    # REDIRECT TEACHER DASHBOARD
    # ========================================================

    return redirect(
        url_for("main.teacher_dashboard")
    )


# ============================================================
# TEACHER DASHBOARD
# ============================================================

@bp.route(
    "/teacher/dashboard",
    methods=["GET"]
)
@teacher_login_required
def teacher_dashboard():

    # ========================================================
    # CURRENT TEACHER
    # ========================================================

    teacher = getattr(g, "teacher", None)

    if not teacher:
        abort(403)

    # ========================================================
    # BASIC TEACHER IDS
    # ========================================================

    teacher_id = teacher.id

    institution_id = teacher.institution_id

    branch_id = teacher.branch_id

    # ========================================================
    # INSTITUTION
    # ========================================================
    # Teacher -> Institution
    #
    # Waxaan si gaar ah u query-gareyneynaa si dashboard-ku
    # u helo institution-ka saxda ah.

    institution = None

    if institution_id:

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )

    # ========================================================
    # BRANCH
    # ========================================================
    # Branch waa inuu ka tirsan yahay institution-ka teacher-ka.

    branch = None

    if branch_id and institution_id:

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id,
                Branch.institution_id == institution_id
            )
            .first()
        )

    # ========================================================
    # TEACHER SUBJECT ASSIGNMENTS
    # ========================================================
    # TeacherSubject:
    #
    # Teacher
    # Subject
    # Program
    # Class
    # Section
    # Academic Year
    #
    # Waxaan ku xireynaa institution + branch si aysan
    # teacher-ku u arkin assignment branch kale.

    teacher_subjects = (
        TeacherSubject.query
        .filter(
            TeacherSubject.teacher_id == teacher_id,
            TeacherSubject.institution_id == institution_id,
            TeacherSubject.branch_id == branch_id
        )
        .order_by(
            TeacherSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # SUBJECT COUNT
    # ========================================================

    subjects_count = len(
        teacher_subjects
    )

    # ========================================================
    # EXAM SUBJECT ASSIGNMENTS
    # ========================================================
    # ExamSubject institution/branch columns ma laha.
    #
    # Sidaas darteed Exam ayaan JOIN gareyneynaa:
    #
    # ExamSubject -> Exam
    #
    # kadib waxaan ka filter-gareyneynaa institution iyo branch.

    exam_subjects = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.teacher_id == teacher_id,
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )
        .order_by(
            ExamSubject.id.desc()
        )
        .all()
    )

    # ========================================================
    # EXAM SUBJECT COUNT
    # ========================================================

    exam_subjects_count = len(
        exam_subjects
    )

    # ========================================================
    # LAST ACTIVE
    # ========================================================

    last_active = teacher.last_active

    # ========================================================
    # RENDER DASHBOARD
    # ========================================================

    return render_template(
        "backend/teacher/home/dashboard.html",


        # ----------------------------------------------------
        # TEACHER
        # ----------------------------------------------------

        teacher=teacher,
        teacher_id=teacher_id,

        # ----------------------------------------------------
        # INSTITUTION
        # ----------------------------------------------------

        institution=institution,
        institution_id=institution_id,

        # ----------------------------------------------------
        # BRANCH
        # ----------------------------------------------------

        branch=branch,
        branch_id=branch_id,

        # ----------------------------------------------------
        # TEACHER SUBJECTS
        # ----------------------------------------------------

        teacher_subjects=teacher_subjects,
        subjects_count=subjects_count,

        # ----------------------------------------------------
        # EXAM SUBJECTS
        # ----------------------------------------------------

        exam_subjects=exam_subjects,
        exam_subjects_count=exam_subjects_count,

        # ----------------------------------------------------
        # SESSION / ACTIVITY
        # ----------------------------------------------------

        last_active=last_active
    )




# ================= REGISTER =================
@bp.route("/register", methods=["GET", "POST"])
def register():

    # ========================================================
    # ALREADY LOGGED IN
    # ========================================================

    if current_user.is_authenticated:

        flash(
            "You are already logged in.",
            "info"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # CHECK IF USERS ALREADY EXIST
    # ========================================================
    #
    # First registration only:
    # First user = Superadmin
    #
    # After the first user exists, public registration
    # is disabled.
    # ========================================================

    if User.query.first():

        flash(
            "Registration is currently closed.",
            "warning"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM DATA
        # ====================================================

        username = request.form.get(
            "username",
            ""
        ).strip()

        email = request.form.get(
            "email",
            ""
        ).strip().lower()

        fullname = request.form.get(
            "fullname",
            ""
        ).strip()

        password = request.form.get(
            "password",
            ""
        )

        confirm_password = request.form.get(
            "confirm_password",
            ""
        )

        # ====================================================
        # VALIDATION
        # ====================================================

        if not username:

            flash(
                "Username is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not email:

            flash(
                "Email is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not fullname:

            flash(
                "Full name is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if not password:

            flash(
                "Password is required.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        if password != confirm_password:

            flash(
                "Passwords do not match.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CHECK USERNAME
        # ====================================================

        existing_username = User.query.filter_by(
            username=username
        ).first()

        if existing_username:

            flash(
                "Username already exists.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CHECK EMAIL
        # ====================================================

        existing_email = User.query.filter_by(
            email=email
        ).first()

        if existing_email:

            flash(
                "Email already exists.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # CREATE FIRST USER
        # ====================================================

        user = User(
            username=username,
            email=email,
            fullname=fullname,

            # First and only public registration
            role=UserRole.superadmin.value,

            status=True,
            is_verified=True,
            auth_status="logout"
        )

        # ====================================================
        # PASSWORD
        # ====================================================

        user.set_password(
            password
        )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                user
            )

            db.session.commit()

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Registration error"
            )

            flash(
                "An error occurred while creating "
                "your account.",
                "danger"
            )

            return render_template(
                "backend/auth/register.html"
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Registration successful. "
            "Your Superadmin account has been created. "
            "Please login.",
            "success"
        )

        return redirect(
            url_for("main.login")
        )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/auth/register.html"
    )


