@bp.route(
    "/edit-institution/<int:institution_id>",
    methods=["GET", "POST"]
)
@login_required
def edit_institution(institution_id):

    # --------------------------------------------------------
    # SUPERADMIN ONLY
    # --------------------------------------------------------

    if not current_user.is_authenticated:
        flash(
            "Authentication required.",
            "danger"
        )
        return redirect(
            url_for("main.login")
        )

    if not current_user.is_superadmin():
        flash(
            "You do not have permission to edit this institution.",
            "danger"
        )
        return redirect(
            url_for("main.dashboard")
        )

    # --------------------------------------------------------
    # FIND INSTITUTION
    # --------------------------------------------------------

    institution = Institution.query.get_or_404(
        institution_id
    )

    # --------------------------------------------------------
    # POST
    # --------------------------------------------------------

    if request.method == "POST":

        try:

            # ------------------------------------------------
            # FORM DATA
            # ------------------------------------------------

            name = request.form.get(
                "name",
                ""
            ).strip()

            short_name = request.form.get(
                "short_name",
                ""
            ).strip()

            code = request.form.get(
                "code",
                ""
            ).strip()

            email = request.form.get(
                "email",
                ""
            ).strip()

            phone = request.form.get(
                "phone",
                ""
            ).strip()

            country = request.form.get(
                "country",
                ""
            ).strip()

            state = request.form.get(
                "state",
                ""
            ).strip()

            city = request.form.get(
                "city",
                ""
            ).strip()

            address = request.form.get(
                "address",
                ""
            ).strip()

            website = request.form.get(
                "website",
                ""
            ).strip()

            description = request.form.get(
                "description",
                ""
            ).strip()

            status = request.form.get(
                "status",
                "active"
            ).strip().lower()

            # ------------------------------------------------
            # VALIDATION
            # ------------------------------------------------

            if not name:

                flash(
                    "Institution name is required.",
                    "danger"
                )

                return render_template(
                    "backend/institutions/edit_institution.html",
                    institution=institution
                )

            # ------------------------------------------------
            # VALID STATUS
            # ------------------------------------------------

            allowed_statuses = {
                "active",
                "inactive",
                "suspended"
            }

            if status not in allowed_statuses:

                status = "active"

            # ------------------------------------------------
            # DUPLICATE NAME
            # ------------------------------------------------

            existing_name = Institution.query.filter(
                db.func.lower(
                    Institution.name
                ) == name.lower(),
                Institution.id != institution.id
            ).first()

            if existing_name:

                flash(
                    "Another institution with this name already exists.",
                    "danger"
                )

                return render_template(
                    "backend/institutions/edit_institution.html",
                    institution=institution
                )

            # ------------------------------------------------
            # DUPLICATE CODE
            # ------------------------------------------------

            if code and hasattr(
                Institution,
                "code"
            ):

                existing_code = Institution.query.filter(
                    db.func.lower(
                        Institution.code
                    ) == code.lower(),
                    Institution.id != institution.id
                ).first()

                if existing_code:

                    flash(
                        "Another institution with this code already exists.",
                        "danger"
                    )

                    return render_template(
                        "backend/institutions/edit_institution.html",
                        institution=institution
                    )

            # ------------------------------------------------
            # UPDATE BASIC INFORMATION
            # ------------------------------------------------

            institution.name = name

            # ------------------------------------------------
            # OPTIONAL FIELDS
            # ------------------------------------------------

            if hasattr(
                Institution,
                "short_name"
            ):
                institution.short_name = (
                    short_name or None
                )

            if hasattr(
                Institution,
                "code"
            ):
                institution.code = (
                    code or None
                )

            if hasattr(
                Institution,
                "email"
            ):
                institution.email = (
                    email or None
                )

            if hasattr(
                Institution,
                "phone"
            ):
                institution.phone = (
                    phone or None
                )

            if hasattr(
                Institution,
                "country"
            ):
                institution.country = (
                    country or None
                )

            if hasattr(
                Institution,
                "state"
            ):
                institution.state = (
                    state or None
                )

            if hasattr(
                Institution,
                "city"
            ):
                institution.city = (
                    city or None
                )

            if hasattr(
                Institution,
                "address"
            ):
                institution.address = (
                    address or None
                )

            if hasattr(
                Institution,
                "website"
            ):
                institution.website = (
                    website or None
                )

            if hasattr(
                Institution,
                "description"
            ):
                institution.description = (
                    description or None
                )

            if hasattr(
                Institution,
                "status"
            ):
                institution.status = status

            # ------------------------------------------------
            # SAVE
            # ------------------------------------------------

            db.session.commit()

            flash(
                f"Institution '{institution.name}' was updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_institutions"
                )
            )

        except IntegrityError:

            db.session.rollback()

            flash(
                "Unable to update institution because "
                "some information already exists.",
                "danger"
            )

        except Exception as e:

            db.session.rollback()

            print(
                "EDIT INSTITUTION ERROR:",
                e
            )

            flash(
                "An unexpected error occurred while updating "
                "the institution.",
                "danger"
            )

    # --------------------------------------------------------
    # GET
    # --------------------------------------------------------

    return render_template(
        "backend/pages/institutions/edit_institution.html",
        institution=institution,
        user=current_user
    )


