# ============================================================
# BRANCH IMAGE UPLOAD HELPER
# ============================================================
def upload_branch_image(file, folder="branches"):
    """
    Upload one branch image to Cloudinary.

    Cloudinary configuration is expected to be configured
    globally elsewhere in the application.

    Returns:
        secure_url or None

    Raises:
        ValueError for invalid files
        RuntimeError for upload/configuration errors
    """

    # ========================================================
    # NO FILE
    # ========================================================

    if not file:
        return None

    if not file.filename:
        return None


    # ========================================================
    # ALLOWED EXTENSIONS
    # ========================================================

    allowed_extensions = {
        "jpg",
        "jpeg",
        "png",
        "webp",
        "gif"
    }


    filename = file.filename.strip()


    if "." not in filename:

        raise ValueError(
            "Invalid image file."
        )


    extension = (
        filename
        .rsplit(".", 1)[1]
        .lower()
    )


    if extension not in allowed_extensions:

        raise ValueError(
            "Only JPG, JPEG, PNG, WEBP and GIF images are allowed."
        )


    # ========================================================
    # ALLOWED MIME TYPES
    # ========================================================

    allowed_mimetypes = {
        "image/jpeg",
        "image/png",
        "image/webp",
        "image/gif"
    }


    if file.mimetype not in allowed_mimetypes:

        raise ValueError(
            "Invalid image type."
        )


    # ========================================================
    # UPLOAD TO GLOBAL CLOUDINARY CONFIGURATION
    # ========================================================

    try:

        result = cloudinary.uploader.upload(

            file,

            folder=folder,

            resource_type="image",

            use_filename=True,

            unique_filename=True,

            overwrite=False,

            transformation=[
                {
                    "quality": "auto",
                    "fetch_format": "auto"
                }
            ]
        )


    except Exception as e:

        raise RuntimeError(
            f"Cloudinary upload failed: {str(e)}"
        )


    # ========================================================
    # GET SECURE URL
    # ========================================================

    secure_url = result.get(
        "secure_url"
    )


    if not secure_url:

        raise RuntimeError(
            "Cloudinary upload completed but no secure URL was returned."
        )


    return secure_url


# ============================================================
# ADD BRANCH
# ============================================================

@bp.route(
    "/add-branch",
    methods=["GET", "POST"]
)
@login_required
def add_branch():

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:

        flash(
            "Authentication required.",
            "danger"
        )

        return redirect(
            url_for("main.login")
        )


    if not current_user.is_superadmin():

        flash(
            "You do not have permission to access this page.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # LOAD INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM DATA
        # ====================================================

        institution_id_raw = request.form.get(
            "institution_id",
            "",
            type=str
        ).strip()


        name = request.form.get(
            "name",
            "",
            type=str
        ).strip()


        code = request.form.get(
            "code",
            "",
            type=str
        ).strip()


        phone = request.form.get(
            "phone",
            "",
            type=str
        ).strip()


        email = request.form.get(
            "email",
            "",
            type=str
        ).strip()


        address = request.form.get(
            "address",
            "",
            type=str
        ).strip()


        city = request.form.get(
            "city",
            "",
            type=str
        ).strip()


        status = request.form.get(
            "status",
            "active",
            type=str
        ).strip().lower()


        description = request.form.get(
            "description",
            "",
            type=str
        ).strip()


        # ====================================================
        # FILE DATA
        # IMPORTANT:
        # Images come from request.files
        # ====================================================

        main_logo_file = request.files.get(
            "main_logo"
        )


        sub_logo_file = request.files.get(
            "sub_logo"
        )


        signature_photo_file = request.files.get(
            "signature_photo"
        )


        # ====================================================
        # VALIDATE REQUIRED FIELDS
        # ====================================================

        if not institution_id_raw:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        if not name:

            flash(
                "Branch name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        if not code:

            flash(
                "Branch code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CONVERT INSTITUTION ID
        # ====================================================

        try:

            institution_id = int(
                institution_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Invalid institution selected.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CHECK INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )


        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # NORMALIZE CODE
        # ====================================================

        code = code.upper()


        # ====================================================
        # VALID STATUS
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "suspended"
        }


        if status not in allowed_statuses:

            status = "active"


        # ====================================================
        # DUPLICATE BRANCH CODE
        #
        # Branch.code is globally UNIQUE
        # ====================================================

        existing_code = (
            Branch.query
            .filter(
                db.func.lower(
                    Branch.code
                ) == code.lower()
            )
            .first()
        )


        if existing_code:

            flash(
                "A branch with this code already exists.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # DUPLICATE BRANCH NAME
        #
        # Same institution cannot have same branch name
        # ====================================================

        existing_name = (
            Branch.query
            .filter(
                Branch.institution_id == institution_id,
                db.func.lower(
                    Branch.name
                ) == name.lower()
            )
            .first()
        )


        if existing_name:

            flash(
                "A branch with this name already exists in this institution.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CLOUDINARY UPLOADS
        # ====================================================

        main_logo_url = None
        sub_logo_url = None
        signature_photo_url = None


        try:

            # ------------------------------------------------
            # MAIN LOGO
            # ------------------------------------------------

            if (
                main_logo_file
                and main_logo_file.filename
            ):

                main_logo_url = upload_branch_image(
                    main_logo_file,
                    folder="branches/main_logos"
                )


            # ------------------------------------------------
            # SUB LOGO
            # ------------------------------------------------

            if (
                sub_logo_file
                and sub_logo_file.filename
            ):

                sub_logo_url = upload_branch_image(
                    sub_logo_file,
                    folder="branches/sub_logos"
                )


            # ------------------------------------------------
            # SIGNATURE
            # ------------------------------------------------

            if (
                signature_photo_file
                and signature_photo_file.filename
            ):

                signature_photo_url = upload_branch_image(
                    signature_photo_file,
                    folder="branches/signatures"
                )


        except ValueError as e:

            flash(
                str(e),
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        except Exception as e:

            flash(
                f"Unable to upload branch image: {str(e)}",
                "danger"
            )

            return render_template(
                "backend/pages/branches/add_branch.html",
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CREATE BRANCH
        # ====================================================

        branch = Branch(

            institution_id=institution_id,

            name=name,

            code=code,

            phone=phone or None,

            email=email or None,

            address=address or None,

            city=city or None,

            main_logo=main_logo_url,

            sub_logo=sub_logo_url,

            signature_photo=signature_photo_url,

            status=status,

            description=description or None
        )


        # ====================================================
        # SAVE DATABASE
        # ====================================================

        try:

            db.session.add(
                branch
            )

            db.session.commit()


            flash(
                f"Branch '{branch.name}' has been created successfully.",
                "success"
            )


            return redirect(
                url_for(
                    "main.all_branches"
                )
            )


        # ====================================================
        # DATABASE INTEGRITY ERROR
        # ====================================================

        except IntegrityError:

            db.session.rollback()


            flash(
                "Unable to create branch because one of the unique values already exists.",
                "danger"
            )


        # ====================================================
        # GENERAL ERROR
        # ====================================================

        except Exception as e:

            db.session.rollback()


            flash(
                f"Unable to create branch: {str(e)}",
                "danger"
            )


    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/branches/add_branch.html",
        institutions=institutions,
        user=current_user
    )

