# ============================================================
# EDIT BRANCH
# ============================================================

@bp.route(
    "/edit-branch/<int:branch_id>",
    methods=["GET", "POST"]
)
@login_required
def edit_branch(branch_id):

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:

        flash(
            "Authentication required.",
            "danger"
        )

        return redirect(
            url_for("main.login")
        )


    if not current_user.is_superadmin():

        flash(
            "You do not have permission to access this page.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # GET BRANCH
    # ========================================================

    branch = (
        Branch.query
        .filter(
            Branch.id == branch_id
        )
        .first()
    )


    if not branch:

        flash(
            "Branch not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_branches")
        )


    # ========================================================
    # LOAD INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM DATA
        # ====================================================

        institution_id_raw = request.form.get(
            "institution_id",
            "",
            type=str
        ).strip()


        name = request.form.get(
            "name",
            "",
            type=str
        ).strip()


        code = request.form.get(
            "code",
            "",
            type=str
        ).strip()


        phone = request.form.get(
            "phone",
            "",
            type=str
        ).strip()


        email = request.form.get(
            "email",
            "",
            type=str
        ).strip()


        address = request.form.get(
            "address",
            "",
            type=str
        ).strip()


        city = request.form.get(
            "city",
            "",
            type=str
        ).strip()


        status = request.form.get(
            "status",
            "active",
            type=str
        ).strip().lower()


        description = request.form.get(
            "description",
            "",
            type=str
        ).strip()


        # ====================================================
        # FILE DATA
        #
        # IMPORTANT:
        # Images are uploaded through request.files
        # ====================================================

        main_logo_file = request.files.get(
            "main_logo"
        )


        sub_logo_file = request.files.get(
            "sub_logo"
        )


        signature_photo_file = request.files.get(
            "signature_photo"
        )


        # ====================================================
        # REQUIRED FIELD VALIDATION
        # ====================================================

        if not institution_id_raw:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        if not name:

            flash(
                "Branch name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        if not code:

            flash(
                "Branch code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # INSTITUTION ID
        # ====================================================

        try:

            institution_id = int(
                institution_id_raw
            )

        except (
            ValueError,
            TypeError
        ):

            flash(
                "Invalid institution selected.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # CHECK INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )


        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # NORMALIZE CODE
        # ====================================================

        code = code.upper()


        # ====================================================
        # VALID STATUS
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "suspended"
        }


        if status not in allowed_statuses:

            status = "active"


        # ====================================================
        # DUPLICATE CODE
        #
        # Branch.code is globally UNIQUE
        #
        # Exclude current branch
        # ====================================================

        existing_code = (
            Branch.query
            .filter(
                db.func.lower(
                    Branch.code
                ) == code.lower(),

                Branch.id != branch.id
            )
            .first()
        )


        if existing_code:

            flash(
                "A branch with this code already exists.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # DUPLICATE NAME
        #
        # Same institution cannot have same name
        #
        # Exclude current branch
        # ====================================================

        existing_name = (
            Branch.query
            .filter(
                Branch.institution_id == institution_id,

                db.func.lower(
                    Branch.name
                ) == name.lower(),

                Branch.id != branch.id
            )
            .first()
        )


        if existing_name:

            flash(
                "A branch with this name already exists in this institution.",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # NEW IMAGE URLS
        #
        # Existing images are preserved by default.
        # ====================================================

        new_main_logo = None
        new_sub_logo = None
        new_signature_photo = None


        # ====================================================
        # CLOUDINARY UPLOADS
        # ====================================================

        try:

            # ------------------------------------------------
            # MAIN LOGO
            # ------------------------------------------------

            if (
                main_logo_file
                and main_logo_file.filename
            ):

                new_main_logo = upload_branch_image(
                    main_logo_file,
                    folder="branches/main_logos"
                )


            # ------------------------------------------------
            # SUB LOGO
            # ------------------------------------------------

            if (
                sub_logo_file
                and sub_logo_file.filename
            ):

                new_sub_logo = upload_branch_image(
                    sub_logo_file,
                    folder="branches/sub_logos"
                )


            # ------------------------------------------------
            # SIGNATURE PHOTO
            # ------------------------------------------------

            if (
                signature_photo_file
                and signature_photo_file.filename
            ):

                new_signature_photo = upload_branch_image(
                    signature_photo_file,
                    folder="branches/signatures"
                )


        except ValueError as e:

            flash(
                str(e),
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        except Exception as e:

            flash(
                f"Unable to upload branch image: {str(e)}",
                "danger"
            )

            return render_template(
                "backend/pages/branches/edit_branch.html",
                branch=branch,
                institutions=institutions,
                user=current_user
            )


        # ====================================================
        # UPDATE BRANCH DATA
        # ====================================================

        branch.institution_id = institution_id

        branch.name = name

        branch.code = code

        branch.phone = phone or None

        branch.email = email or None

        branch.address = address or None

        branch.city = city or None

        branch.status = status

        branch.description = (
            description
            or None
        )


        # ====================================================
        # UPDATE MAIN LOGO
        #
        # If a new image was uploaded:
        # replace old URL.
        #
        # If no new image:
        # keep existing URL.
        # ====================================================

        if new_main_logo:

            branch.main_logo = (
                new_main_logo
            )


        # ====================================================
        # UPDATE SUB LOGO
        # ====================================================

        if new_sub_logo:

            branch.sub_logo = (
                new_sub_logo
            )


        # ====================================================
        # UPDATE SIGNATURE PHOTO
        # ====================================================

        if new_signature_photo:

            branch.signature_photo = (
                new_signature_photo
            )


        # ====================================================
        # SAVE
        # ========================================================

        try:

            db.session.commit()


            flash(
                f"Branch '{branch.name}' has been updated successfully.",
                "success"
            )


            return redirect(
                url_for(
                    "main.view_branch",
                    branch_id=branch.id
                )
            )


        # ====================================================
        # INTEGRITY ERROR
        # ====================================================

        except IntegrityError:

            db.session.rollback()


            flash(
                "Unable to update branch because one of the unique values already exists.",
                "danger"
            )


        # ====================================================
        # GENERAL ERROR
        # ====================================================

        except Exception as e:

            db.session.rollback()


            flash(
                f"Unable to update branch: {str(e)}",
                "danger"
            )


    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/branches/edit_branch.html",
        branch=branch,
        institutions=institutions,
        user=current_user
    )


# ============================================================
# DELETE BRANCH
# ============================================================

@bp.route(
    "/delete-branch/<int:branch_id>",
    methods=["POST"]
)
@login_required
def delete_branch(branch_id):

    # --------------------------------------------------------
    # SUPERADMIN ONLY
    # --------------------------------------------------------

    if not current_user.is_authenticated:

        return jsonify({
            "success": False,
            "message": "Authentication required."
        }), 401


    if not current_user.is_superadmin():

        return jsonify({
            "success": False,
            "message": "You do not have permission to delete branches."
        }), 403


    # --------------------------------------------------------
    # GET BRANCH
    # --------------------------------------------------------

    branch = Branch.query.get(
        branch_id
    )


    if not branch:

        return jsonify({
            "success": False,
            "message": "Branch not found."
        }), 404


    # --------------------------------------------------------
    # SAVE NAME FOR RESPONSE
    # --------------------------------------------------------

    branch_name = branch.name


    # --------------------------------------------------------
    # DELETE
    # --------------------------------------------------------

    try:

        db.session.delete(
            branch
        )

        db.session.commit()


        return jsonify({
            "success": True,
            "message": (
                f"Branch '{branch_name}' "
                "has been deleted successfully."
            )
        }), 200


    except IntegrityError:

        db.session.rollback()


        return jsonify({
            "success": False,
            "message": (
                "This branch cannot be deleted because "
                "related records still depend on it."
            )
        }), 409


    except Exception as e:

        db.session.rollback()


        return jsonify({
            "success": False,
            "message": (
                f"Unable to delete branch: {str(e)}"
            )
        }), 500


# ============================================================
# ALL ACADEMIC YEARS
# ============================================================

@bp.route(
    "/all-academic-years",
    methods=["GET"]
)
@login_required
def all_academic_years():

    # ========================================================
    # SUPERADMIN ONLY
    # ========================================================

    if not current_user.is_authenticated:

        flash(
            "Authentication required.",
            "danger"
        )

        return redirect(
            url_for("main.login")
        )


    # ========================================================
    # ACCESS CONTROL
    # SUPERADMIN + INSTITUTION ADMIN
    # ========================================================

    is_superadmin = current_user.is_superadmin()

    is_institution_admin = (
        hasattr(current_user, "is_institution_admin")
        and current_user.is_institution_admin()
    )

    if not is_superadmin and not is_institution_admin:

        flash(
            "You do not have permission to delete programs.",
            "danger"
        )

        return redirect(
            url_for("main.all_programs")
        )


    # ========================================================
    # QUERY PARAMETERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()


    selected_status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()


    selected_institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()


    selected_current = request.args.get(
        "is_current",
        "",
        type=str
    ).strip().lower()


    # ========================================================
    # PER PAGE
    # ========================================================

    allowed_per_page = {
        10,
        25,
        50,
        100
    }


    try:

        per_page = int(
            request.args.get(
                "per_page",
                25
            )
        )

    except (
        ValueError,
        TypeError
    ):

        per_page = 25


    if per_page not in allowed_per_page:

        per_page = 25


    # ========================================================
    # PAGE
    # ========================================================

    try:

        page = int(
            request.args.get(
                "page",
                1
            )
        )

    except (
        ValueError,
        TypeError
    ):

        page = 1


    if page < 1:

        page = 1


    # ========================================================
    # BASE QUERY
    # ========================================================

    query = AcademicYear.query


    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )


        query = query.filter(

            db.or_(

                AcademicYear.name.ilike(
                    search_pattern
                ),

                AcademicYear.code.ilike(
                    search_pattern
                ),

                AcademicYear.description.ilike(
                    search_pattern
                )

            )

        )


    # ========================================================
    # STATUS FILTER
    # ========================================================

    allowed_statuses = {
        "active",
        "inactive",
        "closed"
    }


    if selected_status in allowed_statuses:

        query = query.filter(
            AcademicYear.status ==
            selected_status
        )

    else:

        selected_status = ""


    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    institution_filter_id = None


    if selected_institution_id:

        try:

            institution_filter_id = int(
                selected_institution_id
            )

        except (
            ValueError,
            TypeError
        ):

            institution_filter_id = None


        if institution_filter_id:

            query = query.filter(
                AcademicYear.institution_id ==
                institution_filter_id
            )

        else:

            selected_institution_id = ""


    # ========================================================
    # CURRENT YEAR FILTER
    # ========================================================

    if selected_current == "current":

        query = query.filter(
            AcademicYear.is_current.is_(True)
        )

    elif selected_current == "not_current":

        query = query.filter(
            AcademicYear.is_current.is_(False)
        )

    else:

        selected_current = ""


    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(

        AcademicYear.is_current.desc(),

        AcademicYear.start_date.desc(),

        AcademicYear.created_at.desc(),

        AcademicYear.id.desc()

    )


    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(

        page=page,

        per_page=per_page,

        error_out=False

    )


    academic_years = pagination.items


    # ========================================================
    # INSTITUTIONS
    # ========================================================

    institutions = (
        Institution.query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )


    # ========================================================
    # STATISTICS
    # ========================================================

    total_academic_years = (
        AcademicYear.query.count()
    )


    active_academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.status == "active"
        )
        .count()
    )


    inactive_academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.status == "inactive"
        )
        .count()
    )


    closed_academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.status == "closed"
        )
        .count()
    )


    current_academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.is_current.is_(True)
        )
        .count()
    )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/academic_years/all_academic_years.html",

        academic_years=academic_years,

        pagination=pagination,

        institutions=institutions,

        search=search,

        selected_status=selected_status,

        selected_institution_id=selected_institution_id,

        selected_current=selected_current,

        per_page=per_page,

        total_academic_years=total_academic_years,

        active_academic_years=active_academic_years,

        inactive_academic_years=inactive_academic_years,

        closed_academic_years=closed_academic_years,

        current_academic_years=current_academic_years,

        user=current_user

    )


