@bp.route(
    "/sections/add",
    methods=["GET", "POST"]
)
@login_required
def add_section():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = _get_user_institution_id()

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # GET FORM DATA
    # ========================================================

    (
        institutions,
        branches,
        classes,
        academic_years,
    ) = _get_section_form_data()

    # ========================================================
    # FORM DATA SECURITY
    # ========================================================

    if role == "branch_admin":

        institutions = [
            institution
            for institution in institutions
            if institution.id
            == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if branch.id
            == user_branch_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if (
                class_obj.institution_id
                == user_institution_id
                and class_obj.branch_id
                == user_branch_id
            )
        ]

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    elif role == "school_admin":

        institutions = [
            institution
            for institution in institutions
            if institution.id
            == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if branch.institution_id
            == user_institution_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if class_obj.institution_id
            == user_institution_id
        ]

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ----------------------------------------------------
        # FORM VALUES
        # ----------------------------------------------------

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        class_id = request.form.get(
            "class_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        name = (
            request.form.get(
                "name",
                ""
            )
            .strip()
        )

        capacity_raw = (
            request.form.get(
                "capacity",
                ""
            )
            .strip()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "active"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        if not branch_id:

            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        if not class_id:

            flash(
                "Please select a class.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        if not academic_year_id:

            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        if not name:

            flash(
                "Section name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # INSTITUTION SECURITY
        # ====================================================

        if role != "superadmin":

            if user_institution_id is None:

                abort(403)

            if institution_id != user_institution_id:

                flash(
                    "You are not allowed to use another institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=user_institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

        # ====================================================
        # BRANCH SECURITY
        # ====================================================

        if role == "branch_admin":

            if user_branch_id is None:
                abort(403)

            if branch_id != user_branch_id:

                flash(
                    "You are not allowed to use another branch.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=user_institution_id,
                        branch_id=user_branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

        # ====================================================
        # NAME LENGTH
        # ====================================================

        if len(name) > 150:

            flash(
                "Section name cannot exceed 150 characters.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # DESCRIPTION LENGTH
        # ====================================================

        if len(description) > 1000:

            flash(
                "Description cannot exceed 1000 characters.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "suspended",
        }

        if status not in allowed_statuses:

            flash(
                "Invalid section status.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status="active",
                )
            )

        # ====================================================
        # CAPACITY
        # ====================================================

        capacity = None

        if capacity_raw:

            try:

                capacity = int(
                    capacity_raw
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Capacity must be a valid whole number.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

            if capacity < 0:

                flash(
                    "Capacity cannot be negative.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

            # Optional reasonable upper limit
            if capacity > 10000:

                flash(
                    "Capacity cannot exceed 10,000 students.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

        # ====================================================
        # INSTITUTION VALIDATION
        # ====================================================

        institution = Institution.query.filter(
            Institution.id == institution_id
        ).first()

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # BRANCH VALIDATION
        # ====================================================

        branch = Branch.query.filter(
            Branch.id == branch_id
        ).first()

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # Branch must belong to institution

        if branch.institution_id != institution_id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # CLASS VALIDATION
        # ====================================================

        class_obj = Class.query.filter(
            Class.id == class_id
        ).first()

        if not class_obj:

            flash(
                "Selected class was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ----------------------------------------------------
        # Class institution
        # ----------------------------------------------------

        if class_obj.institution_id != institution_id:

            flash(
                "Selected class does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ----------------------------------------------------
        # Class branch
        # ----------------------------------------------------

        if class_obj.branch_id != branch_id:

            flash(
                "Selected class does not belong to the selected branch.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # EXTRA BRANCH SECURITY
        # ====================================================

        if role == "branch_admin":

            if class_obj.branch_id != user_branch_id:

                abort(403)

        # ====================================================
        # ACADEMIC YEAR VALIDATION
        # ====================================================

        academic_year = AcademicYear.query.filter(
            AcademicYear.id == academic_year_id
        ).first()

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # ACADEMIC YEAR INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution_id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

        # ====================================================
        # CLASS / ACADEMIC YEAR MATCH
        # ====================================================

        if hasattr(
            Class,
            "academic_year_id"
        ):

            if (
                class_obj.academic_year_id
                != academic_year_id
            ):

                flash(
                    "Selected class does not belong to the selected academic year.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/add_section.html",
                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    )
                )

        # ====================================================
        # AUTO GENERATE CODE
        # ====================================================

        code = generate_section_code(
            name
        )

        if not code:

            flash(
                "Unable to generate section code from the section name.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # DUPLICATE NAME CHECK
        # ====================================================

        existing_section = Section.query.filter(
            Section.institution_id == institution_id,
            Section.branch_id == branch_id,
            Section.class_id == class_id,
            Section.academic_year_id == academic_year_id,
            func.lower(
                Section.name
            ) == name.lower()
        ).first()

        if existing_section:

            flash(
                "A section with this name already exists for the selected class and academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # DUPLICATE CODE CHECK
        # ====================================================

        existing_code = Section.query.filter(
            Section.institution_id == institution_id,
            Section.branch_id == branch_id,
            Section.class_id == class_id,
            Section.academic_year_id == academic_year_id,
            func.upper(
                Section.code
            ) == code.upper()
        ).first()

        if existing_code:

            flash(
                f"The generated section code '{code}' already exists for this class and academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # CREATE SECTION
        # ====================================================

        section = Section(
            institution_id=institution_id,
            branch_id=branch_id,
            class_id=class_id,
            academic_year_id=academic_year_id,
            name=name,
            code=code,
            capacity=capacity,
            description=description or None,
            status=status,
        )

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                section
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Error creating section: %s",
                exc
            )

            flash(
                "An error occurred while creating the section. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/add_section.html",
                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f"Section '{section.name}' ({section.code}) was created successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.view_section",
                section_id=section.id
            )
        )

    # ========================================================
    # GET DEFAULT VALUES
    # ========================================================

    default_institution_id = (
        user_institution_id
    )

    # --------------------------------------------------------
    # Superadmin with only one institution
    # --------------------------------------------------------

    if (
        default_institution_id is None
        and len(institutions) == 1
    ):

        default_institution_id = (
            institutions[0].id
        )

    # --------------------------------------------------------
    # Branch admin default branch
    # --------------------------------------------------------

    default_branch_id = None

    if role == "branch_admin":

        default_branch_id = (
            user_branch_id
        )

    # ========================================================
    # RENDER GET
    # ========================================================

    return render_template(
        "backend/pages/sections/add_section.html",

        **_section_template_context(
            institution_id=default_institution_id,
            branch_id=default_branch_id,
            class_id=None,
            academic_year_id=None,
            name="",
            capacity="",
            description="",
            status="active",
        ),

        # ----------------------------------------------------
        # Extra security/template information
        # ----------------------------------------------------

        current_role=role,

        user=current_user,

        user_institution_id=(
            user_institution_id
        ),

        user_branch_id=(
            user_branch_id
        ),
    )


# ============================================================
# VIEW SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>",
    methods=["GET"]
)
@login_required
def view_section(section_id):

    section = _get_section_or_404(
        section_id
    )

    return render_template(
        "backend/pages/sections/view_section.html",

        section=section,

        # IMPORTANT
        user=current_user,
    )


# ============================================================
# EDIT SECTION
# ============================================================
# ============================================================
# EDIT SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_section(section_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = (
        _section_user_institution_id()
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # ROLE REQUIREMENTS
    # ========================================================

    if role == "school_admin":

        if user_institution_id is None:
            abort(403)

    if role == "branch_admin":

        if (
            user_institution_id is None
            or user_branch_id is None
        ):
            abort(403)

    # ========================================================
    # GET SECTION
    # ========================================================

    section = _get_section_or_404(
        section_id
    )

    # ========================================================
    # EXISTING SECTION SECURITY
    # ========================================================

    # --------------------------------------------------------
    # Institution security
    # --------------------------------------------------------

    if role != "superadmin":

        if (
            user_institution_id is None
            or section.institution_id
            != user_institution_id
        ):

            abort(403)

    # --------------------------------------------------------
    # Branch security
    # --------------------------------------------------------

    if role == "branch_admin":

        if (
            section.branch_id
            != user_branch_id
        ):

            abort(403)

    # ========================================================
    # FORM DATA
    # ========================================================

    (
        institutions,
        branches,
        classes,
        academic_years,
    ) = _get_section_form_data()

    # ========================================================
    # FORM DATA SECURITY
    # ========================================================

    if role == "branch_admin":

        institutions = [
            institution
            for institution in institutions
            if institution.id
            == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if branch.id
            == user_branch_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if (
                class_obj.institution_id
                == user_institution_id
                and class_obj.branch_id
                == user_branch_id
            )
        ]

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    elif role == "school_admin":

        institutions = [
            institution
            for institution in institutions
            if institution.id
            == user_institution_id
        ]

        branches = [
            branch
            for branch in branches
            if branch.institution_id
            == user_institution_id
        ]

        classes = [
            class_obj
            for class_obj in classes
            if class_obj.institution_id
            == user_institution_id
        ]

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years = [
                academic_year
                for academic_year in academic_years
                if academic_year.institution_id
                == user_institution_id
            ]

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        class_id = request.form.get(
            "class_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        name = (
            request.form.get(
                "name",
                "",
                type=str
            )
            .strip()
        )

        capacity_raw = (
            request.form.get(
                "capacity",
                "",
                type=str
            )
            .strip()
        )

        description = (
            request.form.get(
                "description",
                "",
                type=str
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "active",
                type=str
            )
            .strip()
            .lower()
        )

        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if not institution_id:

            flash(
                "Institution is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        if not branch_id:

            flash(
                "Branch is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        if not class_id:

            flash(
                "Class is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        if not academic_year_id:

            flash(
                "Academic year is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        if not name:

            flash(
                "Section name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # NAME LENGTH
        # ====================================================

        if len(name) > 150:

            flash(
                "Section name cannot exceed 150 characters.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # DESCRIPTION LENGTH
        # ====================================================

        if len(description) > 1000:

            flash(
                "Description cannot exceed 1000 characters.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # INSTITUTION SECURITY
        # ====================================================

        if role != "superadmin":

            if institution_id != user_institution_id:

                flash(
                    "You are not allowed to move this section to another institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=user_institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

        # ====================================================
        # BRANCH ADMIN CANNOT MOVE SECTION
        # ====================================================

        if role == "branch_admin":

            if branch_id != user_branch_id:

                flash(
                    "You are not allowed to move this section to another branch.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=user_institution_id,
                        branch_id=user_branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

        # ====================================================
        # STATUS
        # ====================================================

        allowed_statuses = {
            "active",
            "inactive",
            "suspended",
        }

        if status not in allowed_statuses:

            flash(
                "Invalid section status.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status="active",
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # CAPACITY
        # ====================================================

        capacity = None

        if capacity_raw:

            try:

                capacity = int(
                    capacity_raw
                )

            except (
                ValueError,
                TypeError
            ):

                flash(
                    "Capacity must be a valid whole number.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

            if capacity < 0:

                flash(
                    "Capacity cannot be negative.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

            if capacity > 10000:

                flash(
                    "Capacity cannot exceed 10,000 students.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

        # ====================================================
        # INSTITUTION VALIDATION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # BRANCH VALIDATION
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution_id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # CLASS VALIDATION
        # ====================================================

        class_obj = (
            Class.query
            .filter(
                Class.id == class_id
            )
            .first()
        )

        if not class_obj:

            flash(
                "Selected class was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # CLASS → INSTITUTION
        # ====================================================

        if class_obj.institution_id != institution_id:

            flash(
                "Selected class does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # CLASS → BRANCH
        # ====================================================

        if class_obj.branch_id != branch_id:

            flash(
                "Selected class does not belong to the selected branch.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # BRANCH ADMIN CLASS SECURITY
        # ====================================================

        if role == "branch_admin":

            if class_obj.branch_id != user_branch_id:

                abort(403)

        # ====================================================
        # ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution_id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

        # ====================================================
        # CLASS → ACADEMIC YEAR
        # ====================================================

        if hasattr(
            Class,
            "academic_year_id"
        ):

            if (
                class_obj.academic_year_id
                != academic_year_id
            ):

                flash(
                    "Selected class belongs to a different academic year.",
                    "danger"
                )

                return render_template(
                    "backend/pages/sections/edit_section.html",

                    section=section,

                    **_section_template_context(
                        institution_id=institution_id,
                        branch_id=branch_id,
                        class_id=class_id,
                        academic_year_id=academic_year_id,
                        name=name,
                        capacity=capacity_raw,
                        description=description,
                        status=status,
                    ),

                    user=current_user,
                    current_role=role,
                    user_institution_id=user_institution_id,
                    user_branch_id=user_branch_id,
                )

        # ====================================================
        # AUTO GENERATE CODE
        # ====================================================

        code = generate_section_code(
            name
        )

        if not code:

            flash(
                "Unable to generate section code.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # DUPLICATE NAME
        # ====================================================

        existing_name = (
            Section.query
            .filter(
                Section.institution_id
                == institution_id,

                Section.branch_id
                == branch_id,

                Section.class_id
                == class_id,

                Section.academic_year_id
                == academic_year_id,

                func.lower(
                    Section.name
                )
                == name.lower(),

                Section.id
                != section.id,
            )
            .first()
        )

        if existing_name:

            flash(
                "Another section with this name already exists in this class and academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # DUPLICATE CODE
        # ====================================================

        existing_code = (
            Section.query
            .filter(
                Section.institution_id
                == institution_id,

                Section.branch_id
                == branch_id,

                Section.class_id
                == class_id,

                Section.academic_year_id
                == academic_year_id,

                func.upper(
                    Section.code
                )
                == code.upper(),

                Section.id
                != section.id,
            )
            .first()
        )

        if existing_code:

            flash(
                f"Another section with code '{code}' already exists in this class and academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # UPDATE
        # ====================================================

        section.institution_id = (
            institution_id
        )

        section.branch_id = (
            branch_id
        )

        section.class_id = (
            class_id
        )

        section.academic_year_id = (
            academic_year_id
        )

        section.name = name

        section.code = code

        section.capacity = capacity

        section.description = (
            description or None
        )

        section.status = status

        # ====================================================
        # COMMIT
        # ====================================================

        try:

            db.session.commit()

        except IntegrityError:

            db.session.rollback()

            current_app.logger.exception(
                "Integrity error updating section %s",
                section.id
            )

            flash(
                "Unable to update section because of a database constraint or duplicate value.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Error updating section %s: %s",
                section.id,
                exc
            )

            flash(
                "An error occurred while updating the section. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/sections/edit_section.html",

                section=section,

                **_section_template_context(
                    institution_id=institution_id,
                    branch_id=branch_id,
                    class_id=class_id,
                    academic_year_id=academic_year_id,
                    name=name,
                    capacity=capacity_raw,
                    description=description,
                    status=status,
                ),

                user=current_user,
                current_role=role,
                user_institution_id=user_institution_id,
                user_branch_id=user_branch_id,
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f'Section "{section.name}" ({section.code}) was updated successfully.',
            "success"
        )

        return redirect(
            url_for(
                "main.view_section",
                section_id=section.id
            )
        )

    # ========================================================
    # GET DEFAULT VALUES
    # ========================================================

    return render_template(
        "backend/pages/sections/edit_section.html",

        section=section,

        **_section_template_context(
            institution_id=section.institution_id,
            branch_id=section.branch_id,
            class_id=section.class_id,
            academic_year_id=section.academic_year_id,
            name=section.name,
            capacity=(
                section.capacity
                if section.capacity is not None
                else ""
            ),
            description=(
                section.description
                or ""
            ),
            status=(
                section.status
                or "active"
            ),
        ),

        user=current_user,

        current_role=role,

        user_institution_id=(
            user_institution_id
        ),

        user_branch_id=(
            user_branch_id
        ),
    )

# ============================================================
# DELETE SECTION
# ============================================================

@bp.route(
    "/sections/<int:section_id>/delete",
    methods=["POST"]
)
@login_required
def delete_section(section_id):

    section = _get_section_or_404(
        section_id
    )

    section_name = section.name

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            section
        )

        db.session.commit()

    except IntegrityError:

        db.session.rollback()

        flash(
            (
                f'Unable to delete section "{section_name}". '
                "This section may already be connected to "
                "other academic records. Please set it to "
                "inactive instead."
            ),
            "danger"
        )

        return redirect(
            url_for(
                "main.view_section",
                section_id=section.id
            )
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        f'Section "{section_name}" was deleted successfully.',
        "success"
    )

    return redirect(
        url_for(
            "main.all_sections"
        )
    )



# ============================================================
# SUBJECT ROUTES
# PostgreSQL / Neon
# ============================================================


# ============================================================
# SUBJECT CONSTANTS
# ============================================================

SUBJECT_TYPES = [
    "academic",
    "practical",
    "language",
    "religious",
    "vocational",
    "elective",
    "compulsory",
    "skill",
]

SUBJECT_STATUSES = [
    "active",
    "inactive",
    "suspended",
]


# ============================================================
# USER / INSTITUTION HELPERS
# ============================================================

def _subject_is_global_user():
    """
    Returns True when the current user is allowed to
    manage data across all institutions.
    """

    role = (
        getattr(current_user, "role", None)
        or ""
    ).lower().strip()

    return role in {
        "superadmin",
        "super_admin",
        "admin",
        "system_admin",
    }


def _subject_get_user_institution_id():
    """
    Returns the institution ID belonging to the current user.

    Global users return None.
    """

    if _subject_is_global_user():
        return None

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    if institution_id is None:
        return None

    try:
        return int(institution_id)
    except (TypeError, ValueError):
        return None


def _subject_get_user_branch_id():
    """
    Returns the user's branch ID when available.
    """

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if branch_id is None:
        return None

    try:
        return int(branch_id)
    except (TypeError, ValueError):
        return None


def _subject_can_manage_global():
    """
    Determines whether the user can see/manage subjects
    belonging to all branches of their institution.

    Institution admins generally can manage all branches.
    Branch admins are restricted to their branch.
    """

    role = (
        getattr(current_user, "role", None)
        or ""
    ).lower().strip()

    return role in {
        "superadmin",
        "super_admin",
        "admin",
        "system_admin",
        "institution_admin",
    }


# ============================================================
# SUBJECT SCOPE
# ============================================================

def _subject_scope_query(query):
    """
    Apply institution/branch security to a Subject query.

    Global users:
        all institutions.

    Institution admins:
        only their institution.

    Branch admins / teachers:
        their institution + branch.

    Other scoped users:
        their institution and, when available, branch.
    """

    institution_id = _subject_get_user_institution_id()

    # Global user
    if institution_id is None:
        return query

    query = query.filter(
        Subject.institution_id == institution_id
    )

    # Institution-level administrators can manage
    # all branches inside their institution.
    if _subject_can_manage_global():
        return query

    branch_id = _subject_get_user_branch_id()

    if branch_id is not None:
        query = query.filter(
            Subject.branch_id == branch_id
        )

    return query


# ============================================================
# GET ALLOWED INSTITUTIONS
# ============================================================

def _subject_allowed_institutions():
    """
    Returns institutions available to current user.
    """

    institution_id = _subject_get_user_institution_id()

    if institution_id is None:

        return (
            Institution.query
            .order_by(Institution.name.asc())
            .all()
        )

    institution = Institution.query.get(
        institution_id
    )

    if institution:
        return [institution]

    return []


# ============================================================
# GET ALLOWED BRANCHES
# ============================================================

def _subject_allowed_branches(
    institution_id=None
):
    """
    Returns branches available to current user.

    Optional institution_id filters branches further.
    """

    query = Branch.query

    user_institution_id = (
        _subject_get_user_institution_id()
    )

    if user_institution_id is not None:

        query = query.filter(
            Branch.institution_id ==
            user_institution_id
        )

    elif institution_id is not None:

        query = query.filter(
            Branch.institution_id ==
            institution_id
        )


    # Branch-scoped users
    if not _subject_can_manage_global():

        user_branch_id = (
            _subject_get_user_branch_id()
        )

        if user_branch_id is not None:

            query = query.filter(
                Branch.id == user_branch_id
            )


    return (
        query
        .order_by(Branch.name.asc())
        .all()
    )


# ============================================================
# GET ALLOWED PROGRAMS
# ============================================================

def _subject_allowed_programs(
    institution_id=None
):
    """
    Returns programs available for subject assignment.
    """

    query = Program.query

    user_institution_id = (
        _subject_get_user_institution_id()
    )

    if user_institution_id is not None:

        query = query.filter(
            Program.institution_id ==
            user_institution_id
        )

    elif institution_id is not None:

        query = query.filter(
            Program.institution_id ==
            institution_id
        )

    return (
        query
        .order_by(Program.name.asc())
        .all()
    )


# ============================================================
# SUBJECT FORM CONTEXT
# ============================================================

def _subject_form_context(
    institution_id=None
):
    """
    Common context used by add/edit templates.
    """

    institutions = (
        _subject_allowed_institutions()
    )

    branches = (
        _subject_allowed_branches(
            institution_id=institution_id
        )
    )

    programs = (
        _subject_allowed_programs(
            institution_id=institution_id
        )
    )

    return {
        "institutions": institutions,
        "branches": branches,
        "programs": programs,
        "subject_types": SUBJECT_TYPES,
        "subject_statuses": SUBJECT_STATUSES,
        "user": current_user,
    }


# ============================================================
# PARSE DECIMAL
# ============================================================

def _subject_parse_decimal(
    value,
    field_name,
    errors,
    allow_empty=True
):
    """
    Safely parse Decimal values.
    """

    value = (
        str(value).strip()
        if value is not None
        else ""
    )

    if not value:

        if allow_empty:
            return None

        errors[field_name] = (
            f"{field_name.replace('_', ' ').title()} "
            "is required."
        )

        return None

    try:

        return Decimal(value)

    except (InvalidOperation, ValueError):

        errors[field_name] = (
            f"Invalid {field_name.replace('_', ' ')}."
        )

        return None


# ============================================================
# VALIDATE SUBJECT RELATIONSHIPS
# ============================================================

def _validate_subject_relationships(
    institution_id,
    branch_id,
    program_id,
    errors
):
    """
    Validates institution, branch and program relationships.
    """

    institution = None
    branch = None
    program = None


    # --------------------------------------------------------
    # Institution
    # --------------------------------------------------------

    if not institution_id:

        errors["institution_id"] = (
            "Institution is required."
        )

    else:

        try:
            institution_id = int(institution_id)

        except (TypeError, ValueError):

            errors["institution_id"] = (
                "Invalid institution."
            )

        else:

            institution = Institution.query.get(
                institution_id
            )

            if not institution:

                errors["institution_id"] = (
                    "Selected institution was not found."
                )


    # --------------------------------------------------------
    # Security: institution
    # --------------------------------------------------------

    user_institution_id = (
        _subject_get_user_institution_id()
    )

    if (
        user_institution_id is not None
        and institution_id is not None
        and institution_id != user_institution_id
    ):

        errors["institution_id"] = (
            "You are not allowed to use this institution."
        )


    # --------------------------------------------------------
    # Branch
    # --------------------------------------------------------

    if branch_id:

        try:
            branch_id = int(branch_id)

        except (TypeError, ValueError):

            errors["branch_id"] = (
                "Invalid branch."
            )

        else:

            branch = Branch.query.get(
                branch_id
            )

            if not branch:

                errors["branch_id"] = (
                    "Selected branch was not found."
                )

            elif (
                institution_id is not None
                and branch.institution_id != institution_id
            ):

                errors["branch_id"] = (
                    "Selected branch does not belong "
                    "to the selected institution."
                )


            # Branch security
            user_branch_id = (
                _subject_get_user_branch_id()
            )

            if (
                not _subject_can_manage_global()
                and user_branch_id is not None
                and branch_id != user_branch_id
            ):

                errors["branch_id"] = (
                    "You are not allowed to use this branch."
                )


    # --------------------------------------------------------
    # Program
    # --------------------------------------------------------

    if program_id:

        try:
            program_id = int(program_id)

        except (TypeError, ValueError):

            errors["program_id"] = (
                "Invalid program."
            )

        else:

            program = Program.query.get(
                program_id
            )

            if not program:

                errors["program_id"] = (
                    "Selected program was not found."
                )

            elif (
                institution_id is not None
                and program.institution_id != institution_id
            ):

                errors["program_id"] = (
                    "Selected program does not belong "
                    "to the selected institution."
                )

    return institution, branch, program


# ============================================================
# ALL SUBJECTS
# ============================================================

@bp.route(
    "/subjects",
    methods=["GET"]
)
@login_required
def all_subjects():

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    current_role = (
        getattr(
            current_user,
            "role",
            None
        ) or ""
    ).strip().lower()

    # ========================================================
    # ALLOWED ROLES
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to view subjects.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # ROLE FLAGS
    # ========================================================

    is_superadmin = (
        current_role == "superadmin"
    )

    is_school_admin = (
        current_role == "school_admin"
    )

    is_branch_admin = (
        current_role == "branch_admin"
    )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # REQUIRED SCOPE
    # ========================================================

    if is_school_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    if is_branch_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        if current_branch_id is None:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # FILTERS
    # ========================================================

    search = (
        request.args.get(
            "search",
            ""
        ) or ""
    ).strip()

    institution_filter = (
        request.args.get(
            "institution_id",
            ""
        ) or ""
    ).strip()

    branch_filter = (
        request.args.get(
            "branch_id",
            ""
        ) or ""
    ).strip()

    program_filter = (
        request.args.get(
            "program_id",
            ""
        ) or ""
    ).strip()

    subject_type_filter = (
        request.args.get(
            "subject_type",
            ""
        ) or ""
    ).strip().lower()

    status_filter = (
        request.args.get(
            "status",
            ""
        ) or ""
    ).strip().lower()

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    if page < 1:
        page = 1

    if per_page not in {
        10,
        25,
        50,
        100
    }:
        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = Subject.query

    # ========================================================
    # SECURITY SCOPE
    #
    # SUPERADMIN
    #     All subjects.
    #
    # SCHOOL ADMIN
    #     Subjects inside own institution.
    #
    # BRANCH ADMIN
    #     Subjects inside own branch ONLY.
    # ========================================================

    if is_superadmin:

        # ----------------------------------------------------
        # No restriction
        # ----------------------------------------------------

        pass

    elif is_school_admin:

        query = query.filter(
            Subject.institution_id
            == current_institution_id
        )

    elif is_branch_admin:

        # ----------------------------------------------------
        # IMPORTANT:
        # Branch Admin MUST NEVER see:
        #
        # - another institution
        # - another branch
        # - institution-wide subjects
        #
        # Only exact current branch.
        # ----------------------------------------------------

        query = query.filter(
            Subject.institution_id
            == current_institution_id,
            Subject.branch_id
            == current_branch_id
        )

    # ========================================================
    # INSTITUTION FILTER
    # ========================================================

    if institution_filter:

        try:

            institution_id = int(
                institution_filter
            )

            if institution_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    # Never allow the URL filter to escape
                    # the user's institution.

                    if (
                        institution_id
                        != current_institution_id
                    ):

                        # Force impossible query.
                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.institution_id
                            == current_institution_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    if (
                        institution_id
                        != current_institution_id
                    ):

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.institution_id
                            == institution_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.institution_id
                        == institution_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # BRANCH FILTER
    # ========================================================

    if branch_filter:

        try:

            branch_id = int(
                branch_filter
            )

            if branch_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    # Cannot select another branch.

                    if (
                        branch_id
                        != current_branch_id
                    ):

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.branch_id
                            == current_branch_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    selected_branch = (
                        Branch.query.filter(
                            Branch.id
                            == branch_id,
                            Branch.institution_id
                            == current_institution_id
                        ).first()
                    )

                    if selected_branch is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.branch_id
                            == branch_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.branch_id
                        == branch_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_filter:

        try:

            program_id = int(
                program_filter
            )

            if program_id > 0:

                # --------------------------------------------
                # BRANCH ADMIN
                # --------------------------------------------

                if is_branch_admin:

                    selected_program = (
                        Program.query.filter(
                            Program.id
                            == program_id,
                            Program.institution_id
                            == current_institution_id,
                            db.or_(
                                Program.branch_id
                                == current_branch_id,
                                Program.branch_id.is_(None)
                            )
                        ).first()
                    )

                    if selected_program is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.program_id
                            == program_id
                        )

                # --------------------------------------------
                # SCHOOL ADMIN
                # --------------------------------------------

                elif is_school_admin:

                    selected_program = (
                        Program.query.filter(
                            Program.id
                            == program_id,
                            Program.institution_id
                            == current_institution_id
                        ).first()
                    )

                    if selected_program is None:

                        query = query.filter(
                            Subject.id == -1
                        )

                    else:

                        query = query.filter(
                            Subject.program_id
                            == program_id
                        )

                # --------------------------------------------
                # SUPERADMIN
                # --------------------------------------------

                else:

                    query = query.filter(
                        Subject.program_id
                        == program_id
                    )

        except (TypeError, ValueError):

            pass

    # ========================================================
    # SUBJECT TYPE FILTER
    # ========================================================

    if subject_type_filter:

        if (
            subject_type_filter
            in SUBJECT_TYPES
        ):

            query = query.filter(
                Subject.subject_type
                == subject_type_filter
            )

    # ========================================================
    # STATUS FILTER
    # ========================================================

    if status_filter:

        if (
            status_filter
            in SUBJECT_STATUSES
        ):

            query = query.filter(
                Subject.status
                == status_filter
            )

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = (
            f"%{search}%"
        )

        query = query.filter(
            db.or_(
                Subject.name.ilike(
                    search_pattern
                ),
                Subject.code.ilike(
                    search_pattern
                ),
                Subject.short_name.ilike(
                    search_pattern
                )
            )
        )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        Subject.name.asc(),
        Subject.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    subjects = pagination.items

    # ========================================================
    # FILTER DATA
    #
    # Do NOT blindly use global helper functions here.
    # Build the lists according to the user's scope.
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query.filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES
    # ========================================================

    if is_superadmin:

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        branches = (
            Branch.query.filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        # ----------------------------------------------------
        # BRANCH ADMIN:
        # EXACTLY ONE BRANCH
        # ----------------------------------------------------

        branches = (
            Branch.query.filter(
                Branch.id
                == current_branch_id,
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAMS
    # ========================================================

    if is_superadmin:

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        # ----------------------------------------------------
        # BRANCH ADMIN
        #
        # Programs allowed:
        #
        # 1. Current branch programs
        # 2. Institution-wide programs
        # ----------------------------------------------------

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id,
                db.or_(
                    Program.branch_id
                    == current_branch_id,
                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/subjects/all_subjects.html",

        # ----------------------------------------------------
        # DATA
        # ----------------------------------------------------

        subjects=subjects,
        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,

        subject_types=SUBJECT_TYPES,
        subject_statuses=SUBJECT_STATUSES,

        # ----------------------------------------------------
        # CURRENT FILTERS
        # ----------------------------------------------------

        search=search,
        institution_filter=institution_filter,
        branch_filter=branch_filter,
        program_filter=program_filter,
        subject_type_filter=subject_type_filter,
        status_filter=status_filter,

        # ----------------------------------------------------
        # ROLE / SCOPE DATA
        # ----------------------------------------------------

        is_superadmin=is_superadmin,
        is_school_admin=is_school_admin,
        is_branch_admin=is_branch_admin,

        current_user_institution_id=(
            current_institution_id
        ),

        current_user_branch_id=(
            current_branch_id
        ),

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )

# ============================================================
# GENERATE NEXT SUBJECT CODE
# ============================================================
def _generate_next_subject_code(
    institution_id,
    branch_id=None,
    program_id=None
):
    """
    Generate sequential subject code.

    Example:

        Program 1:
            SUB001
            SUB002
            SUB003

        Program 2:
            SUB001
            SUB002

    Sequence is scoped to:
        institution + branch + program
    """

    query = Subject.query.filter(
        Subject.institution_id == institution_id
    )

    # --------------------------------------------------------
    # BRANCH
    # --------------------------------------------------------

    if branch_id:

        query = query.filter(
            Subject.branch_id == branch_id
        )

    else:

        query = query.filter(
            Subject.branch_id.is_(None)
        )

    # --------------------------------------------------------
    # PROGRAM
    # --------------------------------------------------------

    if program_id:

        query = query.filter(
            Subject.program_id == program_id
        )

    else:

        query = query.filter(
            Subject.program_id.is_(None)
        )

    subjects = query.with_entities(
        Subject.code
    ).all()

    # --------------------------------------------------------
    # FIND HIGHEST SUB NUMBER
    # --------------------------------------------------------

    highest_number = 0

    for row in subjects:

        existing_code = (
            row[0]
            if row and row[0]
            else ""
        )

        existing_code = str(
            existing_code
        ).strip().upper()

        # Expected format:
        # SUB001
        # SUB002
        # SUB123

        if existing_code.startswith("SUB"):

            number_part = existing_code[3:]

            if number_part.isdigit():

                number = int(
                    number_part
                )

                if number > highest_number:

                    highest_number = number

    # --------------------------------------------------------
    # NEXT CODE
    # --------------------------------------------------------

    next_number = highest_number + 1

    return f"SUB{next_number:03d}"



# ============================================================
# ADD SUBJECT
# ============================================================
@bp.route(
    "/subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_subject():

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    current_role = (
        getattr(current_user, "role", None)
        or ""
    ).strip().lower()

    # ========================================================
    # ROLE PERMISSION
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to create subjects.",
            "danger"
        )

        return redirect(
            url_for("main.all_subjects")
        )

    # ========================================================
    # ROLE FLAGS
    # ========================================================

    is_superadmin = (
        current_role == "superadmin"
    )

    is_school_admin = (
        current_role == "school_admin"
    )

    is_branch_admin = (
        current_role == "branch_admin"
    )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # BRANCH ADMIN MUST HAVE INSTITUTION + BRANCH
    # ========================================================

    if is_branch_admin:

        if not current_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

        if not current_branch_id:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    # ========================================================
    # SCHOOL ADMIN MUST HAVE INSTITUTION
    # ========================================================

    if is_school_admin:

        if not current_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    # ========================================================
    # SELECTED VALUES
    # ========================================================

    selected_institution_id = None
    selected_branch_id = None
    selected_program_id = None

    # ========================================================
    # GET
    # ========================================================

    if request.method == "GET":

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        if is_superadmin:

            selected_institution_id = (
                request.args.get("institution_id")
                or None
            )

            selected_branch_id = (
                request.args.get("branch_id")
                or None
            )

            selected_program_id = (
                request.args.get("program_id")
                or None
            )

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif is_school_admin:

            selected_institution_id = (
                current_institution_id
            )

            selected_branch_id = (
                request.args.get("branch_id")
                or None
            )

            selected_program_id = (
                request.args.get("program_id")
                or None
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        elif is_branch_admin:

            # NEVER TAKE BRANCH FROM URL
            selected_institution_id = (
                current_institution_id
            )

            selected_branch_id = (
                current_branch_id
            )

            selected_program_id = (
                request.args.get("program_id")
                or None
            )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        errors = {}

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = (
            request.form.get("institution_id")
            or ""
        ).strip()

        branch_id = (
            request.form.get("branch_id")
            or ""
        ).strip()

        program_id = (
            request.form.get("program_id")
            or ""
        ).strip()

        name = (
            request.form.get("name")
            or ""
        ).strip()

        short_name = (
            request.form.get("short_name")
            or ""
        ).strip()

        subject_type = (
            request.form.get("subject_type")
            or "academic"
        ).strip().lower()

        weekly_hours_raw = (
            request.form.get("weekly_hours")
            or ""
        ).strip()

        credit_hours_raw = (
            request.form.get("credit_hours")
            or ""
        ).strip()

        max_marks_raw = (
            request.form.get("max_marks")
            or "100"
        ).strip()

        pass_marks_raw = (
            request.form.get("pass_marks")
            or "50"
        ).strip()

        description = (
            request.form.get("description")
            or ""
        ).strip()

        status = (
            request.form.get("status")
            or "active"
        ).strip().lower()

        # ====================================================
        # OPTIONAL VALUES
        # ====================================================

        branch_id = branch_id or None
        program_id = program_id or None
        short_name = short_name or None
        description = description or None

        # ====================================================
        # BRANCH ADMIN
        # FORCE OWN INSTITUTION + BRANCH
        # ====================================================

        if is_branch_admin:

            institution_id = str(
                current_institution_id
            )

            branch_id = str(
                current_branch_id
            )

        # ====================================================
        # SCHOOL ADMIN
        # FORCE OWN INSTITUTION
        # ====================================================

        elif is_school_admin:

            institution_id = str(
                current_institution_id
            )

        # ====================================================
        # UPDATE SELECTED VALUES
        # ====================================================

        selected_institution_id = (
            institution_id or None
        )

        selected_branch_id = (
            branch_id or None
        )

        selected_program_id = (
            program_id or None
        )

        # ====================================================
        # INSTITUTION
        # ====================================================

        institution = None
        institution_id_int = None

        if not institution_id:

            errors["institution_id"] = (
                "Institution is required."
            )

        else:

            try:

                institution_id_int = int(
                    institution_id
                )

            except (TypeError, ValueError):

                errors["institution_id"] = (
                    "Invalid institution selected."
                )

            else:

                institution = (
                    Institution.query
                    .filter(
                        Institution.id
                        == institution_id_int
                    )
                    .first()
                )

                if not institution:

                    errors["institution_id"] = (
                        "Selected institution does not exist."
                    )

                # --------------------------------------------
                # SCHOOL ADMIN / BRANCH ADMIN
                # --------------------------------------------

                if (
                    not is_superadmin
                    and current_institution_id
                    and institution_id_int
                    != int(current_institution_id)
                ):

                    errors["institution_id"] = (
                        "You can only use your assigned "
                        "institution."
                    )

        # ====================================================
        # BRANCH
        # ====================================================

        branch = None
        branch_id_int = None

        if not branch_id:

            errors["branch_id"] = (
                "Branch is required."
            )

        else:

            try:

                branch_id_int = int(
                    branch_id
                )

            except (TypeError, ValueError):

                errors["branch_id"] = (
                    "Invalid branch selected."
                )

            else:

                branch = (
                    Branch.query
                    .filter(
                        Branch.id
                        == branch_id_int
                    )
                    .first()
                )

                if not branch:

                    errors["branch_id"] = (
                        "Selected branch does not exist."
                    )

                else:

                    # ----------------------------------------
                    # BRANCH → INSTITUTION
                    # ----------------------------------------

                    if (
                        institution_id_int
                        is not None
                        and getattr(
                            branch,
                            "institution_id",
                            None
                        )
                        != institution_id_int
                    ):

                        errors["branch_id"] = (
                            "The selected branch does not "
                            "belong to the selected institution."
                        )

                    # ----------------------------------------
                    # BRANCH ADMIN → OWN BRANCH ONLY
                    # ----------------------------------------

                    if is_branch_admin:

                        if (
                            int(branch.id)
                            != int(current_branch_id)
                        ):

                            errors["branch_id"] = (
                                "You can only use your "
                                "assigned branch."
                            )

                        if (
                            getattr(
                                branch,
                                "institution_id",
                                None
                            )
                            != int(current_institution_id)
                        ):

                            errors["branch_id"] = (
                                "The selected branch does not "
                                "belong to your institution."
                            )

                    # ----------------------------------------
                    # SCHOOL ADMIN → OWN INSTITUTION
                    # ----------------------------------------

                    if is_school_admin:

                        if (
                            getattr(
                                branch,
                                "institution_id",
                                None
                            )
                            != int(current_institution_id)
                        ):

                            errors["branch_id"] = (
                                "You can only use branches "
                                "from your institution."
                            )

        # ====================================================
        # NAME
        # ====================================================

        if not name:

            errors["name"] = (
                "Subject name is required."
            )

        elif len(name) > 150:

            errors["name"] = (
                "Subject name cannot exceed "
                "150 characters."
            )

        # ====================================================
        # SHORT NAME
        # ====================================================

        if short_name and len(short_name) > 100:

            errors["short_name"] = (
                "Short name cannot exceed "
                "100 characters."
            )

        # ====================================================
        # SUBJECT TYPE
        # ====================================================

        if subject_type not in SUBJECT_TYPES:

            errors["subject_type"] = (
                "Invalid subject type selected."
            )

        # ====================================================
        # STATUS
        # ====================================================

        if status not in SUBJECT_STATUSES:

            errors["status"] = (
                "Invalid subject status selected."
            )

        # ====================================================
        # DECIMAL VALUES
        # ====================================================

        weekly_hours = _subject_parse_decimal(
            weekly_hours_raw,
            "weekly_hours",
            errors,
            allow_empty=True
        )

        credit_hours = _subject_parse_decimal(
            credit_hours_raw,
            "credit_hours",
            errors,
            allow_empty=True
        )

        max_marks = _subject_parse_decimal(
            max_marks_raw,
            "max_marks",
            errors,
            allow_empty=False
        )

        pass_marks = _subject_parse_decimal(
            pass_marks_raw,
            "pass_marks",
            errors,
            allow_empty=False
        )

        # ====================================================
        # HOURS VALIDATION
        # ====================================================

        if (
            weekly_hours is not None
            and weekly_hours < Decimal("0")
        ):

            errors["weekly_hours"] = (
                "Weekly hours cannot be negative."
            )

        if (
            credit_hours is not None
            and credit_hours < Decimal("0")
        ):

            errors["credit_hours"] = (
                "Credit hours cannot be negative."
            )

        # ====================================================
        # MARKS VALIDATION
        # ====================================================

        if (
            max_marks is not None
            and max_marks <= Decimal("0")
        ):

            errors["max_marks"] = (
                "Maximum marks must be greater than 0."
            )

        if (
            pass_marks is not None
            and pass_marks < Decimal("0")
        ):

            errors["pass_marks"] = (
                "Pass marks cannot be negative."
            )

        if (
            max_marks is not None
            and pass_marks is not None
            and pass_marks > max_marks
        ):

            errors["pass_marks"] = (
                "Pass marks cannot be greater than "
                "maximum marks."
            )

        # ====================================================
        # PROGRAM REQUIRED
        # ====================================================

        if not program_id:

            errors["program_id"] = (
                "Program is required to generate "
                "the subject code."
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        program = None
        program_id_int = None

        if program_id:

            try:

                program_id_int = int(
                    program_id
                )

            except (TypeError, ValueError):

                errors["program_id"] = (
                    "Invalid program selected."
                )

            else:

                program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id_int
                    )
                    .first()
                )

                if not program:

                    errors["program_id"] = (
                        "Selected program does not exist."
                    )

                else:

                    # ----------------------------------------
                    # PROGRAM INSTITUTION
                    # ----------------------------------------

                    program_institution_id = getattr(
                        program,
                        "institution_id",
                        None
                    )

                    if (
                        institution_id_int
                        is not None
                        and program_institution_id
                        != institution_id_int
                    ):

                        errors["program_id"] = (
                            "The selected program does not "
                            "belong to the selected institution."
                        )

                    # ----------------------------------------
                    # BRANCH ADMIN PROGRAM SCOPE
                    # ----------------------------------------

                    if is_branch_admin:

                        program_branch_id = getattr(
                            program,
                            "branch_id",
                            None
                        )

                        # Program may be:
                        #
                        # - Current branch
                        # - Institution-wide (NULL branch)
                        #

                        if (
                            program_branch_id is not None
                            and int(program_branch_id)
                            != int(current_branch_id)
                        ):

                            errors["program_id"] = (
                                "You can only use programs "
                                "assigned to your branch or "
                                "institution-wide programs."
                            )

        # ====================================================
        # DUPLICATE SUBJECT
        # ====================================================

        if (
            institution_id_int is not None
            and branch_id_int is not None
            and name
            and not errors.get("institution_id")
            and not errors.get("branch_id")
        ):

            query = Subject.query.filter(
                Subject.institution_id
                == institution_id_int,

                Subject.branch_id
                == branch_id_int
            )

            if program_id_int:

                query = query.filter(
                    Subject.program_id
                    == program_id_int
                )

            else:

                query = query.filter(
                    Subject.program_id.is_(None)
                )

            query = query.filter(
                db.func.lower(
                    Subject.name
                )
                == name.lower()
            )

            if query.first():

                errors["name"] = (
                    "A subject with this name already "
                    "exists for the selected program."
                )

        # ====================================================
        # GENERATE SUBJECT CODE
        # ====================================================

        code = None

        if not errors:

            code = _generate_next_subject_code(

                institution_id=(
                    institution_id_int
                ),

                branch_id=(
                    branch_id_int
                ),

                program_id=(
                    program_id_int
                )
            )

        # ====================================================
        # CREATE SUBJECT
        # ====================================================

        if not errors:

            try:

                subject = Subject(

                    institution_id=(
                        institution_id_int
                    ),

                    branch_id=(
                        branch_id_int
                    ),

                    program_id=(
                        program_id_int
                    ),

                    name=name,

                    code=code,

                    short_name=short_name,

                    subject_type=subject_type,

                    weekly_hours=weekly_hours,

                    credit_hours=credit_hours,

                    max_marks=max_marks,

                    pass_marks=pass_marks,

                    description=description,

                    status=status,
                )

                db.session.add(subject)

                db.session.commit()

                flash(
                    f'Subject "{subject.name}" '
                    f'with code "{subject.code}" '
                    f'was created successfully.',
                    "success"
                )

                return redirect(
                    url_for(
                        "main.view_subject",
                        subject_id=subject.id
                    )
                )

            except IntegrityError as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "Subject integrity error"
                )

                error_text = str(
                    getattr(
                        exc,
                        "orig",
                        exc
                    )
                ).lower()

                if "code" in error_text:

                    flash(
                        "The generated subject code already "
                        "exists. Please try again.",
                        "danger"
                    )

                elif "name" in error_text:

                    flash(
                        "A subject with this name already "
                        "exists for the selected program.",
                        "danger"
                    )

                else:

                    flash(
                        "Unable to create the subject because "
                        "of a database constraint.",
                        "danger"
                    )

            except Exception:

                db.session.rollback()

                current_app.logger.exception(
                    "Unexpected error while creating subject"
                )

                flash(
                    "An unexpected error occurred while "
                    "creating the subject.",
                    "danger"
                )

        # ====================================================
        # VALIDATION ERRORS
        # ====================================================

        if errors:

            for message in errors.values():

                flash(
                    message,
                    "danger"
                )

    # ========================================================
    # FORM DATA
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institution = None

        if current_institution_id:

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == current_institution_id
                )
                .first()
            )

        institutions = (
            [institution]
            if institution
            else []
        )

    # ========================================================
    # BRANCHES
    # ========================================================

    if is_superadmin:

        # SUPERADMIN → ALL BRANCHES

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        # SCHOOL ADMIN → ALL BRANCHES
        # OF HIS INSTITUTION

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif is_branch_admin:

        # ====================================================
        # BRANCH ADMIN → ONLY HIS BRANCH
        # ====================================================

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id,

                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = []

    # ========================================================
    # PROGRAMS
    # ========================================================

    if is_superadmin:

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif is_branch_admin:

        # ====================================================
        # BRANCH ADMIN:
        #
        # Current branch programs
        # +
        # Institution-wide programs
        # ====================================================

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id
            )
            .filter(
                db.or_(
                    Program.branch_id
                    == current_branch_id,

                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        programs = []

    # ========================================================
    # FINAL BRANCH ADMIN SAFETY FILTER
    # ========================================================

    if is_branch_admin:

        branches = [
            branch
            for branch in branches
            if (
                int(branch.id)
                == int(current_branch_id)
                and
                int(branch.institution_id)
                == int(current_institution_id)
            )
        ]

    # ========================================================
    # FINAL CONTEXT
    # ========================================================

    context = {

        # ----------------------------------------------------
        # DATA
        # ----------------------------------------------------

        "institutions": institutions,

        "branches": branches,

        "programs": programs,

        # ----------------------------------------------------
        # SELECTED
        # ----------------------------------------------------

        "selected_institution_id": (
            selected_institution_id
        ),

        "selected_branch_id": (
            selected_branch_id
        ),

        "selected_program_id": (
            selected_program_id
        ),

        # ----------------------------------------------------
        # USER
        # ----------------------------------------------------

        "current_user_role": (
            current_role
        ),

        "current_user_institution_id": (
            current_institution_id
        ),

        "current_user_branch_id": (
            current_branch_id
        ),

        # ----------------------------------------------------
        # ROLE FLAGS
        # ----------------------------------------------------

        "is_superadmin": (
            is_superadmin
        ),

        "is_school_admin": (
            is_school_admin
        ),

        "is_branch_admin": (
            is_branch_admin
        ),
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/subjects/add_subject.html",
        **context
    )



# ============================================================
# VIEW SUBJECT
# ============================================================

@bp.route(
    "/subjects/<int:subject_id>",
    methods=["GET"]
)
@login_required
def view_subject(subject_id):

    # ========================================================
    # GET SUBJECT
    # ========================================================

    query = Subject.query.filter(
        Subject.id == subject_id
    )

    query = _subject_scope_query(
        query
    )

    subject = query.first()


    # ========================================================
    # NOT FOUND
    # ========================================================

    if not subject:

        flash(
            "Subject not found or you do not have permission to view it.",
            "warning"
        )

        return redirect(
            url_for("main.all_subjects")
        )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/subjects/view_subject.html",
        subject=subject,
        user=current_user
    )


# ============================================================
# EDIT SUBJECT
# ============================================================
@bp.route(
    "/subjects/<int:subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_subject(subject_id):

    # ============================================================
    # GET SUBJECT
    # ============================================================

    subject = Subject.query.get_or_404(subject_id)

    # ============================================================
    # CURRENT USER ROLE
    # ============================================================

    current_role = (
        getattr(current_user, "role", None) or ""
    ).strip().lower()

    # ============================================================
    # ALLOWED ROLES
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to edit subjects.",
            "danger"
        )

        return redirect(
            url_for("main.all_subjects")
        )

    # ============================================================
    # ROLE FLAGS
    # ============================================================

    is_superadmin = (
        current_role == "superadmin"
    )

    is_school_admin = (
        current_role == "school_admin"
    )

    is_branch_admin = (
        current_role == "branch_admin"
    )

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ============================================================
    # REQUIRED SCOPE VALIDATION
    # ============================================================

    if is_school_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    if is_branch_admin:

        if current_institution_id is None:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

        if current_branch_id is None:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    # ============================================================
    # EXISTING SUBJECT SECURITY
    #
    # SUPERADMIN
    #     Can edit everything.
    #
    # SCHOOL ADMIN
    #     Can edit subjects inside own institution.
    #
    # BRANCH ADMIN
    #     Can edit subjects inside own branch ONLY.
    # ============================================================

    if is_school_admin:

        if (
            subject.institution_id
            != current_institution_id
        ):

            flash(
                "You are not authorized to edit this subject.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    elif is_branch_admin:

        # --------------------------------------------------------
        # Institution must match
        # --------------------------------------------------------

        if (
            subject.institution_id
            != current_institution_id
        ):

            flash(
                "You are not authorized to edit this subject.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

        # --------------------------------------------------------
        # Branch MUST match exactly
        #
        # branch_admin cannot edit:
        # - another branch subject
        # - institution-wide subject (branch_id=None)
        # --------------------------------------------------------

        if (
            subject.branch_id
            != current_branch_id
        ):

            flash(
                "You are not authorized to edit a subject "
                "outside your assigned branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_subjects")
            )

    # ============================================================
    # POST
    # ============================================================

    if request.method == "POST":

        errors = {}

        # ========================================================
        # INSTITUTION
        # ========================================================

        institution_raw = (
            request.form.get("institution_id") or ""
        ).strip()

        institution_id = None

        if is_branch_admin or is_school_admin:

            # ----------------------------------------------------
            # NEVER TRUST FORM FOR ADMIN SCOPE
            # ----------------------------------------------------

            institution_id = current_institution_id

        elif is_superadmin:

            if not institution_raw:

                errors["institution_id"] = (
                    "Institution is required."
                )

            else:

                try:

                    institution_id = int(
                        institution_raw
                    )

                    if institution_id <= 0:
                        raise ValueError

                except (TypeError, ValueError):

                    errors["institution_id"] = (
                        "Invalid institution."
                    )

        # ========================================================
        # BRANCH
        # ========================================================

        branch_raw = (
            request.form.get("branch_id") or ""
        ).strip()

        branch_id = None

        if is_branch_admin:

            # ----------------------------------------------------
            # BRANCH ADMIN:
            # FORCE CURRENT BRANCH
            # ----------------------------------------------------

            branch_id = current_branch_id

        elif branch_raw:

            try:

                branch_id = int(
                    branch_raw
                )

                if branch_id <= 0:
                    raise ValueError

            except (TypeError, ValueError):

                errors["branch_id"] = (
                    "Invalid branch."
                )

        # ========================================================
        # PROGRAM
        # ========================================================

        program_raw = (
            request.form.get("program_id") or ""
        ).strip()

        program_id = None

        if not program_raw:

            errors["program_id"] = (
                "Program is required."
            )

        else:

            try:

                program_id = int(
                    program_raw
                )

                if program_id <= 0:
                    raise ValueError

            except (TypeError, ValueError):

                errors["program_id"] = (
                    "Invalid program."
                )

        # ========================================================
        # SUBJECT NAME
        # ========================================================

        name = (
            request.form.get("name") or ""
        ).strip()

        if not name:

            errors["name"] = (
                "Subject name is required."
            )

        elif len(name) > 150:

            errors["name"] = (
                "Subject name cannot exceed "
                "150 characters."
            )

        # ========================================================
        # SUBJECT CODE
        #
        # IMPORTANT:
        # CODE IS NEVER CHANGED FROM FORM.
        # ========================================================

        code = (
            subject.code or ""
        ).strip().upper()

        if not code:

            errors["code"] = (
                "This subject does not have a valid "
                "subject code."
            )

        # ========================================================
        # SHORT NAME
        # ========================================================

        short_name = (
            request.form.get("short_name") or ""
        ).strip()

        if short_name:

            if len(short_name) > 100:

                errors["short_name"] = (
                    "Short name cannot exceed "
                    "100 characters."
                )

        else:

            short_name = None

        # ========================================================
        # SUBJECT TYPE
        # ========================================================

        subject_type = (
            request.form.get("subject_type")
            or "academic"
        ).strip().lower()

        if subject_type not in SUBJECT_TYPES:

            errors["subject_type"] = (
                "Invalid subject type."
            )

        # ========================================================
        # STATUS
        # ========================================================

        status = (
            request.form.get("status")
            or "active"
        ).strip().lower()

        if status not in SUBJECT_STATUSES:

            errors["status"] = (
                "Invalid subject status."
            )

        # ========================================================
        # WEEKLY HOURS
        # ========================================================

        weekly_hours = _subject_parse_decimal(
            request.form.get("weekly_hours"),
            "weekly_hours",
            errors,
            allow_empty=True
        )

        if (
            weekly_hours is not None
            and weekly_hours < Decimal("0")
        ):

            errors["weekly_hours"] = (
                "Weekly hours cannot be negative."
            )

        # ========================================================
        # CREDIT HOURS
        # ========================================================

        credit_hours = _subject_parse_decimal(
            request.form.get("credit_hours"),
            "credit_hours",
            errors,
            allow_empty=True
        )

        if (
            credit_hours is not None
            and credit_hours < Decimal("0")
        ):

            errors["credit_hours"] = (
                "Credit hours cannot be negative."
            )

        # ========================================================
        # MAX MARKS
        # ========================================================

        max_marks = _subject_parse_decimal(
            request.form.get("max_marks"),
            "max_marks",
            errors,
            allow_empty=False
        )

        if (
            max_marks is not None
            and max_marks <= Decimal("0")
        ):

            errors["max_marks"] = (
                "Maximum marks must be greater than 0."
            )

        # ========================================================
        # PASS MARKS
        # ========================================================

        pass_marks = _subject_parse_decimal(
            request.form.get("pass_marks"),
            "pass_marks",
            errors,
            allow_empty=False
        )

        if (
            pass_marks is not None
            and pass_marks < Decimal("0")
        ):

            errors["pass_marks"] = (
                "Pass marks cannot be negative."
            )

        # ========================================================
        # PASS MARKS <= MAX MARKS
        # ========================================================

        if (
            max_marks is not None
            and pass_marks is not None
            and pass_marks > max_marks
        ):

            errors["pass_marks"] = (
                "Pass marks cannot be greater than "
                "maximum marks."
            )

        # ========================================================
        # DESCRIPTION
        # ========================================================

        description = (
            request.form.get("description") or ""
        ).strip()

        if not description:
            description = None

        # ========================================================
        # USER SCOPE SECURITY
        #
        # This is backend enforcement.
        # Even if someone modifies HTML/POST manually,
        # branch_admin cannot escape his scope.
        # ========================================================

        if is_school_admin:

            if (
                institution_id
                != current_institution_id
            ):

                errors["institution_id"] = (
                    "You cannot move this subject "
                    "to another institution."
                )

        if is_branch_admin:

            # ----------------------------------------------------
            # Force institution
            # ----------------------------------------------------

            institution_id = (
                current_institution_id
            )

            # ----------------------------------------------------
            # Force branch
            # ----------------------------------------------------

            branch_id = (
                current_branch_id
            )

        # ========================================================
        # RELATIONSHIP VALIDATION
        # ========================================================

        if institution_id is not None:

            _validate_subject_relationships(
                institution_id,
                branch_id,
                program_id,
                errors
            )

        # ========================================================
        # EXTRA BRANCH ADMIN PROGRAM SECURITY
        #
        # Program must belong to:
        #
        #   1. Current institution
        #   2. Current branch
        #
        # OR:
        #
        #   Institution-wide program (branch_id=NULL)
        # ========================================================

        if (
            is_branch_admin
            and program_id is not None
        ):

            selected_program = (
                Program.query.filter(
                    Program.id == program_id,
                    Program.institution_id
                    == current_institution_id
                ).first()
            )

            if selected_program is None:

                errors["program_id"] = (
                    "You cannot use a program "
                    "outside your institution."
                )

            elif (
                selected_program.branch_id is not None
                and selected_program.branch_id
                != current_branch_id
            ):

                errors["program_id"] = (
                    "You cannot use a program "
                    "outside your assigned branch."
                )

        # ========================================================
        # BRANCH SECURITY
        # ========================================================

        if branch_id is not None:

            selected_branch = (
                Branch.query.filter(
                    Branch.id == branch_id
                ).first()
            )

            if selected_branch is None:

                errors["branch_id"] = (
                    "Selected branch does not exist."
                )

            else:

                if (
                    institution_id is not None
                    and selected_branch.institution_id
                    != institution_id
                ):

                    errors["branch_id"] = (
                        "Selected branch does not "
                        "belong to the selected institution."
                    )

                # ------------------------------------------------
                # BRANCH ADMIN MUST USE OWN BRANCH
                # ------------------------------------------------

                if (
                    is_branch_admin
                    and selected_branch.id
                    != current_branch_id
                ):

                    errors["branch_id"] = (
                        "You cannot move this subject "
                        "to another branch."
                    )

        # ========================================================
        # DUPLICATE SUBJECT NAME
        #
        # Same name is allowed in different branches,
        # but not within the same institution + branch.
        # ========================================================

        if (
            institution_id is not None
            and name
        ):

            duplicate_name_query = (
                Subject.query.filter(
                    Subject.id != subject.id,
                    Subject.institution_id
                    == institution_id,
                    db.func.lower(
                        Subject.name
                    ) == name.lower()
                )
            )

            if branch_id is not None:

                duplicate_name_query = (
                    duplicate_name_query.filter(
                        Subject.branch_id
                        == branch_id
                    )
                )

            else:

                duplicate_name_query = (
                    duplicate_name_query.filter(
                        Subject.branch_id.is_(None)
                    )
                )

            duplicate_name = (
                duplicate_name_query.first()
            )

            if duplicate_name:

                errors["name"] = (
                    "Another subject with this name "
                    "already exists in the selected "
                    "institution and branch."
                )

        # ========================================================
        # DUPLICATE SUBJECT CODE
        #
        # Existing code is preserved.
        # ========================================================

        if (
            institution_id is not None
            and code
        ):

            duplicate_code_query = (
                Subject.query.filter(
                    Subject.id != subject.id,
                    Subject.institution_id
                    == institution_id,
                    db.func.upper(
                        Subject.code
                    ) == code.upper()
                )
            )

            if branch_id is not None:

                duplicate_code_query = (
                    duplicate_code_query.filter(
                        Subject.branch_id
                        == branch_id
                    )
                )

            else:

                duplicate_code_query = (
                    duplicate_code_query.filter(
                        Subject.branch_id.is_(None)
                    )
                )

            duplicate_code = (
                duplicate_code_query.first()
            )

            if duplicate_code:

                errors["code"] = (
                    "The existing subject code is "
                    "already used in the selected "
                    "institution and branch."
                )

        # ========================================================
        # VALIDATION FAILED
        # ========================================================

        if errors:

            for message in errors.values():

                flash(
                    message,
                    "danger"
                )

            # ----------------------------------------------------
            # BUILD SAFE FORM CONTEXT
            # ----------------------------------------------------

            if is_superadmin:

                institutions = (
                    Institution.query
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches = (
                    Branch.query
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs = (
                    Program.query
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            elif is_school_admin:

                institutions = (
                    Institution.query.filter(
                        Institution.id
                        == current_institution_id
                    )
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches = (
                    Branch.query.filter(
                        Branch.institution_id
                        == current_institution_id
                    )
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs = (
                    Program.query.filter(
                        Program.institution_id
                        == current_institution_id
                    )
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            else:

                # ------------------------------------------------
                # BRANCH ADMIN
                # ONLY ONE BRANCH
                # ------------------------------------------------

                institutions = (
                    Institution.query.filter(
                        Institution.id
                        == current_institution_id
                    )
                    .order_by(
                        Institution.name.asc()
                    )
                    .all()
                )

                branches = (
                    Branch.query.filter(
                        Branch.id
                        == current_branch_id,
                        Branch.institution_id
                        == current_institution_id
                    )
                    .order_by(
                        Branch.name.asc()
                    )
                    .all()
                )

                programs = (
                    Program.query.filter(
                        Program.institution_id
                        == current_institution_id,
                        db.or_(
                            Program.branch_id
                            == current_branch_id,
                            Program.branch_id.is_(None)
                        )
                    )
                    .order_by(
                        Program.name.asc()
                    )
                    .all()
                )

            return render_template(
                "backend/pages/subjects/edit_subject.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                subject=subject,
                is_superadmin=is_superadmin,
                is_school_admin=is_school_admin,
                is_branch_admin=is_branch_admin,
                current_user_institution_id=(
                    current_institution_id
                ),
                current_user_branch_id=(
                    current_branch_id
                ),
                selected_institution_id=(
                    institution_id
                    if institution_id is not None
                    else subject.institution_id
                ),
                selected_branch_id=(
                    branch_id
                    if branch_id is not None
                    else subject.branch_id
                ),
                selected_program_id=(
                    program_id
                    if program_id is not None
                    else subject.program_id
                )
            )

        # ========================================================
        # UPDATE SUBJECT
        # ========================================================

        try:

            # ----------------------------------------------------
            # IMPORTANT:
            # SUBJECT CODE IS NOT CHANGED
            # ----------------------------------------------------

            subject.institution_id = (
                institution_id
            )

            subject.branch_id = (
                branch_id
            )

            subject.program_id = (
                program_id
            )

            subject.name = (
                name
            )

            subject.short_name = (
                short_name
            )

            subject.subject_type = (
                subject_type
            )

            subject.weekly_hours = (
                weekly_hours
            )

            subject.credit_hours = (
                credit_hours
            )

            subject.max_marks = (
                max_marks
            )

            subject.pass_marks = (
                pass_marks
            )

            subject.description = (
                description
            )

            subject.status = (
                status
            )

            # ----------------------------------------------------
            # UPDATED TIMESTAMP
            # ----------------------------------------------------

            subject.updated_at = datetime.utcnow()

            # ----------------------------------------------------
            # COMMIT
            # ----------------------------------------------------

            db.session.commit()

            flash(
                f'Subject "{subject.name}" '
                f'updated successfully.',
                "success"
            )

            return redirect(
                url_for(
                    "main.view_subject",
                    subject_id=subject.id
                )
            )

        # ========================================================
        # DATABASE INTEGRITY ERROR
        # ========================================================

        except IntegrityError:

            db.session.rollback()

            current_app.logger.exception(
                "IntegrityError while editing "
                "subject ID %s",
                subject.id
            )

            flash(
                "Unable to update the subject because "
                "of a database constraint conflict. "
                "Please check the institution, branch, "
                "program, name, and code.",
                "danger"
            )

        # ========================================================
        # GENERAL ERROR
        # ========================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Unexpected error while updating "
                "subject ID %s: %s",
                subject.id,
                exc
            )

            flash(
                "An unexpected error occurred while "
                "updating the subject.",
                "danger"
            )

    # ============================================================
    # GET / FAILED POST AFTER DATABASE ERROR
    # ============================================================

    if is_superadmin:

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif is_school_admin:

        institutions = (
            Institution.query.filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

        branches = (
            Branch.query.filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        # ========================================================
        # BRANCH ADMIN
        # EXACTLY ONE BRANCH
        # ========================================================

        institutions = (
            Institution.query.filter(
                Institution.id
                == current_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

        branches = (
            Branch.query.filter(
                Branch.id
                == current_branch_id,
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

        programs = (
            Program.query.filter(
                Program.institution_id
                == current_institution_id,
                db.or_(
                    Program.branch_id
                    == current_branch_id,
                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ============================================================
    # RENDER EDIT PAGE
    # ============================================================

    return render_template(
        "backend/pages/subjects/edit_subject.html",
        institutions=institutions,
        branches=branches,
        programs=programs,
        subject=subject,
        is_superadmin=is_superadmin,
        is_school_admin=is_school_admin,
        is_branch_admin=is_branch_admin,
        current_user_institution_id=(
            current_institution_id
        ),
        current_user_branch_id=(
            current_branch_id
        ),
        selected_institution_id=(
            subject.institution_id
        ),
        selected_branch_id=(
            subject.branch_id
        ),
        selected_program_id=(
            subject.program_id
        ),
        user=current_user
    )



# ============================================================
# DELETE SUBJECT
# ============================================================

@bp.route(
    "/subjects/<int:subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_subject(subject_id):

    # ========================================================
    # GET SUBJECT WITH SECURITY SCOPE
    # ========================================================

    query = Subject.query.filter(
        Subject.id == subject_id
    )

    query = _subject_scope_query(
        query
    )

    subject = query.first()


    # ========================================================
    # NOT FOUND
    # ========================================================

    if not subject:

        flash(
            "Subject not found or you do not have permission to delete it.",
            "warning"
        )

        return redirect(
            url_for("main.all_subjects")
        )


    subject_name = (
        subject.name
    )


    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            subject
        )

        db.session.commit()

        flash(
            f'Subject "{subject_name}" was deleted successfully.',
            "success"
        )


    except IntegrityError:

        db.session.rollback()

        flash(
            "This subject cannot be deleted because it is "
            "currently referenced by other academic records.",
            "danger"
        )


    except Exception:

        db.session.rollback()

        flash(
            "An unexpected error occurred while deleting the subject.",
            "danger"
        )


    return redirect(
        url_for(
            "main.all_subjects"
        )
    )


# ============================================================
# TEACHER ROUTES
# PostgreSQL / Neon
# ============================================================

# ============================================================
# TEACHER CONSTANTS
# ============================================================

TEACHER_GENDERS = [
    "male",
    "female",
    "other",
]

TEACHER_STATUSES = [
    "active",
    "inactive",
    "suspended",
    "resigned",
]


# ============================================================
# TEACHER ACCESS HELPERS
# ============================================================

def _teacher_is_global_user():
    """
    Global users can manage teachers across institutions.
    """

    return (
        getattr(current_user, "role", None)
        in {
            "superadmin",
            "super_admin",
            "admin",
            "system_admin",
        }
    )


def _teacher_get_user_institution_id():
    """
    Return current user's institution ID.

    Global users:
        None

    Institution-scoped users:
        institution_id
    """

    if _teacher_is_global_user():
        return None

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    if institution_id:
        try:
            return int(institution_id)
        except (TypeError, ValueError):
            return None

    return None


def _teacher_get_user_branch_id():
    """
    Return current user's branch ID.
    """

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if branch_id:
        try:
            return int(branch_id)
        except (TypeError, ValueError):
            return None

    return None


def _teacher_can_manage():
    """
    Roles allowed to manage teachers.
    """

    return (
        getattr(current_user, "role", None)
        in {
            "superadmin",
            "super_admin",
            "admin",
            "system_admin",
            "institution_admin",
            "branch_admin",
        }
    )


def _teacher_scope_query(query):
    """
    Apply institution / branch security.
    """

    if _teacher_is_global_user():
        return query

    institution_id = _teacher_get_user_institution_id()

    if institution_id is None:
        return query.filter(
            db.literal(False)
        )

    query = query.filter(
        Teacher.institution_id == institution_id
    )

    # Branch admins are restricted to their branch.
    if getattr(current_user, "role", None) == "branch_admin":

        branch_id = _teacher_get_user_branch_id()

        if branch_id is None:
            return query.filter(
                db.literal(False)
            )

        query = query.filter(
            Teacher.branch_id == branch_id
        )

    return query


# ============================================================
# ALLOWED INSTITUTIONS
# ============================================================

def _teacher_allowed_institutions():

    if _teacher_is_global_user():

        return Institution.query.order_by(
            Institution.name.asc()
        ).all()

    institution_id = _teacher_get_user_institution_id()

    if institution_id is None:
        return []

    institution = Institution.query.filter(
        Institution.id == institution_id
    ).first()

    return [institution] if institution else []


# ============================================================
# ALLOWED BRANCHES
# ============================================================

def _teacher_allowed_branches(institution_id=None):

    query = Branch.query

    if institution_id is not None:

        query = query.filter(
            Branch.institution_id == institution_id
        )

    if not _teacher_is_global_user():

        user_institution_id = (
            _teacher_get_user_institution_id()
        )

        if user_institution_id is None:
            return []

        query = query.filter(
            Branch.institution_id == user_institution_id
        )

        if getattr(current_user, "role", None) == "branch_admin":

            user_branch_id = (
                _teacher_get_user_branch_id()
            )

            if user_branch_id is None:
                return []

            query = query.filter(
                Branch.id == user_branch_id
            )

    return query.order_by(
        Branch.name.asc()
    ).all()


# ============================================================
# TEACHER FORM CONTEXT
# ============================================================

def _teacher_form_context(institution_id=None):

    return {
        "user": current_user,

        "institutions":
            _teacher_allowed_institutions(),

        "branches":
            _teacher_allowed_branches(institution_id),

        "teacher_genders":
            TEACHER_GENDERS,

        "teacher_statuses":
            TEACHER_STATUSES,
    }


# ============================================================
# VALIDATE INSTITUTION / BRANCH
# ============================================================

def _validate_teacher_relationships(
    institution_id,
    branch_id,
    errors
):

    if not institution_id:
        errors.append(
            "Institution is required."
        )
        return

    institution = Institution.query.filter(
        Institution.id == institution_id
    ).first()

    if not institution:
        errors.append(
            "Selected institution was not found."
        )
        return

    # --------------------------------------------------------
    # Scoped user cannot select another institution
    # --------------------------------------------------------

    if not _teacher_is_global_user():

        user_institution_id = (
            _teacher_get_user_institution_id()
        )

        if (
            user_institution_id is None
            or institution_id != user_institution_id
        ):
            errors.append(
                "You are not allowed to use this institution."
            )

    # --------------------------------------------------------
    # Branch required
    # --------------------------------------------------------

    if not branch_id:

        errors.append(
            "Branch is required."
        )

        return

    branch = Branch.query.filter(
        Branch.id == branch_id
    ).first()

    if not branch:

        errors.append(
            "Selected branch was not found."
        )

        return

    # --------------------------------------------------------
    # Branch must belong to institution
    # --------------------------------------------------------

    if branch.institution_id != institution_id:

        errors.append(
            "Selected branch does not belong "
            "to the selected institution."
        )

    # --------------------------------------------------------
    # Branch-admin restriction
    # --------------------------------------------------------

    if (
        not _teacher_is_global_user()
        and getattr(current_user, "role", None)
        == "branch_admin"
    ):

        user_branch_id = (
            _teacher_get_user_branch_id()
        )

        if (
            user_branch_id is None
            or branch_id != user_branch_id
        ):

            errors.append(
                "You are not allowed to use this branch."
            )


# ============================================================
# AUTO GENERATE TEACHER ROLL NUMBER
# ============================================================

def _generate_teacher_roll_no(institution_id):
    """
    Generate:

        T001
        T002
        T003

    Roll number is unique within institution.
    """

    prefix = "T"

    teachers = Teacher.query.filter(
        Teacher.institution_id == institution_id
    ).all()

    used_numbers = set()

    for teacher in teachers:

        if not teacher.roll_no:
            continue

        roll = teacher.roll_no.strip().upper()

        if not roll.startswith(prefix):
            continue

        numeric_part = roll[len(prefix):]

        if numeric_part.isdigit():

            used_numbers.add(
                int(numeric_part)
            )

    number = 1

    while number in used_numbers:
        number += 1

    return f"{prefix}{number:03d}"


# ============================================================
# TEACHER DETAIL ACCESS
# ============================================================

def _teacher_can_access(teacher):

    if _teacher_is_global_user():
        return True

    institution_id = (
        _teacher_get_user_institution_id()
    )

    if (
        institution_id is None
        or teacher.institution_id != institution_id
    ):
        return False

    if getattr(current_user, "role", None) == "branch_admin":

        branch_id = _teacher_get_user_branch_id()

        if (
            branch_id is None
            or teacher.branch_id != branch_id
        ):
            return False

    return True


# ============================================================
# 1. ALL TEACHERS
# ============================================================

@bp.route("/teachers", methods=["GET"])
@login_required
def all_teachers():

    if not _teacher_can_manage():

        flash(
            "You are not authorized to manage teachers.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        "",
        type=str
    ).strip()

    branch_id = request.args.get(
        "branch_id",
        "",
        type=str
    ).strip()

    gender = request.args.get(
        "gender",
        "",
        type=str
    ).strip().lower()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip().lower()

    active = request.args.get(
        "active",
        "",
        type=str
    ).strip().lower()

    verified = request.args.get(
        "verified",
        "",
        type=str
    ).strip().lower()

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    if page < 1:
        page = 1

    query = _teacher_scope_query(
        Teacher.query
    )

    # --------------------------------------------------------
    # Institution filter
    # --------------------------------------------------------

    if institution_id:

        try:
            selected_institution_id = int(
                institution_id
            )

            if _teacher_is_global_user():

                query = query.filter(
                    Teacher.institution_id
                    == selected_institution_id
                )

        except ValueError:

            institution_id = ""

    # --------------------------------------------------------
    # Branch filter
    # --------------------------------------------------------

    if branch_id:

        try:

            selected_branch_id = int(
                branch_id
            )

            query = query.filter(
                Teacher.branch_id
                == selected_branch_id
            )

        except ValueError:

            branch_id = ""

    # --------------------------------------------------------
    # Search
    # --------------------------------------------------------

    if search:

        search_value = f"%{search}%"

        query = query.filter(
            or_(
                Teacher.full_name.ilike(
                    search_value
                ),

                Teacher.username.ilike(
                    search_value
                ),

                Teacher.email.ilike(
                    search_value
                ),

                Teacher.roll_no.ilike(
                    search_value
                ),

                Teacher.phone.ilike(
                    search_value
                ),

                Teacher.qualification.ilike(
                    search_value
                ),

                Teacher.specialization.ilike(
                    search_value
                ),
            )
        )

    # --------------------------------------------------------
    # Gender
    # --------------------------------------------------------

    if gender in TEACHER_GENDERS:

        query = query.filter(
            func.lower(Teacher.gender)
            == gender
        )

    # --------------------------------------------------------
    # Status
    # --------------------------------------------------------

    if status in TEACHER_STATUSES:

        query = query.filter(
            Teacher.status == status
        )

    # --------------------------------------------------------
    # Active
    # --------------------------------------------------------

    if active == "1":

        query = query.filter(
            Teacher.is_active.is_(True)
        )

    elif active == "0":

        query = query.filter(
            Teacher.is_active.is_(False)
        )

    # --------------------------------------------------------
    # Verified
    # --------------------------------------------------------

    if verified == "1":

        query = query.filter(
            Teacher.is_verified.is_(True)
        )

    elif verified == "0":

        query = query.filter(
            Teacher.is_verified.is_(False)
        )

    # --------------------------------------------------------
    # Ordering
    # --------------------------------------------------------

    query = query.order_by(
        Teacher.full_name.asc(),
        Teacher.id.desc()
    )

    # --------------------------------------------------------
    # Pagination
    # --------------------------------------------------------

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    teachers = pagination.items

    # --------------------------------------------------------
    # Filter dropdown data
    # --------------------------------------------------------

    selected_institution_for_branches = None

    if institution_id:

        try:

            selected_institution_for_branches = int(
                institution_id
            )

        except ValueError:
            pass

    elif not _teacher_is_global_user():

        selected_institution_for_branches = (
            _teacher_get_user_institution_id()
        )

    institutions = (
        _teacher_allowed_institutions()
    )

    branches = _teacher_allowed_branches(
        selected_institution_for_branches
    )

    # --------------------------------------------------------
    # Statistics
    # --------------------------------------------------------

    scoped_query = _teacher_scope_query(
        Teacher.query
    )

    total_teachers = scoped_query.count()

    active_teachers = scoped_query.filter(
        Teacher.is_active.is_(True),
        Teacher.status == "active"
    ).count()

    inactive_teachers = scoped_query.filter(
        Teacher.is_active.is_(False)
    ).count()

    verified_teachers = scoped_query.filter(
        Teacher.is_verified.is_(True)
    ).count()

    suspended_teachers = scoped_query.filter(
        Teacher.status == "suspended"
    ).count()

    resigned_teachers = scoped_query.filter(
        Teacher.status == "resigned"
    ).count()

    return render_template(
        "backend/pages/teachers/all_teachers.html",

        teachers=teachers,
        pagination=pagination,

        institutions=institutions,
        branches=branches,

        teacher_genders=TEACHER_GENDERS,
        teacher_statuses=TEACHER_STATUSES,

        search=search,
        institution_id=institution_id,
        branch_id=branch_id,
        gender=gender,
        status=status,
        active=active,
        verified=verified,
        per_page=per_page,

        total_teachers=total_teachers,
        active_teachers=active_teachers,
        inactive_teachers=inactive_teachers,
        verified_teachers=verified_teachers,
        suspended_teachers=suspended_teachers,
        resigned_teachers=resigned_teachers,

        user=current_user,
    )

