# ============================================================
# ALL TEACHER SUBJECTS
# ============================================================

@bp.route("/teacher-subjects", methods=["GET"])
@login_required
def all_teacher_subjects():

    if not _teacher_subject_can_manage():
        flash(
            "You are not authorized to manage teacher subject assignments.",
            "danger"
        )
        return redirect(url_for("main.dashboard"))

    query = TeacherSubject.query

    role = getattr(current_user, "role", None)

    user_institution_id = _teacher_subject_user_institution_id()
    user_branch_id = _teacher_subject_user_branch_id()

    # ========================================================
    # SECURITY SCOPE
    # ========================================================

    if user_institution_id:
        query = query.filter(
            TeacherSubject.institution_id == user_institution_id
        )

    if role == "branch_admin" and user_branch_id:
        query = query.filter(
            TeacherSubject.branch_id == user_branch_id
        )

    # ========================================================
    # FILTER VALUES
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    teaching_type = request.args.get(
        "teaching_type",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip()

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    # ========================================================
    # SECURITY: INSTITUTION
    # ========================================================

    if user_institution_id:
        institution_id = user_institution_id

    elif institution_id:
        query = query.filter(
            TeacherSubject.institution_id == institution_id
        )

    # ========================================================
    # BRANCH
    # ========================================================

    if role == "branch_admin":
        branch_id = user_branch_id

    if branch_id:
        query = query.filter(
            TeacherSubject.branch_id == branch_id
        )

    # ========================================================
    # TEACHER
    # ========================================================

    if teacher_id:
        query = query.filter(
            TeacherSubject.teacher_id == teacher_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:
        query = query.filter(
            TeacherSubject.subject_id == subject_id
        )

    # ========================================================
    # PROGRAM
    # ========================================================

    if program_id:
        query = query.filter(
            TeacherSubject.program_id == program_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:
        query = query.filter(
            TeacherSubject.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:
        query = query.filter(
            TeacherSubject.section_id == section_id
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if academic_year_id:
        query = query.filter(
            TeacherSubject.academic_year_id ==
            academic_year_id
        )

    # ========================================================
    # TEACHING TYPE
    # ========================================================

    if teaching_type:
        query = query.filter(
            TeacherSubject.teaching_type ==
            teaching_type
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:
        query = query.filter(
            TeacherSubject.status == status
        )

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        query = query.join(
            Teacher,
            Teacher.id == TeacherSubject.teacher_id
        ).join(
            Subject,
            Subject.id == TeacherSubject.subject_id
        ).filter(
            or_(
                Teacher.full_name.ilike(
                    f"%{search}%"
                ),
                Teacher.username.ilike(
                    f"%{search}%"
                ),
                Subject.name.ilike(
                    f"%{search}%"
                ),
                Subject.code.ilike(
                    f"%{search}%"
                )
            )
        )

    # ========================================================
    # RESULTS
    # ========================================================

    teacher_subjects = query.order_by(
        TeacherSubject.created_at.desc()
    ).all()

    # ========================================================
    # FORM/FILTER DATA
    # ========================================================

    institutions = _teacher_subject_allowed_institutions()

    branches = _teacher_subject_allowed_branches(
        institution_id
    )

    # ========================================================
    # TEACHERS
    # ========================================================

    teacher_query = Teacher.query

    if institution_id:
        teacher_query = teacher_query.filter(
            Teacher.institution_id == institution_id
        )

    if branch_id:
        teacher_query = teacher_query.filter(
            Teacher.branch_id == branch_id
        )

    teachers = teacher_query.order_by(
        Teacher.full_name.asc()
    ).all()

    # ========================================================
    # SUBJECTS
    # ========================================================

    subject_query = Subject.query

    if institution_id:
        subject_query = subject_query.filter(
            Subject.institution_id == institution_id
        )

    if branch_id and hasattr(Subject, "branch_id"):
        subject_query = subject_query.filter(
            Subject.branch_id == branch_id
        )

    subjects = subject_query.order_by(
        Subject.name.asc()
    ).all()

    # ========================================================
    # PROGRAMS
    # ========================================================

    program_query = Program.query

    if institution_id:
        program_query = program_query.filter(
            Program.institution_id == institution_id
        )

    if branch_id and hasattr(Program, "branch_id"):
        program_query = program_query.filter(
            Program.branch_id == branch_id
        )

    programs = program_query.order_by(
        Program.name.asc()
    ).all()

    # ========================================================
    # CLASSES
    # ========================================================

    class_query = Class.query

    if institution_id:
        class_query = class_query.filter(
            Class.institution_id == institution_id
        )

    if branch_id and hasattr(Class, "branch_id"):
        class_query = class_query.filter(
            Class.branch_id == branch_id
        )

    classes = class_query.order_by(
        Class.name.asc()
    ).all()

    # ========================================================
    # SECTIONS
    # ========================================================

    section_query = Section.query

    if institution_id:
        section_query = section_query.filter(
            Section.institution_id == institution_id
        )

    if branch_id and hasattr(Section, "branch_id"):
        section_query = section_query.filter(
            Section.branch_id == branch_id
        )

    sections = section_query.order_by(
        Section.name.asc()
    ).all()

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    academic_year_query = AcademicYear.query

    if (
        institution_id
        and hasattr(AcademicYear, "institution_id")
    ):
        academic_year_query = academic_year_query.filter(
            AcademicYear.institution_id == institution_id
        )

    academic_years = academic_year_query.order_by(
        AcademicYear.id.desc()
    ).all()

    # ========================================================
    # FILTER OBJECT
    # ========================================================

    filters = {
        "institution_id": institution_id,
        "branch_id": branch_id,
        "teacher_id": teacher_id,
        "subject_id": subject_id,
        "program_id": program_id,
        "class_id": class_id,
        "section_id": section_id,
        "academic_year_id": academic_year_id,
        "teaching_type": teaching_type,
        "status": status,
        "search": search,
    }

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/all_teacher_subjects.html",

        user=current_user,

        teacher_subjects=teacher_subjects,

        institutions=institutions,
        branches=branches,
        teachers=teachers,
        subjects=subjects,
        programs=programs,
        classes=classes,
        sections=sections,
        academic_years=academic_years,

        teacher_subject_types=
            TEACHER_SUBJECT_TYPES,

        teacher_subject_statuses=
            TEACHER_SUBJECT_STATUSES,

        filters=filters,
    )


# ============================================================
# ADD TEACHER SUBJECT
# ============================================================


# ============================================================
# ADD TEACHER SUBJECT ASSIGNMENTS
# ============================================================
# ============================================================
# TEACHER SUBJECT / ASSIGNMENT
# ADD MULTIPLE TEACHER ASSIGNMENTS
#
# ROLE SCOPE
# ------------------------------------------------------------
# superadmin   -> all institutions + all branches
# school_admin -> own institution + all its branches
# branch_admin -> own institution + ONLY own branch
# ============================================================

@bp.route(
    "/teacher-subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_teacher_subject():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = (
        getattr(current_user, "role", None) or ""
    ).strip().lower()

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to create teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # BRANCH ADMIN MUST HAVE INSTITUTION + BRANCH
    # ========================================================

    if current_role == "branch_admin":

        if not current_institution_id:

            flash(
                "Your branch admin account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        if not current_branch_id:

            flash(
                "Your branch admin account is not linked to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # SCHOOL ADMIN MUST HAVE INSTITUTION
    # ========================================================

    if current_role == "school_admin":

        if not current_institution_id:

            flash(
                "Your school admin account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # INITIAL DATA
    # ========================================================

    institutions = []

    branches = []

    academic_years = []

    teachers = []

    programs = []

    classes = []

    subjects = []

    sections = []

    # ========================================================
    # LOAD INSTITUTIONS
    # ========================================================

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institution = (
            Institution.query
            .filter(
                Institution.id == current_institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Institution not found.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        institutions = [
            institution
        ]

    # ========================================================
    # HELPER: SAFE INTEGER
    # ========================================================

    def safe_int(value):

        try:

            if value is None:
                return None

            value = str(value).strip()

            if not value:
                return None

            return int(value)

        except (
            TypeError,
            ValueError
        ):

            return None

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # ==================================================
            # FORM VALUES
            # ==================================================

            institution_id_raw = (
                request.form.get(
                    "institution_id"
                )
                or ""
            ).strip()

            branch_id_raw = (
                request.form.get(
                    "branch_id"
                )
                or ""
            ).strip()

            academic_year_id_raw = (
                request.form.get(
                    "academic_year_id"
                )
                or ""
            ).strip()

            teaching_type = (
                request.form.get(
                    "teaching_type"
                )
                or "teacher"
            ).strip().lower()

            status = (
                request.form.get(
                    "status"
                )
                or "active"
            ).strip().lower()

            start_date_raw = (
                request.form.get(
                    "start_date"
                )
                or ""
            ).strip()

            end_date_raw = (
                request.form.get(
                    "end_date"
                )
                or ""
            ).strip()

            notes = (
                request.form.get(
                    "notes"
                )
                or ""
            ).strip()

            is_primary = (
                request.form.get(
                    "is_primary"
                )
                == "1"
            )

            # ==================================================
            # MULTIPLE ROWS
            # ==================================================

            teacher_ids = request.form.getlist(
                "teacher_ids"
            )

            assignment_types = request.form.getlist(
                "assignment_type"
            )

            program_ids = request.form.getlist(
                "program_ids"
            )

            class_ids = request.form.getlist(
                "class_ids"
            )

            subject_ids = request.form.getlist(
                "subject_ids"
            )

            section_ids = request.form.getlist(
                "section_ids"
            )

            # ==================================================
            # BASIC REQUIRED VALUES
            # ==================================================

            if not teacher_ids:

                raise ValueError(
                    "Please add at least one teacher assignment."
                )

            if not academic_year_id_raw:

                raise ValueError(
                    "Academic Year is required."
                )

            if not branch_id_raw:

                raise ValueError(
                    "Branch is required."
                )

            # ==================================================
            # INSTITUTION
            # ==================================================

            submitted_institution_id = safe_int(
                institution_id_raw
            )

            submitted_branch_id = safe_int(
                branch_id_raw
            )

            academic_year_id = safe_int(
                academic_year_id_raw
            )

            # ==================================================
            # SUPERADMIN
            # ==================================================

            if current_role == "superadmin":

                if not submitted_institution_id:

                    raise ValueError(
                        "Institution is required."
                    )

                institution_id = (
                    submitted_institution_id
                )

            # ==================================================
            # SCHOOL ADMIN
            # ==================================================

            elif current_role == "school_admin":

                institution_id = (
                    current_institution_id
                )

                # ----------------------------------------------
                # SECURITY:
                # school_admin cannot submit another institution
                # ----------------------------------------------

                if (
                    submitted_institution_id
                    and submitted_institution_id
                    != current_institution_id
                ):

                    raise ValueError(
                        "You cannot create assignments for another institution."
                    )

            # ==================================================
            # BRANCH ADMIN
            # ==================================================

            else:

                institution_id = (
                    current_institution_id
                )

                # ----------------------------------------------
                # SECURITY:
                # branch_admin cannot change institution
                # ----------------------------------------------

                if (
                    submitted_institution_id
                    and submitted_institution_id
                    != current_institution_id
                ):

                    raise ValueError(
                        "You cannot create assignments for another institution."
                    )

                # ----------------------------------------------
                # SECURITY:
                # branch_admin MUST use current branch
                # ----------------------------------------------

                if (
                    submitted_branch_id
                    != current_branch_id
                ):

                    raise ValueError(
                        "You can only create assignments for your own branch."
                    )

            # ==================================================
            # BRANCH ID
            # ==================================================

            if not submitted_branch_id:

                raise ValueError(
                    "Branch is required."
                )

            branch_id = (
                submitted_branch_id
            )

            # ==================================================
            # INSTITUTION VALIDATION
            # ==================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == institution_id
                )
                .first()
            )

            if not institution:

                raise ValueError(
                    "Selected institution does not exist."
                )

            # ==================================================
            # BRANCH VALIDATION
            # ==================================================

            branch_query = (
                Branch.query
                .filter(
                    Branch.id == branch_id,
                    Branch.institution_id == institution_id,
                )
            )

            # ----------------------------------------------
            # EXTRA BRANCH ADMIN SECURITY
            # ----------------------------------------------

            if current_role == "branch_admin":

                branch_query = branch_query.filter(
                    Branch.id == current_branch_id
                )

            branch = (
                branch_query
                .first()
            )

            if not branch:

                raise ValueError(
                    "Selected branch is not available for your account."
                )

            # ==================================================
            # ACADEMIC YEAR VALIDATION
            # ==================================================

            if not academic_year_id:

                raise ValueError(
                    "Academic Year is required."
                )

            academic_year = (
                AcademicYear.query
                .filter(
                    AcademicYear.id
                    == academic_year_id,

                    AcademicYear.institution_id
                    == institution_id,
                )
                .first()
            )

            if not academic_year:

                raise ValueError(
                    "Selected academic year does not belong to this institution."
                )

            # ==================================================
            # TEACHING TYPE
            # ==================================================

            allowed_teaching_types = {
                "teacher",
                "assistant",
                "coordinator",
                "substitute",
            }

            if teaching_type not in allowed_teaching_types:

                raise ValueError(
                    "Invalid teaching type."
                )

            # ==================================================
            # STATUS
            # ==================================================

            allowed_statuses = {
                "active",
                "inactive",
            }

            if status not in allowed_statuses:

                raise ValueError(
                    "Invalid assignment status."
                )

            # ==================================================
            # DATE PARSING
            # ==================================================

            start_date = None
            end_date = None

            if start_date_raw:

                try:

                    start_date = datetime.strptime(
                        start_date_raw,
                        "%Y-%m-%d"
                    ).date()

                except ValueError:

                    raise ValueError(
                        "Invalid start date."
                    )

            if end_date_raw:

                try:

                    end_date = datetime.strptime(
                        end_date_raw,
                        "%Y-%m-%d"
                    ).date()

                except ValueError:

                    raise ValueError(
                        "Invalid end date."
                    )

            # ==================================================
            # DATE RANGE
            # ==================================================

            if (
                start_date
                and end_date
                and end_date < start_date
            ):

                raise ValueError(
                    "End Date cannot be earlier than Start Date."
                )

            # ==================================================
            # ROW COUNTS
            # ==================================================

            row_count = len(
                teacher_ids
            )

            if len(assignment_types) != row_count:

                raise ValueError(
                    "Assignment data is incomplete. "
                    "Please make sure every row has an assignment type."
                )

            # ==================================================
            # LIST HELPER
            # ==================================================

            def get_list_value(
                values,
                index
            ):

                if index >= len(values):

                    return None

                value = (
                    values[index]
                    or ""
                ).strip()

                return value or None

            # ==================================================
            # DUPLICATES IN CURRENT FORM
            # ==================================================

            submitted_keys = set()

            # ==================================================
            # CREATED COUNT
            # ==================================================

            created_count = 0

            # ==================================================
            # PROCESS EACH ROW
            # ==================================================

            for index in range(
                row_count
            ):

                row_number = (
                    index + 1
                )

                # ==============================================
                # TEACHER
                # ==============================================

                teacher_id = safe_int(
                    get_list_value(
                        teacher_ids,
                        index
                    )
                )

                if not teacher_id:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Teacher is required."
                    )

                # ==============================================
                # ASSIGNMENT TYPE
                # ==============================================

                assignment_type = (
                    get_list_value(
                        assignment_types,
                        index
                    )
                    or ""
                ).lower()

                allowed_assignment_types = {
                    "program",
                    "class",
                    "subject",
                    "section",
                }

                if (
                    assignment_type
                    not in allowed_assignment_types
                ):

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Invalid assignment type."
                    )

                # ==============================================
                # TEACHER SECURITY
                # ==============================================

                teacher_query = (
                    Teacher.query
                    .filter(
                        Teacher.id
                        == teacher_id,

                        Teacher.institution_id
                        == institution_id,

                        Teacher.branch_id
                        == branch_id,
                    )
                )

                # branch_admin is already restricted by branch_id
                teacher = (
                    teacher_query
                    .first()
                )

                if not teacher:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "Selected teacher does not belong to "
                        "the selected branch."
                    )

                # ==============================================
                # PROGRAM
                # ==============================================

                program_id = None

                program_id_raw = get_list_value(
                    program_ids,
                    index
                )

                if assignment_type in {
                    "program",
                    "class",
                    "subject",
                    "section",
                }:

                    if not program_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Program is required."
                        )

                    program_id = safe_int(
                        program_id_raw
                    )

                    if not program_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid program."
                        )

                # ==============================================
                # PROGRAM SECURITY
                # ==============================================

                program = None

                if program_id:

                    program = (
                        Program.query
                        .filter(
                            Program.id
                            == program_id,

                            Program.institution_id
                            == institution_id,
                        )
                        .first()
                    )

                    if not program:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected program does not belong "
                            "to this institution."
                        )

                    # ------------------------------------------
                    # PROGRAM BRANCH SCOPE
                    #
                    # branch_id = NULL
                    # means institution-wide
                    #
                    # branch_id = current branch
                    # means branch-specific
                    # ------------------------------------------

                    if (
                        program.branch_id is not None
                        and program.branch_id != branch_id
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected program does not belong "
                            "to this branch."
                        )

                    # ------------------------------------------
                    # PROGRAM STATUS
                    # ------------------------------------------

                    if (
                        getattr(
                            program,
                            "status",
                            "active"
                        )
                        != "active"
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected program is not active."
                        )

                # ==============================================
                # CLASS
                # ==============================================

                class_id = None

                class_id_raw = get_list_value(
                    class_ids,
                    index
                )

                if assignment_type in {
                    "class",
                    "subject",
                    "section",
                }:

                    if not class_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Class is required."
                        )

                    class_id = safe_int(
                        class_id_raw
                    )

                    if not class_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid class."
                        )

                    # ------------------------------------------
                    # CLASS MUST MATCH:
                    # institution
                    # branch
                    # program
                    # academic year
                    # ------------------------------------------

                    class_obj = (
                        Class.query
                        .filter(
                            Class.id
                            == class_id,

                            Class.institution_id
                            == institution_id,

                            Class.branch_id
                            == branch_id,

                            Class.program_id
                            == program_id,

                            Class.academic_year_id
                            == academic_year_id,
                        )
                        .first()
                    )

                    if not class_obj:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected class does not match "
                            "the selected program, branch, "
                            "or academic year."
                        )

                # ==============================================
                # SUBJECT
                # ==============================================

                subject_id = None

                subject_id_raw = get_list_value(
                    subject_ids,
                    index
                )

                if assignment_type in {
                    "subject",
                    "section",
                }:

                    if not subject_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Subject is required."
                        )

                    subject_id = safe_int(
                        subject_id_raw
                    )

                    if not subject_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid subject."
                        )

                    # ------------------------------------------
                    # SUBJECT BASE QUERY
                    # ------------------------------------------

                    subject = (
                        Subject.query
                        .filter(
                            Subject.id
                            == subject_id,

                            Subject.institution_id
                            == institution_id,
                        )
                        .first()
                    )

                    if not subject:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to this institution."
                        )

                    # ------------------------------------------
                    # SUBJECT BRANCH
                    # ------------------------------------------

                    if (
                        subject.branch_id is not None
                        and subject.branch_id != branch_id
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to this branch."
                        )

                    # ------------------------------------------
                    # SUBJECT PROGRAM
                    # ------------------------------------------

                    subject_program_id = getattr(
                        subject,
                        "program_id",
                        None
                    )

                    if (
                        subject_program_id is not None
                        and subject_program_id != program_id
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject does not belong "
                            "to the selected program."
                        )

                    # ------------------------------------------
                    # SUBJECT STATUS
                    # ------------------------------------------

                    if (
                        getattr(
                            subject,
                            "status",
                            "active"
                        )
                        != "active"
                    ):

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected subject is not active."
                        )

                # ==============================================
                # SECTION
                # ==============================================

                section_id = None

                section_id_raw = get_list_value(
                    section_ids,
                    index
                )

                if assignment_type == "section":

                    if not section_id_raw:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Section is required."
                        )

                    section_id = safe_int(
                        section_id_raw
                    )

                    if not section_id:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Invalid section."
                        )

                    # ------------------------------------------
                    # SECTION MUST MATCH:
                    # institution
                    # branch
                    # class
                    # academic year
                    # ------------------------------------------

                    section = (
                        Section.query
                        .filter(
                            Section.id
                            == section_id,

                            Section.institution_id
                            == institution_id,

                            Section.branch_id
                            == branch_id,

                            Section.class_id
                            == class_id,

                            Section.academic_year_id
                            == academic_year_id,
                        )
                        .first()
                    )

                    if not section:

                        raise ValueError(
                            f"Assignment {row_number}: "
                            "Selected section does not belong "
                            "to the selected class, branch, "
                            "or academic year."
                        )

                # ==============================================
                # CLEAN LOWER-LEVEL VALUES
                # ==============================================

                if assignment_type == "program":

                    class_id = None
                    subject_id = None
                    section_id = None

                elif assignment_type == "class":

                    subject_id = None
                    section_id = None

                elif assignment_type == "subject":

                    section_id = None

                # ==============================================
                # FORM DUPLICATE KEY
                # ==============================================

                duplicate_key = (
                    teacher_id,
                    academic_year_id,
                    branch_id,
                    assignment_type,
                    program_id,
                    class_id,
                    subject_id,
                    section_id,
                )

                if duplicate_key in submitted_keys:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "This same teacher assignment "
                        "appears more than once."
                    )

                submitted_keys.add(
                    duplicate_key
                )

                # ==============================================
                # DATABASE DUPLICATE CHECK
                # ==============================================

                duplicate_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.institution_id
                        == institution_id,

                        TeacherSubject.branch_id
                        == branch_id,

                        TeacherSubject.teacher_id
                        == teacher_id,

                        TeacherSubject.academic_year_id
                        == academic_year_id,

                        TeacherSubject.assignment_type
                        == assignment_type,

                        TeacherSubject.scope
                        == "specific",
                    )
                )

                # ----------------------------------------------
                # PROGRAM
                # ----------------------------------------------

                if program_id is None:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.program_id.is_(None)
                        )
                    )

                else:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.program_id
                            == program_id
                        )
                    )

                # ----------------------------------------------
                # CLASS
                # ----------------------------------------------

                if class_id is None:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.class_id.is_(None)
                        )
                    )

                else:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.class_id
                            == class_id
                        )
                    )

                # ----------------------------------------------
                # SUBJECT
                # ----------------------------------------------

                if subject_id is None:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.subject_id.is_(None)
                        )
                    )

                else:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.subject_id
                            == subject_id
                        )
                    )

                # ----------------------------------------------
                # SECTION
                # ----------------------------------------------

                if section_id is None:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.section_id.is_(None)
                        )
                    )

                else:

                    duplicate_query = (
                        duplicate_query
                        .filter(
                            TeacherSubject.section_id
                            == section_id
                        )
                    )

                existing_assignment = (
                    duplicate_query
                    .first()
                )

                if existing_assignment:

                    raise ValueError(
                        f"Assignment {row_number}: "
                        "This teacher is already assigned "
                        "to the selected target."
                    )

                # ==============================================
                # CREATE
                # ==============================================

                assignment = TeacherSubject(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        branch_id
                    ),

                    teacher_id=(
                        teacher_id
                    ),

                    program_id=(
                        program_id
                    ),

                    class_id=(
                        class_id
                    ),

                    subject_id=(
                        subject_id
                    ),

                    section_id=(
                        section_id
                    ),

                    academic_year_id=(
                        academic_year_id
                    ),

                    assignment_type=(
                        assignment_type
                    ),

                    scope="specific",

                    teaching_type=(
                        teaching_type
                    ),

                    is_primary=(
                        is_primary
                    ),

                    status=(
                        status
                    ),

                    start_date=(
                        start_date
                    ),

                    end_date=(
                        end_date
                    ),

                    notes=(
                        notes or None
                    ),
                )

                db.session.add(
                    assignment
                )

                created_count += 1

            # ==================================================
            # COMMIT
            # ==================================================

            db.session.commit()

            # ==================================================
            # SUCCESS
            # ==================================================

            flash(
                f"{created_count} teacher assignment(s) "
                "created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_teacher_subjects"
                )
            )

        # ========================================================
        # VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            flash(
                str(exc),
                "danger"
            )

        # ========================================================
        # DATABASE ERROR
        # ========================================================

        except IntegrityError:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher assignment IntegrityError"
            )

            flash(
                "Unable to save teacher assignment because "
                "of a database constraint.",
                "danger"
            )

        # ========================================================
        # GENERAL ERROR
        # ========================================================

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Teacher assignment creation failed"
            )

            flash(
                "An unexpected error occurred while creating "
                "teacher assignments.",
                "danger"
            )

    # ============================================================
    # SELECTED INSTITUTION
    # ============================================================

    selected_institution_id = None

    if current_role == "superadmin":

        if request.method == "POST":

            selected_institution_id = safe_int(
                request.form.get(
                    "institution_id"
                )
            )

    else:

        selected_institution_id = (
            current_institution_id
        )

    # ============================================================
    # SELECTED BRANCH
    # ============================================================

    selected_branch_id = None

    if current_role == "branch_admin":

        # ----------------------------------------------
        # BRANCH ADMIN:
        # ALWAYS CURRENT BRANCH
        # ----------------------------------------------

        selected_branch_id = (
            current_branch_id
        )

    elif request.method == "POST":

        selected_branch_id = safe_int(
            request.form.get(
                "branch_id"
            )
        )

    # ============================================================
    # SELECTED ACADEMIC YEAR
    # ============================================================

    selected_academic_year_id = None

    if request.method == "POST":

        selected_academic_year_id = safe_int(
            request.form.get(
                "academic_year_id"
            )
        )

    # ============================================================
    # LOAD BRANCHES
    # ============================================================

    if current_role == "superadmin":

        # ----------------------------------------------
        # SUPERADMIN:
        # Branches depend on selected institution
        # ----------------------------------------------

        if selected_institution_id:

            branches = (
                Branch.query
                .filter(
                    Branch.institution_id
                    == selected_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

    elif current_role == "school_admin":

        # ----------------------------------------------
        # SCHOOL ADMIN:
        # ALL BRANCHES IN OWN INSTITUTION
        # ----------------------------------------------

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif current_role == "branch_admin":

        # ----------------------------------------------
        # BRANCH ADMIN:
        # ONLY CURRENT BRANCH
        # ----------------------------------------------

        current_branch = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id,

                Branch.institution_id
                == current_institution_id,
            )
            .first()
        )

        if current_branch:

            branches = [
                current_branch
            ]

        else:

            branches = []

    # ============================================================
    # LOAD ACADEMIC YEARS
    # ============================================================

    if selected_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == selected_institution_id
            )
            .order_by(
                AcademicYear.start_date.desc()
            )
            .all()
        )

    # ============================================================
    # LOAD TEACHERS
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
    ):

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == selected_institution_id,

                Teacher.branch_id
                == selected_branch_id,
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD PROGRAMS
    # ============================================================

    if selected_institution_id:

        program_query = (
            Program.query
            .filter(
                Program.institution_id
                == selected_institution_id
            )
        )

        if selected_branch_id:

            program_query = (
                program_query
                .filter(
                    db.or_(
                        Program.branch_id
                        == selected_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
            )

        programs = (
            program_query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD CLASSES
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
        and selected_academic_year_id
    ):

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == selected_institution_id,

                Class.branch_id
                == selected_branch_id,

                Class.academic_year_id
                == selected_academic_year_id,
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD SUBJECTS
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
    ):

        subject_query = (
            Subject.query
            .filter(
                Subject.institution_id
                == selected_institution_id
            )
        )

        subject_query = (
            subject_query
            .filter(
                db.or_(
                    Subject.branch_id
                    == selected_branch_id,

                    Subject.branch_id.is_(None)
                )
            )
        )

        subjects = (
            subject_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ============================================================
    # LOAD SECTIONS
    # ============================================================

    if (
        selected_institution_id
        and selected_branch_id
        and selected_academic_year_id
    ):

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == selected_institution_id,

                Section.branch_id
                == selected_branch_id,

                Section.academic_year_id
                == selected_academic_year_id,
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ============================================================
    # FORM VALUES
    # ============================================================

    form_values = {

        "institution_id": (
            selected_institution_id
            or ""
        ),

        "branch_id": (
            selected_branch_id
            or ""
        ),

        "academic_year_id": (
            selected_academic_year_id
            or ""
        ),

        "teaching_type": (
            request.form.get(
                "teaching_type",
                "teacher"
            )
            if request.method == "POST"
            else "teacher"
        ),

        "status": (
            request.form.get(
                "status",
                "active"
            )
            if request.method == "POST"
            else "active"
        ),

        "start_date": (
            request.form.get(
                "start_date",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "end_date": (
            request.form.get(
                "end_date",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "notes": (
            request.form.get(
                "notes",
                ""
            )
            if request.method == "POST"
            else ""
        ),

        "is_primary": (
            request.form.get(
                "is_primary"
            )
            == "1"
            if request.method == "POST"
            else True
        ),
    }

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(

        "backend/pages/teacher_subjects/"
        "add_teacher_subject.html",

        # --------------------------------------------------------
        # DATA
        # --------------------------------------------------------

        institutions=institutions,

        branches=branches,

        academic_years=academic_years,

        teachers=teachers,

        programs=programs,

        classes=classes,

        subjects=subjects,

        sections=sections,

        # --------------------------------------------------------
        # FORM
        # --------------------------------------------------------

        form_values=form_values,

        # --------------------------------------------------------
        # USER
        # --------------------------------------------------------

        user=current_user,

        current_user=current_user,

        # --------------------------------------------------------
        # ROLE
        # --------------------------------------------------------

        current_role=current_role,

        is_superadmin=(
            current_role
            == "superadmin"
        ),

        is_school_admin=(
            current_role
            == "school_admin"
        ),

        is_branch_admin=(
            current_role
            == "branch_admin"
        ),

        # --------------------------------------------------------
        # CURRENT SCOPE
        # --------------------------------------------------------

        current_institution_id=(
            current_institution_id
        ),

        current_branch_id=(
            current_branch_id
        ),

        # --------------------------------------------------------
        # IMPORTANT FOR TEMPLATE
        # --------------------------------------------------------

        branch_locked=(
            current_role
            == "branch_admin"
        ),
    )





# ============================================================
# VIEW TEACHER SUBJECT
# ============================================================
# ============================================================
# VIEW TEACHER SUBJECT ASSIGNMENT
# ============================================================

# ============================================================
# VIEW TEACHER SUBJECT
# ============================================================

# ============================================================
# VIEW TEACHER SUBJECT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>",
    methods=["GET"]
)
@login_required
def view_teacher_subject(teacher_subject_id):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    allowed_roles = {
        "superadmin",
        "institution_admin",
        "branch_admin",
        "teacher",
    }

    if (
        not _teacher_can_manage()
        and getattr(current_user, "role", None)
        not in allowed_roles
    ):
        flash(
            "You are not authorized to view teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # LOAD ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .options(
            db.joinedload(
                TeacherSubject.institution
            ),

            db.joinedload(
                TeacherSubject.branch
            ),

            db.joinedload(
                TeacherSubject.teacher
            ),

            db.joinedload(
                TeacherSubject.subject
            ),

            db.joinedload(
                TeacherSubject.program
            ),

            db.joinedload(
                TeacherSubject.class_
            ),

            db.joinedload(
                TeacherSubject.section
            ),

            db.joinedload(
                TeacherSubject.academic_year
            ),
        )
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first()
    )

    # ========================================================
    # NOT FOUND
    # ========================================================

    if not assignment:

        flash(
            "Teacher subject assignment was not found.",
            "warning"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # CURRENT USER ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # ========================================================
    # SUPERADMIN
    # ========================================================

    if role == "superadmin":

        pass

    # ========================================================
    # INSTITUTION ADMIN
    # ========================================================

    elif role == "institution_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if (
            not user_institution_id
            or assignment.institution_id
            != user_institution_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # BRANCH ADMIN
    # ========================================================

    elif role == "branch_admin":

        user_institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        user_branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if (
            not user_institution_id
            or not user_branch_id
            or assignment.institution_id
            != user_institution_id
            or assignment.branch_id
            != user_branch_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # TEACHER
    # ========================================================

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        # ----------------------------------------------------
        # Teacher must have a linked teacher record
        # ----------------------------------------------------

        if current_teacher_id is None:

            flash(
                "Your teacher account is not linked to a teacher record.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        # ----------------------------------------------------
        # Only own assignment
        # ----------------------------------------------------

        if (
            assignment.teacher_id
            != current_teacher_id
        ):

            flash(
                "You are not authorized to view this assignment.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

    # ========================================================
    # OTHER ROLES
    # ========================================================

    else:

        flash(
            "You are not authorized to view teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/view_teacher_subject.html",
        assignment=assignment,
        user=current_user,
    )

# ============================================================
# EDIT TEACHER SUBJECT
# ============================================================
# ============================================================
# EDIT TEACHER SUBJECT / ASSIGNMENT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_teacher_subject(teacher_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = (
        getattr(current_user, "role", None) or ""
    ).strip().lower()

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to edit teacher assignments.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # GET CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD ASSIGNMENT
    # ========================================================

    assignment = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first()
    )

    if not assignment:

        flash(
            "Teacher assignment not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # ASSIGNMENT ACCESS SECURITY
    # ========================================================

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id
        )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not user_institution_id:

            flash(
                "Your account is not linked to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id,
            TeacherSubject.institution_id == user_institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    else:

        if not user_institution_id or not user_branch_id:

            flash(
                "Your account is not properly linked to an institution and branch.",
                "danger"
            )

            return redirect(
                url_for("main.all_teacher_subjects")
            )

        assignment_query = TeacherSubject.query.filter(
            TeacherSubject.id == teacher_subject_id,
            TeacherSubject.institution_id == user_institution_id,
            TeacherSubject.branch_id == user_branch_id
        )

    assignment = assignment_query.first()

    if not assignment:

        flash(
            "You do not have permission to edit this teacher assignment.",
            "danger"
        )

        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # FORM VALUES
    # ========================================================

    form_values = {}

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ----------------------------------------------------
        # READ FORM VALUES
        # ----------------------------------------------------

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        teacher_id = request.form.get(
            "teacher_id",
            type=int
        )

        assignment_type = (
            request.form.get(
                "assignment_type",
                ""
            )
            .strip()
            .lower()
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        class_id = request.form.get(
            "class_id",
            type=int
        )

        subject_id = request.form.get(
            "subject_id",
            type=int
        )

        section_id = request.form.get(
            "section_id",
            type=int
        )

        teaching_type = (
            request.form.get(
                "teaching_type",
                "teacher"
            )
            .strip()
            .lower()
        )

        status = (
            request.form.get(
                "status",
                "active"
            )
            .strip()
            .lower()
        )

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
            or None
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
            or None
        )

        is_primary = (
            request.form.get("is_primary")
            in {
                "1",
                "true",
                "True",
                "on",
                "yes"
            }
        )

        notes = (
            request.form.get(
                "notes",
                ""
            )
            .strip()
            or None
        )

        scope = (
            request.form.get(
                "scope",
                "specific"
            )
            .strip()
            .lower()
        )

        # ----------------------------------------------------
        # KEEP FORM VALUES FOR ERROR RENDERING
        # ----------------------------------------------------

        form_values = {
            "institution_id": institution_id,
            "branch_id": branch_id,
            "academic_year_id": academic_year_id,
            "teacher_id": teacher_id,
            "assignment_type": assignment_type,
            "program_id": program_id,
            "class_id": class_id,
            "subject_id": subject_id,
            "section_id": section_id,
            "teaching_type": teaching_type,
            "status": status,
            "start_date": start_date or "",
            "end_date": end_date or "",
            "is_primary": is_primary,
            "notes": notes or "",
            "scope": scope,
        }

        # ====================================================
        # ROLE-BASED INSTITUTION / BRANCH SECURITY
        # ====================================================

        if current_role == "school_admin":

            institution_id = user_institution_id

            form_values["institution_id"] = institution_id

            if not institution_id:

                flash(
                    "Your account is not linked to an institution.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_teacher_subjects")
                )

        elif current_role == "branch_admin":

            institution_id = user_institution_id
            branch_id = user_branch_id

            form_values["institution_id"] = institution_id
            form_values["branch_id"] = branch_id

            if not institution_id or not branch_id:

                flash(
                    "Your account is not properly linked to an institution and branch.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_teacher_subjects")
                )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        errors = []

        if not institution_id:
            errors.append(
                "Institution is required."
            )

        if not branch_id:
            errors.append(
                "Branch is required."
            )

        if not academic_year_id:
            errors.append(
                "Academic year is required."
            )

        if not teacher_id:
            errors.append(
                "Teacher is required."
            )

        allowed_assignment_types = {
            "program",
            "class",
            "subject",
            "section",
        }

        if assignment_type not in allowed_assignment_types:

            errors.append(
                "Invalid assignment type."
            )

        allowed_teaching_types = {
            "teacher",
            "assistant",
            "coordinator",
            "substitute",
        }

        if teaching_type not in allowed_teaching_types:

            errors.append(
                "Invalid teaching type."
            )

        allowed_statuses = {
            "active",
            "inactive",
        }

        if status not in allowed_statuses:

            errors.append(
                "Invalid assignment status."
            )

        # ====================================================
        # SCOPE
        # ====================================================

        # TeacherSubject currently represents a specific
        # assignment, therefore force scope=specific.

        scope = "specific"

        # ====================================================
        # ASSIGNMENT HIERARCHY VALIDATION
        # ====================================================

        # ----------------------------------------------------
        # PROGRAM
        # ----------------------------------------------------

        if assignment_type in {
            "program",
            "class",
            "subject",
            "section",
        }:

            if not program_id:

                errors.append(
                    "Program is required for this assignment type."
                )

        # ----------------------------------------------------
        # CLASS
        # ----------------------------------------------------

        if assignment_type in {
            "class",
            "subject",
            "section",
        }:

            if not class_id:

                errors.append(
                    "Class is required for this assignment type."
                )

        # ----------------------------------------------------
        # SUBJECT
        # ----------------------------------------------------

        if assignment_type in {
            "subject",
            "section",
        }:

            if not subject_id:

                errors.append(
                    "Subject is required for this assignment type."
                )

        # ----------------------------------------------------
        # SECTION
        # ----------------------------------------------------

        if assignment_type == "section":

            if not section_id:

                errors.append(
                    "Section is required for section assignment."
                )

        # ----------------------------------------------------
        # CLEAR UNUSED HIERARCHY VALUES
        # ----------------------------------------------------

        if assignment_type == "program":

            class_id = None
            subject_id = None
            section_id = None

        elif assignment_type == "class":

            subject_id = None
            section_id = None

        elif assignment_type == "subject":

            section_id = None

        form_values["program_id"] = program_id
        form_values["class_id"] = class_id
        form_values["subject_id"] = subject_id
        form_values["section_id"] = section_id

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:

                parsed_start_date = datetime.strptime(
                    start_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "Start date must be a valid date."
                )

        if end_date:

            try:

                parsed_end_date = datetime.strptime(
                    end_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                errors.append(
                    "End date must be a valid date."
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            errors.append(
                "End date cannot be earlier than start date."
            )

        # ====================================================
        # INSTITUTION VALIDATION
        # ====================================================

        institution = None

        if institution_id:

            institution = (
                Institution.query
                .filter(
                    Institution.id == institution_id
                )
                .first()
            )

            if not institution:

                errors.append(
                    "Selected institution does not exist."
                )

        # ====================================================
        # BRANCH VALIDATION
        # ====================================================

        branch = None

        if branch_id:

            branch = (
                Branch.query
                .filter(
                    Branch.id == branch_id
                )
                .first()
            )

            if not branch:

                errors.append(
                    "Selected branch does not exist."
                )

            elif institution and branch.institution_id != institution.id:

                errors.append(
                    "Selected branch does not belong to the selected institution."
                )

        # ====================================================
        # ACADEMIC YEAR VALIDATION
        # ====================================================

        academic_year = None

        if academic_year_id:

            academic_year = (
                AcademicYear.query
                .filter(
                    AcademicYear.id == academic_year_id
                )
                .first()
            )

            if not academic_year:

                errors.append(
                    "Selected academic year does not exist."
                )

            elif (
                institution
                and academic_year.institution_id
                != institution.id
            ):

                errors.append(
                    "Selected academic year does not belong to the selected institution."
                )

        # ====================================================
        # TEACHER VALIDATION
        # ====================================================

        teacher = None

        if teacher_id:

            teacher = (
                Teacher.query
                .filter(
                    Teacher.id == teacher_id
                )
                .first()
            )

            if not teacher:

                errors.append(
                    "Selected teacher does not exist."
                )

            else:

                if (
                    institution
                    and teacher.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected teacher does not belong to the selected institution."
                    )

                if (
                    branch
                    and teacher.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected teacher does not belong to the selected branch."
                    )

        # ====================================================
        # PROGRAM VALIDATION
        # ====================================================

        program = None

        if program_id:

            program = (
                Program.query
                .filter(
                    Program.id == program_id
                )
                .first()
            )

            if not program:

                errors.append(
                    "Selected program does not exist."
                )

            else:

                if (
                    institution
                    and program.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected program does not belong to the selected institution."
                    )

                # Program branch can be NULL, meaning
                # institution-wide program.

                if (
                    branch
                    and program.branch_id is not None
                    and program.branch_id != branch.id
                ):

                    errors.append(
                        "Selected program is not available in the selected branch."
                    )

        # ====================================================
        # CLASS VALIDATION
        # ====================================================

        class_obj = None

        if class_id:

            class_obj = (
                Class.query
                .filter(
                    Class.id == class_id
                )
                .first()
            )

            if not class_obj:

                errors.append(
                    "Selected class does not exist."
                )

            else:

                if (
                    institution
                    and class_obj.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected institution."
                    )

                if (
                    branch
                    and class_obj.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected branch."
                    )

                if (
                    academic_year
                    and class_obj.academic_year_id
                    != academic_year.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected academic year."
                    )

                if (
                    program
                    and class_obj.program_id
                    != program.id
                ):

                    errors.append(
                        "Selected class does not belong to the selected program."
                    )

        # ====================================================
        # SUBJECT VALIDATION
        # ====================================================

        subject = None

        if subject_id:

            subject = (
                Subject.query
                .filter(
                    Subject.id == subject_id
                )
                .first()
            )

            if not subject:

                errors.append(
                    "Selected subject does not exist."
                )

            else:

                if (
                    institution
                    and subject.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected subject does not belong to the selected institution."
                    )

                # Subject branch may be NULL,
                # meaning institution-wide subject.

                if (
                    branch
                    and subject.branch_id is not None
                    and subject.branch_id != branch.id
                ):

                    errors.append(
                        "Selected subject is not available in the selected branch."
                    )

                # Subject program may be NULL,
                # meaning it can be institution/branch-wide.

                if (
                    program
                    and subject.program_id is not None
                    and subject.program_id != program.id
                ):

                    errors.append(
                        "Selected subject does not belong to the selected program."
                    )

        # ====================================================
        # SECTION VALIDATION
        # ====================================================

        section = None

        if section_id:

            section = (
                Section.query
                .filter(
                    Section.id == section_id
                )
                .first()
            )

            if not section:

                errors.append(
                    "Selected section does not exist."
                )

            else:

                if (
                    institution
                    and section.institution_id
                    != institution.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected institution."
                    )

                if (
                    branch
                    and section.branch_id
                    != branch.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected branch."
                    )

                if (
                    academic_year
                    and section.academic_year_id
                    != academic_year.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected academic year."
                    )

                if (
                    class_obj
                    and section.class_id
                    != class_obj.id
                ):

                    errors.append(
                        "Selected section does not belong to the selected class."
                    )

        # ====================================================
        # STOP IF VALIDATION ERRORS
        # ====================================================

        if errors:

            for error in errors:

                flash(
                    error,
                    "danger"
                )

        else:

            try:

                # ====================================================
                # DUPLICATE ASSIGNMENT CHECK
                # ====================================================

                duplicate_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.id != assignment.id,

                        TeacherSubject.institution_id
                        == institution_id,

                        TeacherSubject.branch_id
                        == branch_id,

                        TeacherSubject.teacher_id
                        == teacher_id,

                        TeacherSubject.academic_year_id
                        == academic_year_id,

                        TeacherSubject.assignment_type
                        == assignment_type,

                        TeacherSubject.program_id
                        == program_id,

                        TeacherSubject.class_id
                        == class_id,

                        TeacherSubject.subject_id
                        == subject_id,

                        TeacherSubject.section_id
                        == section_id,

                        TeacherSubject.status
                        == "active",
                    )
                )

                duplicate = duplicate_query.first()

                if duplicate:

                    flash(
                        "This teacher assignment already exists.",
                        "danger"
                    )

                else:

                    # ====================================================
                    # UPDATE ASSIGNMENT
                    # ====================================================

                    assignment.institution_id = (
                        institution_id
                    )

                    assignment.branch_id = (
                        branch_id
                    )

                    assignment.teacher_id = (
                        teacher_id
                    )

                    assignment.program_id = (
                        program_id
                    )

                    assignment.subject_id = (
                        subject_id
                    )

                    assignment.class_id = (
                        class_id
                    )

                    assignment.section_id = (
                        section_id
                    )

                    assignment.academic_year_id = (
                        academic_year_id
                    )

                    assignment.assignment_type = (
                        assignment_type
                    )

                    assignment.scope = (
                        "specific"
                    )

                    assignment.teaching_type = (
                        teaching_type
                    )

                    assignment.is_primary = (
                        is_primary
                    )

                    assignment.status = (
                        status
                    )

                    assignment.start_date = (
                        parsed_start_date
                    )

                    assignment.end_date = (
                        parsed_end_date
                    )

                    assignment.notes = (
                        notes
                    )

                    # ====================================================
                    # SAVE
                    # ====================================================

                    db.session.commit()

                    flash(
                        "Teacher assignment updated successfully.",
                        "success"
                    )

                    return redirect(
                        url_for(
                            "main.all_teacher_subjects"
                        )
                    )

            except IntegrityError as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "IntegrityError while updating TeacherSubject %s",
                    teacher_subject_id
                )

                flash(
                    "Could not update the teacher assignment because of a database constraint.",
                    "danger"
                )

            except Exception as exc:

                db.session.rollback()

                current_app.logger.exception(
                    "Error while updating TeacherSubject %s",
                    teacher_subject_id
                )

                flash(
                    "An unexpected error occurred while updating the teacher assignment.",
                    "danger"
                )

    # ========================================================
    # GET / RENDER DATA
    # ========================================================

    # --------------------------------------------------------
    # INSTITUTIONS
    # --------------------------------------------------------

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # --------------------------------------------------------
    # BRANCHES
    # --------------------------------------------------------

    if current_role == "superadmin":

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            branches = (
                Branch.query
                .filter(
                    Branch.id == user_branch_id,
                    Branch.institution_id
                    == user_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

        else:

            branches = (
                Branch.query
                .filter(
                    Branch.institution_id
                    == user_institution_id
                )
                .order_by(
                    Branch.name.asc()
                )
                .all()
            )

    else:

        branches = []

    # --------------------------------------------------------
    # ACADEMIC YEARS
    # --------------------------------------------------------

    if current_role == "superadmin":

        academic_years = (
            AcademicYear.query
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

    elif user_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
            .order_by(
                AcademicYear.name.desc()
            )
            .all()
        )

    else:

        academic_years = []

    # --------------------------------------------------------
    # TEACHERS
    # --------------------------------------------------------

    if current_role == "superadmin":

        teachers = (
            Teacher.query
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    elif current_role == "branch_admin":

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == user_institution_id,
                Teacher.branch_id
                == user_branch_id
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    else:

        teachers = (
            Teacher.query
            .filter(
                Teacher.institution_id
                == user_institution_id
            )
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # --------------------------------------------------------
    # PROGRAMS
    # --------------------------------------------------------

    if current_role == "superadmin":

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            programs = (
                Program.query
                .filter(
                    Program.institution_id
                    == user_institution_id,

                    db.or_(
                        Program.branch_id
                        == user_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
                .order_by(
                    Program.name.asc()
                )
                .all()
            )

        else:

            programs = (
                Program.query
                .filter(
                    Program.institution_id
                    == user_institution_id
                )
                .order_by(
                    Program.name.asc()
                )
                .all()
            )

    else:

        programs = []

    # --------------------------------------------------------
    # CLASSES
    # --------------------------------------------------------

    if current_role == "superadmin":

        classes = (
            Class.query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            classes = (
                Class.query
                .filter(
                    Class.institution_id
                    == user_institution_id,

                    Class.branch_id
                    == user_branch_id
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

        else:

            classes = (
                Class.query
                .filter(
                    Class.institution_id
                    == user_institution_id
                )
                .order_by(
                    Class.name.asc()
                )
                .all()
            )

    else:

        classes = []

    # --------------------------------------------------------
    # SUBJECTS
    # --------------------------------------------------------

    if current_role == "superadmin":

        subjects = (
            Subject.query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            subjects = (
                Subject.query
                .filter(
                    Subject.institution_id
                    == user_institution_id,

                    db.or_(
                        Subject.branch_id
                        == user_branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

        else:

            subjects = (
                Subject.query
                .filter(
                    Subject.institution_id
                    == user_institution_id
                )
                .order_by(
                    Subject.name.asc()
                )
                .all()
            )

    else:

        subjects = []

    # --------------------------------------------------------
    # SECTIONS
    # --------------------------------------------------------

    if current_role == "superadmin":

        sections = (
            Section.query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    elif user_institution_id:

        if current_role == "branch_admin":

            sections = (
                Section.query
                .filter(
                    Section.institution_id
                    == user_institution_id,

                    Section.branch_id
                    == user_branch_id
                )
                .order_by(
                    Section.name.asc()
                )
                .all()
            )

        else:

            sections = (
                Section.query
                .filter(
                    Section.institution_id
                    == user_institution_id
                )
                .order_by(
                    Section.name.asc()
                )
                .all()
            )

    else:

        sections = []

    # ========================================================
    # CURRENT IDS
    # ========================================================

    current_institution_id = (
        form_values.get(
            "institution_id"
        )
        if request.method == "POST" and form_values
        else assignment.institution_id
    )

    current_branch_id = (
        form_values.get(
            "branch_id"
        )
        if request.method == "POST" and form_values
        else assignment.branch_id
    )

    current_academic_year_id = (
        form_values.get(
            "academic_year_id"
        )
        if request.method == "POST" and form_values
        else assignment.academic_year_id
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/teacher_subjects/edit_teacher_subject.html",

        assignment=assignment,

        institutions=institutions,
        branches=branches,
        academic_years=academic_years,
        teachers=teachers,
        programs=programs,
        classes=classes,
        subjects=subjects,
        sections=sections,

        form_values=form_values,

        current_role=current_role,

        current_institution_id=current_institution_id,
        current_branch_id=current_branch_id,
        current_academic_year_id=current_academic_year_id,

        is_superadmin=(
            current_role == "superadmin"
        ),

        is_school_admin=(
            current_role == "school_admin"
        ),

        is_branch_admin=(
            current_role == "branch_admin"
        ),
    )


# ============================================================
# DELETE TEACHER SUBJECT
# ============================================================

@bp.route(
    "/teacher-subjects/<int:teacher_subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_teacher_subject(teacher_subject_id):

    # ========================================================
    # AUTHORIZATION
    # ========================================================

    if not _teacher_subject_can_manage():
        flash(
            "You are not authorized to delete assignments.",
            "danger"
        )
        return redirect(
            url_for("main.all_teacher_subjects")
        )

    # ========================================================
    # LOAD
    # ========================================================

    teacher_subject = (
        TeacherSubject.query
        .filter(
            TeacherSubject.id == teacher_subject_id
        )
        .first_or_404()
    )

    # ========================================================
    # SECURITY
    # ========================================================

    user_institution_id = (
        _teacher_subject_user_institution_id()
    )

    user_branch_id = (
        _teacher_subject_user_branch_id()
    )

    role = getattr(
        current_user,
        "role",
        None
    )

    if (
        role != "superadmin"
        and user_institution_id
        and teacher_subject.institution_id
        != user_institution_id
    ):
        abort(403)

    if (
        role == "branch_admin"
        and user_branch_id
        and teacher_subject.branch_id
        != user_branch_id
    ):
        abort(403)

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            teacher_subject
        )

        db.session.commit()

        flash(
            "Teacher subject assignment deleted successfully.",
            "success"
        )

    except IntegrityError:

        db.session.rollback()

        flash(
            "Unable to delete this assignment because it is being used by another record.",
            "danger"
        )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Error deleting TeacherSubject: %s",
            e
        )

        flash(
            "Unable to delete the teacher subject assignment.",
            "danger"
        )

    return redirect(
        url_for(
            "main.all_teacher_subjects"
        )
    )


