@bp.route("/add-student", methods=["GET", "POST"])
@login_required
def add_student():

    # ========================================================
    # IMPORTS
    # ========================================================

    import os
    import secrets
    import string

    from datetime import date, datetime
    from decimal import Decimal, InvalidOperation

    from flask import (
        current_app,
        flash,
        redirect,
        render_template,
        request,
        session,
        url_for,
    )

    from sqlalchemy import or_

    from werkzeug.utils import secure_filename

    # ========================================================
    # ACCESS CONTROL
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if getattr(
        current_user,
        "role",
        None
    ) not in allowed_roles:

        flash(
            "You do not have permission to add students.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # HELPERS
    # ========================================================

    def _clean(value):

        if value is None:
            return ""

        return str(value).strip()

    # --------------------------------------------------------

    def _decimal(
        value,
        default=Decimal("0.00")
    ):

        value = _clean(value)

        if not value:
            return default

        try:

            value = value.replace(",", "")

            return Decimal(
                value
            ).quantize(
                Decimal("0.01")
            )

        except (
            InvalidOperation,
            ValueError,
        ):

            return default

    # --------------------------------------------------------

    def _parse_date(
        value,
        default=None
    ):

        value = _clean(value)

        if not value:
            return default

        formats = (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
        )

        for fmt in formats:

            try:

                return datetime.strptime(
                    value,
                    fmt
                ).date()

            except ValueError:

                continue

        return default

    # --------------------------------------------------------

    def _random_password(
        length=10
    ):

        chars = (
            string.ascii_letters
            + string.digits
        )

        return "".join(
            secrets.choice(chars)
            for _ in range(length)
        )

    # --------------------------------------------------------

    def _first_name(
        full_name
    ):

        name = _clean(
            full_name
        )

        if not name:
            return "student"

        return (
            name
            .split()[0]
            .lower()
        )

    # --------------------------------------------------------

    def _institution_prefix(
        institution
    ):

        if not institution:
            return "STU"

        short_name = _clean(
            getattr(
                institution,
                "short_name",
                ""
            )
        )

        name = _clean(
            getattr(
                institution,
                "name",
                ""
            )
        )

        source = (
            short_name
            or name
        )

        if not source:
            return "STU"

        letters = [
            char.upper()
            for char in source
            if char.isalpha()
        ]

        if len(letters) >= 3:

            return "".join(
                letters[:3]
            )

        if letters:

            return "".join(
                letters
            ).ljust(
                3,
                "X"
            )

        return "STU"

    # --------------------------------------------------------

    def _next_student_sequence(
        institution_id
    ):

        students = (
            Student.query
            .filter(
                Student.institution_id
                == institution_id
            )
            .all()
        )

        highest = 0

        for student in students:

            value = _clean(
                getattr(
                    student,
                    "admission_no",
                    ""
                )
            )

            if not value:
                continue

            digits = "".join(
                char
                for char in value
                if char.isdigit()
            )

            if not digits:
                continue

            try:

                number = int(
                    digits
                )

                if number > highest:
                    highest = number

            except ValueError:

                continue

        return highest + 1

    # --------------------------------------------------------

    def _generate_student_numbers(
        institution
    ):

        prefix = _institution_prefix(
            institution
        )

        sequence = (
            _next_student_sequence(
                institution.id
            )
        )

        year = date.today().year

        admission_no = (
            f"{prefix}-"
            f"{year}-"
            f"{sequence:05d}"
        )

        roll_no = str(
            sequence
        )

        return (
            admission_no,
            roll_no
        )

    # --------------------------------------------------------

    def _generate_username(
        full_name
    ):

        base = _first_name(
            full_name
        )

        base = "".join(
            char
            for char in base
            if char.isalnum()
        ).lower()

        if not base:
            base = "student"

        year = date.today().year

        username = (
            f"{base}{year}"
        )

        original = username

        counter = 1

        while (
            Student.query
            .filter(
                Student.username
                == username
            )
            .first()
            is not None
        ):

            counter += 1

            username = (
                f"{original}{counter}"
            )

        return username

    # --------------------------------------------------------

    def _generate_email(
        full_name,
        admission_no
    ):

        base = _first_name(
            full_name
        )

        base = "".join(
            char
            for char in base
            if char.isalnum()
        ).lower()

        if not base:
            base = "student"

        domain = (
            current_app.config.get(
                "STUDENT_EMAIL_DOMAIN"
            )
            or "student.local"
        )

        email_base = (
            f"{base}."
            f"{str(admission_no).lower()}"
        )

        email = (
            f"{email_base}@{domain}"
        )

        counter = 1

        while (
            Student.query
            .filter(
                Student.email
                == email
            )
            .first()
            is not None
        ):

            email = (
                f"{email_base}"
                f"{counter}@{domain}"
            )

            counter += 1

        return email

    # --------------------------------------------------------

    def _generate_enrollment_no(
        admission_no,
        index
    ):

        return (
            f"{admission_no}-"
            f"E{index + 1:02d}"
        )

    # --------------------------------------------------------

    def _form_list_value(
        values,
        index
    ):

        if index >= len(values):
            return ""

        return _clean(
            values[index]
        )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        try:

            # ====================================================
            # STUDENT BASIC INFORMATION
            # ====================================================

            full_name = _clean(
                request.form.get(
                    "full_name"
                )
            )

            gender = _clean(
                request.form.get(
                    "gender"
                )
            )

            date_of_birth = _parse_date(
                request.form.get(
                    "date_of_birth"
                )
            )

            place_of_birth = _clean(
                request.form.get(
                    "place_of_birth"
                )
            )

            nationality = _clean(
                request.form.get(
                    "nationality"
                )
            )

            phone = _clean(
                request.form.get(
                    "phone"
                )
            )

            email = _clean(
                request.form.get(
                    "email"
                )
            )

            address = _clean(
                request.form.get(
                    "address"
                )
            )

            city = _clean(
                request.form.get(
                    "city"
                )
            )

            status = (
                _clean(
                    request.form.get(
                        "status"
                    )
                )
                or "active"
            )

            notes = _clean(
                request.form.get(
                    "notes"
                )
            )

            # ====================================================
            # THESE FIELDS MAY EXIST IN TEMPLATE
            # BUT ARE NOT IN Student MODEL.
            #
            # We intentionally READ them only so the form
            # remains compatible.
            # ====================================================

            country = _clean(
                request.form.get(
                    "country"
                )
            )

            phone_country = _clean(
                request.form.get(
                    "phone_country"
                )
            )

            state = _clean(
                request.form.get(
                    "state"
                )
            )

            # ====================================================
            # PARENT / GUARDIAN
            # ====================================================

            parent_name = _clean(
                request.form.get(
                    "parent_name"
                )
            )

            relationship_to_student = _clean(
                request.form.get(
                    "relationship_to_student"
                )
            )

            parent_phone = _clean(
                request.form.get(
                    "parent_phone"
                )
            )

            parent_email = _clean(
                request.form.get(
                    "parent_email"
                )
            )

            parent_address = _clean(
                request.form.get(
                    "parent_address"
                )
            )

            # ====================================================
            # VALIDATE NAME
            # ====================================================

            if not full_name:

                raise ValueError(
                    "Student full name is required."
                )

            # ====================================================
            # INSTITUTION
            # ====================================================

            submitted_institution_id = (
                request.form.get(
                    "institution_id",
                    type=int
                )
            )

            if current_user.role == "superadmin":

                institution_id = (
                    submitted_institution_id
                )

            else:

                institution_id = (
                    current_institution_id
                )

                if (
                    submitted_institution_id
                    and
                    submitted_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "You cannot add a student "
                        "to another institution."
                    )

            if not institution_id:

                raise ValueError(
                    "Institution is required."
                )

            # ====================================================
            # GET INSTITUTION
            # ====================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == institution_id
                )
                .first()
            )

            if not institution:

                raise ValueError(
                    "Selected institution was not found."
                )

            # ====================================================
            # BRANCH
            # ====================================================

            submitted_branch_id = (
                request.form.get(
                    "branch_id",
                    type=int
                )
            )

            if (
                current_user.role
                == "branch_admin"
            ):

                branch_id = (
                    current_branch_id
                )

            else:

                branch_id = (
                    submitted_branch_id
                )

            if not branch_id:

                raise ValueError(
                    "Branch is required."
                )

            # ====================================================
            # GET BRANCH
            # ====================================================

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == branch_id,

                    Branch.institution_id
                    == institution_id
                )
                .first()
            )

            if not branch:

                raise ValueError(
                    "Selected branch does not "
                    "belong to the selected institution."
                )

            # ====================================================
            # BRANCH ADMIN SECURITY
            # ====================================================

            if (
                current_user.role
                == "branch_admin"
            ):

                if (
                    current_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "Invalid institution access."
                    )

                if (
                    current_branch_id
                    != branch_id
                ):

                    raise ValueError(
                        "Invalid branch access."
                    )

            # ====================================================
            # SCHOOL ADMIN SECURITY
            # ====================================================

            if (
                current_user.role
                == "school_admin"
            ):

                if (
                    current_institution_id
                    != institution_id
                ):

                    raise ValueError(
                        "You can only add students "
                        "to your institution."
                    )

            # ====================================================
            # STATUS
            # ====================================================

            allowed_student_statuses = {
                "active",
                "inactive",
                "graduated",
                "transferred",
                "suspended",
                "withdrawn",
            }

            if (
                status
                not in allowed_student_statuses
            ):

                status = "active"

            # ====================================================
            # GENERATE STUDENT NUMBERS
            # ====================================================

            (
                admission_no,
                roll_no
            ) = _generate_student_numbers(
                institution
            )

            # ====================================================
            # USERNAME
            # ====================================================

            username = _generate_username(
                full_name
            )

            # ====================================================
            # PASSWORD
            # ====================================================

            generated_password = (
                _random_password(10)
            )

            # ====================================================
            # EMAIL
            # ====================================================

            if email:

                existing_email = (
                    Student.query
                    .filter(
                        Student.email
                        == email
                    )
                    .first()
                )

                if existing_email:

                    raise ValueError(
                        "The email address is already "
                        "used by another student."
                    )

            else:

                email = _generate_email(
                    full_name,
                    admission_no
                )

            # ====================================================
            # CREATE STUDENT
            #
            # IMPORTANT:
            # No country
            # No phone_country
            # No state
            #
            # because these fields DO NOT EXIST
            # in the supplied Student model.
            # ====================================================

            student = Student(

                institution_id=(
                    institution_id
                ),

                branch_id=(
                    branch_id
                ),

                username=(
                    username
                ),

                email=(
                    email
                ),

                password="",

                role="student",

                is_active=(
                    status == "active"
                ),

                is_verified=False,

                admission_no=(
                    admission_no
                ),

                roll_no=(
                    roll_no
                ),

                full_name=(
                    full_name
                ),

                gender=(
                    gender or None
                ),

                date_of_birth=(
                    date_of_birth
                ),

                place_of_birth=(
                    place_of_birth or None
                ),

                nationality=(
                    nationality or None
                ),

                phone=(
                    phone or None
                ),

                address=(
                    address or None
                ),

                city=(
                    city or None
                ),

                parent_name=(
                    parent_name or None
                ),

                parent_phone=(
                    parent_phone or None
                ),

                parent_email=(
                    parent_email or None
                ),

                parent_address=(
                    parent_address or None
                ),

                relationship_to_student=(
                    relationship_to_student
                    or None
                ),

                status=(
                    status
                ),

                notes=(
                    notes or None
                ),
            )

            # ====================================================
            # PASSWORD HASH
            # ====================================================

            student.set_password(
                generated_password
            )

            # ====================================================
            # PHOTO
            # ====================================================

            photo = request.files.get(
                "photo"
            )

            if (
                photo
                and
                photo.filename
            ):

                original_filename = (
                    secure_filename(
                        photo.filename
                    )
                )

                extension = ""

                if "." in original_filename:

                    extension = (
                        original_filename
                        .rsplit(
                            ".",
                            1
                        )[1]
                        .lower()
                    )

                allowed_extensions = {
                    "jpg",
                    "jpeg",
                    "png",
                    "webp",
                }

                if (
                    extension
                    not in allowed_extensions
                ):

                    raise ValueError(
                        "Invalid photo format. "
                        "Use JPG, JPEG, PNG or WEBP."
                    )

                upload_directory = os.path.join(
                    current_app.root_path,
                    "static",
                    "uploads",
                    "students"
                )

                os.makedirs(
                    upload_directory,
                    exist_ok=True
                )

                filename = (
                    "student_"
                    f"{secrets.token_hex(10)}."
                    f"{extension}"
                )

                absolute_path = os.path.join(
                    upload_directory,
                    filename
                )

                photo.save(
                    absolute_path
                )

                student.photo = (
                    f"uploads/students/{filename}"
                )

            # ====================================================
            # ADD STUDENT
            # ====================================================

            db.session.add(
                student
            )

            db.session.flush()

            # ====================================================
            # ENROLLMENT ARRAYS
            # ====================================================

            academic_year_ids = (
                request.form.getlist(
                    "academic_year_id[]"
                )
            )

            program_ids = (
                request.form.getlist(
                    "program_id[]"
                )
            )

            class_ids = (
                request.form.getlist(
                    "class_id[]"
                )
            )

            section_ids = (
                request.form.getlist(
                    "section_id[]"
                )
            )

            enrollment_dates = (
                request.form.getlist(
                    "enrollment_date[]"
                )
            )

            enrollment_statuses = (
                request.form.getlist(
                    "enrollment_status[]"
                )
            )

            enrollment_notes = (
                request.form.getlist(
                    "enrollment_notes[]"
                )
            )

            # ====================================================
            # ENROLLMENT RECORDS
            # ====================================================

            enrollment_records = []

            max_enrollments = max(
                len(academic_year_ids),
                len(program_ids),
                len(class_ids),
                len(section_ids),
                len(enrollment_dates),
                len(enrollment_statuses),
                len(enrollment_notes),
                0
            )

            # ====================================================
            # ENROLLMENT STATUS
            # ====================================================

            allowed_enrollment_statuses = {
                "active",
                "completed",
                "transferred",
                "withdrawn",
                "suspended",
                "promoted",
            }

            # ====================================================
            # PROCESS ENROLLMENTS
            # ====================================================

            for index in range(
                max_enrollments
            ):

                academic_year_raw = (
                    _form_list_value(
                        academic_year_ids,
                        index
                    )
                )

                program_raw = (
                    _form_list_value(
                        program_ids,
                        index
                    )
                )

                class_raw = (
                    _form_list_value(
                        class_ids,
                        index
                    )
                )

                section_raw = (
                    _form_list_value(
                        section_ids,
                        index
                    )
                )

                enrollment_date_raw = (
                    _form_list_value(
                        enrollment_dates,
                        index
                    )
                )

                enrollment_status = (
                    _form_list_value(
                        enrollment_statuses,
                        index
                    )
                    or "active"
                )

                enrollment_note = (
                    _form_list_value(
                        enrollment_notes,
                        index
                    )
                )

                # ----------------------------------------------
                # EMPTY ROW
                # ----------------------------------------------

                if not (
                    academic_year_raw
                    or program_raw
                    or class_raw
                    or section_raw
                ):

                    continue

                # ----------------------------------------------
                # IDs
                # ----------------------------------------------

                if not academic_year_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Academic year is required."
                    )

                if not program_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Program is required."
                    )

                if not class_raw.isdigit():

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Class is required."
                    )

                academic_year_id = int(
                    academic_year_raw
                )

                program_id = int(
                    program_raw
                )

                class_id = int(
                    class_raw
                )

                section_id = None

                if section_raw.isdigit():

                    section_id = int(
                        section_raw
                    )

                # ----------------------------------------------
                # ACADEMIC YEAR
                # ----------------------------------------------

                academic_year = (
                    AcademicYear.query
                    .filter(
                        AcademicYear.id
                        == academic_year_id,

                        AcademicYear.institution_id
                        == institution_id
                    )
                    .first()
                )

                if not academic_year:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid academic year."
                    )

                # ----------------------------------------------
                # PROGRAM
                # ----------------------------------------------

                program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id,

                        Program.institution_id
                        == institution_id,

                        or_(
                            Program.branch_id
                            == branch_id,

                            Program.branch_id.is_(None)
                        )
                    )
                    .first()
                )

                if not program:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid program for this branch."
                    )

                # ----------------------------------------------
                # CLASS
                # ----------------------------------------------

                selected_class = (
                    Class.query
                    .filter(
                        Class.id
                        == class_id,

                        Class.institution_id
                        == institution_id,

                        Class.branch_id
                        == branch_id
                    )
                    .first()
                )

                if not selected_class:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Invalid class for this branch."
                    )

                # ----------------------------------------------
                # CLASS → PROGRAM
                # ----------------------------------------------

                class_program_id = getattr(
                    selected_class,
                    "program_id",
                    None
                )

                if (
                    class_program_id
                    and
                    class_program_id
                    != program_id
                ):

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Selected class does not "
                        "belong to selected program."
                    )

                # ----------------------------------------------
                # SECTION
                # ----------------------------------------------

                if section_id:

                    selected_section = (
                        Section.query
                        .filter(
                            Section.id
                            == section_id,

                            Section.institution_id
                            == institution_id,

                            Section.branch_id
                            == branch_id,

                            Section.class_id
                            == class_id
                        )
                        .first()
                    )

                    if not selected_section:

                        raise ValueError(
                            f"Enrollment #{index + 1}: "
                            "Invalid section for selected class."
                        )

                # ----------------------------------------------
                # ENROLLMENT STATUS
                # ----------------------------------------------

                if (
                    enrollment_status
                    not in allowed_enrollment_statuses
                ):

                    enrollment_status = (
                        "active"
                    )

                # ----------------------------------------------
                # DUPLICATE
                # ----------------------------------------------

                duplicate = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,

                        StudentEnrollment.academic_year_id
                        == academic_year_id
                    )
                    .first()
                )

                if duplicate:

                    raise ValueError(
                        f"Enrollment #{index + 1}: "
                        "Student already has an "
                        "enrollment for this academic year."
                    )

                # ----------------------------------------------
                # DATE
                # ----------------------------------------------

                enrollment_date = (
                    _parse_date(
                        enrollment_date_raw,
                        default=date.today()
                    )
                )

                # ----------------------------------------------
                # ENROLLMENT NUMBER
                # ----------------------------------------------

                enrollment_no = (
                    _generate_enrollment_no(
                        admission_no,
                        index
                    )
                )

                # ----------------------------------------------
                # SAFETY CHECK
                # ----------------------------------------------

                existing_enrollment_no = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.institution_id
                        == institution_id,

                        StudentEnrollment.enrollment_no
                        == enrollment_no
                    )
                    .first()
                )

                if existing_enrollment_no:

                    enrollment_no = (
                        f"{admission_no}-"
                        f"E{index + 1:02d}-"
                        f"{secrets.token_hex(2).upper()}"
                    )

                # ----------------------------------------------
                # CREATE ENROLLMENT
                # ----------------------------------------------

                enrollment = StudentEnrollment(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    academic_year_id=(
                        academic_year_id
                    ),

                    program_id=(
                        program_id
                    ),

                    class_id=(
                        class_id
                    ),

                    section_id=(
                        section_id
                    ),

                    enrollment_no=(
                        enrollment_no
                    ),

                    enrollment_date=(
                        enrollment_date
                    ),

                    status=(
                        enrollment_status
                    ),

                    notes=(
                        enrollment_note
                        or None
                    ),
                )

                db.session.add(
                    enrollment
                )

                enrollment_records.append({
                    "enrollment": enrollment,
                    "academic_year": academic_year,
                    "program": program,
                    "index": index,
                })

            # ====================================================
            # REQUIRE ENROLLMENT
            # ====================================================

            if not enrollment_records:

                raise ValueError(
                    "At least one academic enrollment "
                    "is required."
                )

            db.session.flush()

            # ====================================================
            # AUTOMATIC REGISTRATION FEE
            # ====================================================

            first_record = (
                enrollment_records[0]
            )

            first_enrollment = (
                first_record["enrollment"]
            )

            first_academic_year = (
                first_record["academic_year"]
            )

            first_program = (
                first_record["program"]
            )

            registration_amount = (
                Decimal("5.00")
            )

            registration_charge = (
                StudentCharge(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    enrollment_id=(
                        first_enrollment.id
                    ),

                    academic_year_id=(
                        first_academic_year.id
                    ),

                    charge_type=(
                        "registration"
                    ),

                    charge_name=(
                        "Registration Fee"
                    ),

                    description=(
                        "Automatic registration fee"
                    ),

                    amount=(
                        registration_amount
                    ),

                    discount=(
                        Decimal("0.00")
                    ),

                    net_amount=(
                        registration_amount
                    ),

                    paid_amount=(
                        Decimal("0.00")
                    ),

                    balance=(
                        registration_amount
                    ),

                    due_date=(
                        date.today()
                    ),

                    status=(
                        "unpaid"
                    ),

                    created_by=(
                        getattr(
                            current_user,
                            "id",
                            None
                        )
                    ),
                )
            )

            db.session.add(
                registration_charge
            )

            # ====================================================
            # AUTOMATIC PROGRAM FEE
            # ====================================================

            program_price = _decimal(
                getattr(
                    first_program,
                    "price",
                    0
                )
            )

            if (
                program_price
                > Decimal("0.00")
            ):

                program_name = (
                    _clean(
                        getattr(
                            first_program,
                            "name",
                            ""
                        )
                    )
                    or "Program"
                )

                program_charge = (
                    StudentCharge(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            branch_id
                        ),

                        student_id=(
                            student.id
                        ),

                        enrollment_id=(
                            first_enrollment.id
                        ),

                        academic_year_id=(
                            first_academic_year.id
                        ),

                        charge_type=(
                            "program_fee"
                        ),

                        charge_name=(
                            f"{program_name} Fee"
                        ),

                        description=(
                            "Automatic program fee"
                        ),

                        amount=(
                            program_price
                        ),

                        discount=(
                            Decimal("0.00")
                        ),

                        net_amount=(
                            program_price
                        ),

                        paid_amount=(
                            Decimal("0.00")
                        ),

                        balance=(
                            program_price
                        ),

                        due_date=(
                            date.today()
                        ),

                        status=(
                            "unpaid"
                        ),

                        created_by=(
                            getattr(
                                current_user,
                                "id",
                                None
                            )
                        ),
                    )
                )

                db.session.add(
                    program_charge
                )

            # ====================================================
            # MANUAL CHARGES
            # ====================================================

            charge_types = (
                request.form.getlist(
                    "charge_type[]"
                )
            )

            charge_names = (
                request.form.getlist(
                    "charge_name[]"
                )
            )

            charge_amounts = (
                request.form.getlist(
                    "charge_amount[]"
                )
            )

            charge_discounts = (
                request.form.getlist(
                    "charge_discount[]"
                )
            )

            charge_paid_amounts = (
                request.form.getlist(
                    "charge_paid_amount[]"
                )
            )

            charge_due_dates = (
                request.form.getlist(
                    "charge_due_date[]"
                )
            )

            charge_enrollment_values = (
                request.form.getlist(
                    "charge_enrollment[]"
                )
            )

            # Compatibility with old template

            if not charge_enrollment_values:

                charge_enrollment_values = (
                    request.form.getlist(
                        "charge_enrollment_index[]"
                    )
                )

            charge_descriptions = (
                request.form.getlist(
                    "charge_description[]"
                )
            )

            allowed_charge_types = {
                "registration",
                "program_fee",
                "tuition",
                "exam",
                "admission",
                "id_card",
                "uniform",
                "books",
                "transport",
                "laboratory",
                "library",
                "certificate",
                "other",
            }

            max_charges = max(
                len(charge_types),
                len(charge_names),
                len(charge_amounts),
                len(charge_discounts),
                len(charge_paid_amounts),
                len(charge_due_dates),
                len(charge_enrollment_values),
                len(charge_descriptions),
                0
            )

            for index in range(
                max_charges
            ):

                charge_type = (
                    _form_list_value(
                        charge_types,
                        index
                    )
                    .lower()
                )

                charge_name = (
                    _form_list_value(
                        charge_names,
                        index
                    )
                )

                amount = _decimal(
                    _form_list_value(
                        charge_amounts,
                        index
                    )
                )

                discount = _decimal(
                    _form_list_value(
                        charge_discounts,
                        index
                    )
                )

                paid_amount = _decimal(
                    _form_list_value(
                        charge_paid_amounts,
                        index
                    )
                )

                due_date = _parse_date(
                    _form_list_value(
                        charge_due_dates,
                        index
                    ),
                    default=date.today()
                )

                description = (
                    _form_list_value(
                        charge_descriptions,
                        index
                    )
                )

                enrollment_index_raw = (
                    _form_list_value(
                        charge_enrollment_values,
                        index
                    )
                )

                enrollment_index = 0

                if enrollment_index_raw.isdigit():

                    enrollment_index = int(
                        enrollment_index_raw
                    )

                # ----------------------------------------------
                # EMPTY ROW
                # ----------------------------------------------

                if not (
                    charge_type
                    or charge_name
                    or amount
                ):

                    continue

                # ----------------------------------------------
                # AUTO CHARGES
                # ----------------------------------------------

                if charge_type in {
                    "registration",
                    "program_fee",
                }:

                    continue

                # ----------------------------------------------
                # VALID TYPE
                # ----------------------------------------------

                if (
                    charge_type
                    not in allowed_charge_types
                ):

                    charge_type = "other"

                # ----------------------------------------------
                # NORMALIZE MONEY
                # ----------------------------------------------

                if amount < 0:

                    raise ValueError(
                        f"Charge #{index + 1}: "
                        "Amount cannot be negative."
                    )

                if discount < 0:

                    discount = Decimal(
                        "0.00"
                    )

                if paid_amount < 0:

                    paid_amount = Decimal(
                        "0.00"
                    )

                if discount > amount:

                    discount = amount

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:

                    paid_amount = net_amount

                balance = (
                    net_amount
                    - paid_amount
                )

                # ----------------------------------------------
                # STATUS
                # ----------------------------------------------

                if balance <= 0:

                    charge_status = "paid"

                    balance = Decimal(
                        "0.00"
                    )

                elif paid_amount > 0:

                    charge_status = "partial"

                else:

                    charge_status = "unpaid"

                # ----------------------------------------------
                # ENROLLMENT INDEX
                # ----------------------------------------------

                if (
                    enrollment_index < 0
                    or
                    enrollment_index
                    >= len(
                        enrollment_records
                    )
                ):

                    enrollment_index = 0

                charge_enrollment_record = (
                    enrollment_records[
                        enrollment_index
                    ]
                )

                charge_enrollment = (
                    charge_enrollment_record[
                        "enrollment"
                    ]
                )

                charge_academic_year = (
                    charge_enrollment_record[
                        "academic_year"
                    ]
                )

                # ----------------------------------------------
                # NAME
                # ----------------------------------------------

                if not charge_name:

                    charge_name = (
                        charge_type
                        .replace(
                            "_",
                            " "
                        )
                        .title()
                    )

                # ----------------------------------------------
                # CREATE
                # ----------------------------------------------

                manual_charge = (
                    StudentCharge(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            branch_id
                        ),

                        student_id=(
                            student.id
                        ),

                        enrollment_id=(
                            charge_enrollment.id
                        ),

                        academic_year_id=(
                            charge_academic_year.id
                        ),

                        charge_type=(
                            charge_type
                        ),

                        charge_name=(
                            charge_name
                        ),

                        description=(
                            description
                            or None
                        ),

                        amount=(
                            amount
                        ),

                        discount=(
                            discount
                        ),

                        net_amount=(
                            net_amount
                        ),

                        paid_amount=(
                            paid_amount
                        ),

                        balance=(
                            balance
                        ),

                        due_date=(
                            due_date
                        ),

                        status=(
                            charge_status
                        ),

                        created_by=(
                            getattr(
                                current_user,
                                "id",
                                None
                            )
                        ),
                    )
                )

                db.session.add(
                    manual_charge
                )

            # ====================================================
            # FINAL FLUSH
            # ====================================================

            db.session.flush()

            # ====================================================
            # COMMIT
            # ====================================================

            db.session.commit()

            # ====================================================
            # SAVE GENERATED LOGIN DETAILS
            # ====================================================

            session[
                "new_student_credentials"
            ] = {

                "student_id": student.id,

                "full_name": student.full_name,

                "admission_no": (
                    student.admission_no
                ),

                "roll_no": (
                    student.roll_no
                ),

                "username": (
                    student.username
                ),

                "email": (
                    student.email
                ),

                "password": (
                    generated_password
                ),
            }

            # ====================================================
            # SUCCESS
            # ====================================================

            flash(
                (
                    f"Student "
                    f"{student.full_name} "
                    f"was added successfully."
                ),
                "success"
            )

            # ====================================================
            # REDIRECT
            # ====================================================

            if (
                "main.view_student"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.view_student",
                        student_id=student.id
                    )
                )

            if (
                "main.all_students"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.all_students"
                    )
                )

            return redirect(
                url_for(
                    "main.dashboard"
                )
            )

        # ========================================================
        # VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            current_app.logger.warning(
                "Add student validation error: %s",
                exc
            )

            flash(
                str(exc),
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_student"
                )
            )

        # ========================================================
        # DATABASE / UNEXPECTED ERROR
        # ========================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Unexpected error while adding student"
            )

            flash(
                (
                    "Unable to add student. "
                    f"Error: {exc}"
                ),
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_student"
                )
            )

    # ========================================================
    # GET
    # ========================================================

    # ========================================================
    # INSTITUTIONS
    # ========================================================

    if current_user.role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = []

        if current_institution_id:

            current_institution_for_list = (
                Institution.query
                .filter(
                    Institution.id
                    == current_institution_id
                )
                .first()
            )

            if current_institution_for_list:

                institutions = [
                    current_institution_for_list
                ]

    # ========================================================
    # BRANCHES
    # ========================================================

    if (
        current_user.role
        == "branch_admin"
    ):

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id,

                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif (
        current_user.role
        == "school_admin"
    ):

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ========================================================
    # CURRENT INSTITUTION
    # ========================================================

    current_institution = None

    if current_institution_id:

        current_institution = (
            Institution.query
            .filter(
                Institution.id
                == current_institution_id
            )
            .first()
        )

    # ========================================================
    # CURRENT BRANCH
    # ========================================================

    current_branch = None

    if current_branch_id:

        current_branch = (
            Branch.query
            .filter(
                Branch.id
                == current_branch_id
            )
            .first()
        )

    # ========================================================
    # DEFAULT BRANCH
    # ========================================================

    default_branch_id = (
        current_branch_id
        if current_user.role
        == "branch_admin"
        else None
    )

    # ========================================================
    # PROGRAMS
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id,

                or_(
                    Program.branch_id
                    == default_branch_id,

                    Program.branch_id.is_(None)
                )
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        programs = (
            Program.query
            .filter(
                Program.institution_id
                == current_institution_id
            )
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    else:

        programs = (
            Program.query
            .order_by(
                Program.name.asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == current_institution_id,

                Class.branch_id
                == default_branch_id
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        classes = (
            Class.query
            .filter(
                Class.institution_id
                == current_institution_id
            )
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    else:

        classes = (
            Class.query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    if (
        current_institution_id
        and default_branch_id
    ):

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == current_institution_id,

                Section.branch_id
                == default_branch_id
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    elif current_institution_id:

        sections = (
            Section.query
            .filter(
                Section.institution_id
                == current_institution_id
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    else:

        sections = (
            Section.query
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # ACADEMIC YEARS
    # ========================================================

    if current_institution_id:

        academic_years = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id
                == current_institution_id
            )
            .order_by(
                AcademicYear.is_current.desc(),
                AcademicYear.id.desc()
            )
            .all()
        )

    else:

        academic_years = (
            AcademicYear.query
            .order_by(
                AcademicYear.is_current.desc(),
                AcademicYear.id.desc()
            )
            .all()
        )

    # ========================================================
    # COUNTRIES
    # ========================================================

    try:

        all_countries = (
            get_all_countries()
        )

    except Exception:

        all_countries = []

    # ========================================================
    # TODAY
    # ========================================================

    today = (
        date.today()
        .isoformat()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/students/add_student.html",
        user=current_user,

        institutions=institutions,

        branches=branches,

        programs=programs,

        classes=classes,

        sections=sections,

        academic_years=academic_years,

        all_countries=all_countries,

        current_institution=(
            current_institution
        ),

        current_branch=(
            current_branch
        ),

        current_institution_id=(
            current_institution_id
        ),

        current_branch_id=(
            current_branch_id
        ),

        default_branch_id=(
            default_branch_id
        ),

        today=today,

        registration_fee=(
            Decimal("5.00")
        ),
    )





# ============================================================
# VIEW STUDENT
# ============================================================
@bp.route("/students/<int:student_id>", methods=["GET"])
@login_required
def view_student(student_id):
    """
    View a single student profile.

    Access:
        - superadmin   -> all students
        - school_admin -> students belonging to their institution
        - branch_admin -> students belonging to their institution + branch

    Template:
        backend/pages/students/view_student.html
    """

    # ============================================================
    # IMPORTS
    # ============================================================

    from flask import abort, render_template, flash, redirect, url_for
    from sqlalchemy.orm import joinedload

    # ============================================================
    # ALLOWED ROLES
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_user.role not in allowed_roles:
        abort(403)

    # ============================================================
    # BASIC USER SCOPE VALIDATION
    # ============================================================

    if current_user.role == "school_admin":
        if not current_user.institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )
            return redirect(url_for("main.dashboard"))

    if current_user.role == "branch_admin":
        if (
            not current_user.institution_id
            or not current_user.branch_id
        ):
            flash(
                "Your account is not assigned to an institution and branch.",
                "danger"
            )
            return redirect(url_for("main.dashboard"))

    # ============================================================
    # GET STUDENT
    #
    # Eager-load the relationships needed by view_student.html
    # ============================================================

    student_query = (
        Student.query
        .options(
            joinedload(Student.institution),
            joinedload(Student.branch),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.academic_year),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.program),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.class_),

            joinedload(Student.enrollments)
                .joinedload(StudentEnrollment.section),

            joinedload(Student.charges)
                .joinedload(StudentCharge.academic_year),

            joinedload(Student.charges)
                .joinedload(StudentCharge.enrollment)
        )
        .filter(
            Student.id == student_id,
            Student.role == "student"
        )
    )

    # ============================================================
    # ROLE-BASED SECURITY SCOPE
    # ============================================================

    if current_user.role == "school_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id
        )

    elif current_user.role == "branch_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id,
            Student.branch_id == current_user.branch_id
        )

    # superadmin:
    # no institution/branch restriction

    # ============================================================
    # FETCH STUDENT
    # ============================================================

    student = student_query.first()

    if not student:
        abort(404)

    # ============================================================
    # SORT ENROLLMENTS
    # ============================================================

    enrollments = list(student.enrollments or [])

    enrollments.sort(
        key=lambda e: (
            e.enrollment_date is None,
            e.enrollment_date or date.min,
            e.id or 0
        ),
        reverse=True
    )

    # ============================================================
    # SORT CHARGES
    # ============================================================

    charges = list(student.charges or [])

    charges.sort(
        key=lambda c: (
            c.due_date is None,
            c.due_date or date.min,
            c.id or 0
        )
    )

    # ============================================================
    # ENROLLMENT STATISTICS
    # ============================================================

    total_enrollments = len(enrollments)

    active_enrollments = [
        enrollment
        for enrollment in enrollments
        if enrollment.status == "active"
    ]

    active_enrollment_count = len(active_enrollments)

    # ============================================================
    # PROGRAM / COURSE COUNT
    #
    # Count unique programs from enrollments
    # ============================================================

    program_ids = {
        enrollment.program_id
        for enrollment in enrollments
        if enrollment.program_id is not None
    }

    total_programs = len(program_ids)

    # ============================================================
    # FINANCIAL CALCULATIONS
    #
    # Use Decimal for money calculations.
    # ============================================================

    total_amount = Decimal("0.00")
    total_discount = Decimal("0.00")
    total_net_amount = Decimal("0.00")
    total_paid_amount = Decimal("0.00")
    total_balance = Decimal("0.00")

    for charge in charges:

        amount = (
            charge.amount
            if charge.amount is not None
            else Decimal("0.00")
        )

        discount = (
            charge.discount
            if charge.discount is not None
            else Decimal("0.00")
        )

        net_amount = (
            charge.net_amount
            if charge.net_amount is not None
            else amount - discount
        )

        paid_amount = (
            charge.paid_amount
            if charge.paid_amount is not None
            else Decimal("0.00")
        )

        balance = (
            charge.balance
            if charge.balance is not None
            else net_amount - paid_amount
        )

        total_amount += Decimal(str(amount))
        total_discount += Decimal(str(discount))
        total_net_amount += Decimal(str(net_amount))
        total_paid_amount += Decimal(str(paid_amount))
        total_balance += Decimal(str(balance))

    # ============================================================
    # CHARGE STATISTICS
    # ============================================================

    total_charges = len(charges)

    paid_charges = sum(
        1
        for charge in charges
        if charge.status == "paid"
    )

    partial_charges = sum(
        1
        for charge in charges
        if charge.status == "partial"
    )

    unpaid_charges = sum(
        1
        for charge in charges
        if charge.status == "unpaid"
    )

    overdue_charges = sum(
        1
        for charge in charges
        if charge.status == "overdue"
    )

    cancelled_charges = sum(
        1
        for charge in charges
        if charge.status == "cancelled"
    )

    # ============================================================
    # CURRENT / ACTIVE ENROLLMENT
    # ============================================================

    current_enrollment = None

    for enrollment in enrollments:
        if enrollment.status == "active":
            current_enrollment = enrollment
            break

    # If there is no active enrollment, use latest enrollment
    if current_enrollment is None and enrollments:
        current_enrollment = enrollments[0]

    # ============================================================
    # CURRENT PROGRAM / CLASS / SECTION
    # ============================================================

    current_program = None
    current_class = None
    current_section = None
    current_academic_year = None

    if current_enrollment:

        current_program = current_enrollment.program

        current_class = current_enrollment.class_

        current_section = current_enrollment.section

        current_academic_year = current_enrollment.academic_year

    # ============================================================
    # INSTITUTIONS
    #
    # Useful if the template displays institution information.
    # ============================================================

    institution = student.institution
    branch = student.branch

    # ============================================================
    # TODAY
    # ============================================================

    today = date.today()

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(
        "backend/pages/students/view_student.html",

        # --------------------------------------------------------
        # Student
        # --------------------------------------------------------

        student=student,
        user=current_user,

        # --------------------------------------------------------
        # Institution / Branch
        # --------------------------------------------------------

        institution=institution,
        branch=branch,

        # --------------------------------------------------------
        # Academic data
        # --------------------------------------------------------

        enrollments=enrollments,
        current_enrollment=current_enrollment,
        current_program=current_program,
        current_class=current_class,
        current_section=current_section,
        current_academic_year=current_academic_year,

        # --------------------------------------------------------
        # Charges
        # --------------------------------------------------------

        charges=charges,

        # --------------------------------------------------------
        # Enrollment statistics
        # --------------------------------------------------------

        total_enrollments=total_enrollments,
        active_enrollment_count=active_enrollment_count,
        total_programs=total_programs,

        # --------------------------------------------------------
        # Financial statistics
        # --------------------------------------------------------

        total_charges=total_charges,
        total_amount=total_amount,
        total_discount=total_discount,
        total_net_amount=total_net_amount,
        total_paid_amount=total_paid_amount,
        total_balance=total_balance,

        # --------------------------------------------------------
        # Charge status statistics
        # --------------------------------------------------------

        paid_charges=paid_charges,
        partial_charges=partial_charges,
        unpaid_charges=unpaid_charges,
        overdue_charges=overdue_charges,
        cancelled_charges=cancelled_charges,

        # --------------------------------------------------------
        # Current user
        # --------------------------------------------------------

        current_role=current_user.role,
        current_institution_id=current_user.institution_id,
        current_branch_id=current_user.branch_id,

        # --------------------------------------------------------
        # Date
        # --------------------------------------------------------

        today=today,
    )



# ============================================================
# EDIT STUDENT
# ============================================================
@bp.route("/edit-student/<int:student_id>", methods=["GET", "POST"])
@login_required
def edit_student(student_id):
    """
    EDIT STUDENT
    ============================================================
    Compatible with:

        Student
        StudentEnrollment
        StudentCharge
        Institution
        Branch
        Program
        Class
        Section
        AcademicYear

    IMPORTANT
    ------------------------------------------------------------
    Student DOES NOT have:

        country
        phone_country
        state

    Those fields may exist in the HTML form, but they are
    intentionally NOT saved to Student.

    Student statuses:
        active
        inactive
        graduated
        transferred
        suspended
        withdrawn

    Enrollment statuses:
        active
        completed
        transferred
        withdrawn
        suspended
        promoted

    Charge types:
        registration
        program_fee
        tuition
        exam
        admission
        id_card
        uniform
        books
        transport
        laboratory
        library
        certificate
        other
    """

    # ============================================================
    # IMPORTS
    # ============================================================

    import os
    from datetime import date, datetime
    from decimal import Decimal, InvalidOperation

    from flask import (
        current_app,
        flash,
        redirect,
        render_template,
        request,
        url_for,
    )

    from flask_login import current_user, login_required
    from sqlalchemy import or_
    from werkzeug.utils import secure_filename

    # ============================================================
    # ROLE SECURITY
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_user_role = getattr(
        current_user,
        "role",
        None,
    )

    if current_user_role not in allowed_roles:
        flash(
            "You do not have permission to edit students.",
            "danger",
        )
        return redirect(
            url_for("main.dashboard")
        )

    # ============================================================
    # HELPERS
    # ============================================================

    def _clean(value):
        if value is None:
            return ""

        return str(value).strip()

    def _int_or_none(value):
        value = _clean(value)

        if not value:
            return None

        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _decimal(
        value,
        default=Decimal("0.00"),
    ):
        value = _clean(value)

        if not value:
            return default

        try:
            return Decimal(
                value
            ).quantize(
                Decimal("0.01")
            )
        except (
            InvalidOperation,
            ValueError,
            TypeError,
        ):
            return default

    def _parse_date(value):
        value = _clean(value)

        if not value:
            return None

        try:
            return datetime.strptime(
                value,
                "%Y-%m-%d",
            ).date()

        except ValueError:
            return None

    def _valid_student_status(value):
        return value in {
            "active",
            "inactive",
            "graduated",
            "transferred",
            "suspended",
            "withdrawn",
        }

    valid_enrollment_statuses = {
        "active",
        "completed",
        "transferred",
        "withdrawn",
        "suspended",
        "promoted",
    }

    valid_charge_types = {
        "registration",
        "program_fee",
        "tuition",
        "exam",
        "admission",
        "id_card",
        "uniform",
        "books",
        "transport",
        "laboratory",
        "library",
        "certificate",
        "other",
    }

    # ============================================================
    # CURRENT USER SCOPE
    # ============================================================

    current_user_institution_id = getattr(
        current_user,
        "institution_id",
        None,
    )

    current_user_branch_id = getattr(
        current_user,
        "branch_id",
        None,
    )

    # ============================================================
    # GET STUDENT
    # ============================================================

    student_query = (
        Student.query
        .filter(
            Student.id == student_id,
            Student.role == "student",
        )
    )

    # ============================================================
    # STUDENT SECURITY SCOPE
    # ============================================================

    if current_user_role == "school_admin":

        if not current_user_institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger",
            )
            return redirect(
                url_for("main.all_students")
            )

        student_query = student_query.filter(
            Student.institution_id
            == current_user_institution_id
        )

    elif current_user_role == "branch_admin":

        if (
            not current_user_institution_id
            or not current_user_branch_id
        ):
            flash(
                "Your account is not assigned to a valid institution and branch.",
                "danger",
            )
            return redirect(
                url_for("main.all_students")
            )

        student_query = student_query.filter(
            Student.institution_id
            == current_user_institution_id,
            Student.branch_id
            == current_user_branch_id,
        )

    student = (
        student_query
        .first_or_404()
    )

    # ============================================================
    # POST
    # ============================================================

    if request.method == "POST":

        uploaded_photo_path = None

        try:

            # ====================================================
            # BASIC STUDENT INFORMATION
            # ====================================================

            full_name = _clean(
                request.form.get(
                    "full_name"
                )
            )

            email = _clean(
                request.form.get(
                    "email"
                )
            ).lower()

            gender = _clean(
                request.form.get(
                    "gender"
                )
            )

            date_of_birth = _parse_date(
                request.form.get(
                    "date_of_birth"
                )
            )

            place_of_birth = _clean(
                request.form.get(
                    "place_of_birth"
                )
            )

            nationality = _clean(
                request.form.get(
                    "nationality"
                )
            )

            phone = _clean(
                request.form.get(
                    "phone"
                )
            )

            city = _clean(
                request.form.get(
                    "city"
                )
            )

            address = _clean(
                request.form.get(
                    "address"
                )
            )

            status = _clean(
                request.form.get(
                    "status"
                )
            ).lower()

            notes = _clean(
                request.form.get(
                    "notes"
                )
            )

            # ====================================================
            # FORM FIELDS THAT ARE NOT STUDENT COLUMNS
            # ====================================================
            #
            # These are intentionally read only if the template
            # sends them. They are NEVER assigned to Student.
            #

            _country_form = _clean(
                request.form.get(
                    "country"
                )
            )

            _phone_country_form = _clean(
                request.form.get(
                    "phone_country"
                )
            )

            _state_form = _clean(
                request.form.get(
                    "state"
                )
            )

            _parent_id_form = _clean(
                request.form.get(
                    "parent_id"
                )
            )

            # ====================================================
            # VALIDATE NAME
            # ====================================================

            if not full_name:
                raise ValueError(
                    "Student full name is required."
                )

            # ====================================================
            # VALIDATE STUDENT STATUS
            # ====================================================

            if not _valid_student_status(
                status
            ):
                raise ValueError(
                    "Invalid student status."
                )

            # ====================================================
            # PARENT / GUARDIAN
            # ====================================================

            parent_name = _clean(
                request.form.get(
                    "parent_name"
                )
            )

            relationship_to_student = _clean(
                request.form.get(
                    "relationship_to_student"
                )
            )

            parent_phone = _clean(
                request.form.get(
                    "parent_phone"
                )
            )

            parent_email = _clean(
                request.form.get(
                    "parent_email"
                )
            ).lower()

            parent_address = _clean(
                request.form.get(
                    "parent_address"
                )
            )

            # ====================================================
            # INSTITUTION / BRANCH
            # ====================================================

            submitted_institution_id = (
                _int_or_none(
                    request.form.get(
                        "institution_id"
                    )
                )
            )

            submitted_branch_id = (
                _int_or_none(
                    request.form.get(
                        "branch_id"
                    )
                )
            )

            # ====================================================
            # DETERMINE NEW INSTITUTION
            # ====================================================

            if current_user_role == "superadmin":

                if not submitted_institution_id:
                    raise ValueError(
                        "Please select an institution."
                    )

                new_institution_id = (
                    submitted_institution_id
                )

            else:

                if not current_user_institution_id:
                    raise ValueError(
                        "Your account is not assigned to an institution."
                    )

                new_institution_id = (
                    current_user_institution_id
                )

            # ====================================================
            # DETERMINE NEW BRANCH
            # ====================================================

            if current_user_role == "branch_admin":

                if not current_user_branch_id:
                    raise ValueError(
                        "Your account is not assigned to a branch."
                    )

                new_branch_id = (
                    current_user_branch_id
                )

            else:

                if not submitted_branch_id:
                    raise ValueError(
                        "Please select a branch."
                    )

                new_branch_id = (
                    submitted_branch_id
                )

            # ====================================================
            # VERIFY INSTITUTION
            # ====================================================

            institution = (
                Institution.query
                .filter(
                    Institution.id
                    == new_institution_id
                )
                .first()
            )

            if not institution:
                raise ValueError(
                    "Selected institution was not found."
                )

            # ====================================================
            # VERIFY BRANCH
            # ============================================================

            branch = (
                Branch.query
                .filter(
                    Branch.id
                    == new_branch_id,
                    Branch.institution_id
                    == new_institution_id,
                )
                .first()
            )

            if not branch:
                raise ValueError(
                    "Selected branch does not belong to the selected institution."
                )

            # ====================================================
            # ROLE-SPECIFIC BRANCH SECURITY
            # ============================================================

            if current_user_role == "school_admin":

                if (
                    new_institution_id
                    != current_user_institution_id
                ):
                    raise ValueError(
                        "You cannot move a student outside your institution."
                    )

            elif current_user_role == "branch_admin":

                if (
                    new_institution_id
                    != current_user_institution_id
                    or new_branch_id
                    != current_user_branch_id
                ):
                    raise ValueError(
                        "You cannot move a student outside your branch."
                    )

            # ====================================================
            # EMAIL DUPLICATE
            # ============================================================

            if email:

                duplicate_email = (
                    Student.query
                    .filter(
                        Student.email == email,
                        Student.id != student.id,
                    )
                    .first()
                )

                if duplicate_email:
                    raise ValueError(
                        "This email address is already used by another student."
                    )

            # ====================================================
            # UPDATE STUDENT
            # ============================================================

            student.institution_id = (
                new_institution_id
            )

            student.branch_id = (
                new_branch_id
            )

            student.full_name = (
                full_name
            )

            student.email = (
                email or None
            )

            student.gender = (
                gender or None
            )

            student.date_of_birth = (
                date_of_birth
            )

            student.place_of_birth = (
                place_of_birth or None
            )

            student.nationality = (
                nationality or None
            )

            student.phone = (
                phone or None
            )

            student.city = (
                city or None
            )

            student.address = (
                address or None
            )

            student.parent_name = (
                parent_name or None
            )

            student.relationship_to_student = (
                relationship_to_student or None
            )

            student.parent_phone = (
                parent_phone or None
            )

            student.parent_email = (
                parent_email or None
            )

            student.parent_address = (
                parent_address or None
            )

            student.status = (
                status
            )

            student.is_active = (
                status == "active"
            )

            student.notes = (
                notes or None
            )

            # ====================================================
            # PHOTO UPLOAD
            # ====================================================

            photo_file = request.files.get(
                "photo"
            )

            if (
                photo_file
                and photo_file.filename
            ):

                original_filename = secure_filename(
                    photo_file.filename
                )

                if not original_filename:
                    raise ValueError(
                        "Invalid photo filename."
                    )

                extension = ""

                if "." in original_filename:
                    extension = (
                        original_filename
                        .rsplit(".", 1)[1]
                        .lower()
                    )

                allowed_extensions = {
                    "jpg",
                    "jpeg",
                    "png",
                    "webp",
                }

                if extension not in allowed_extensions:
                    raise ValueError(
                        "Invalid photo format. "
                        "Use JPG, JPEG, PNG or WebP."
                    )

                upload_folder = os.path.join(
                    current_app.root_path,
                    "static",
                    "uploads",
                    "students",
                )

                os.makedirs(
                    upload_folder,
                    exist_ok=True,
                )

                unique_filename = (
                    f"student_{student.id}_"
                    f"{int(datetime.utcnow().timestamp())}_"
                    f"{os.urandom(4).hex()}."
                    f"{extension}"
                )

                absolute_photo_path = os.path.join(
                    upload_folder,
                    unique_filename,
                )

                photo_file.save(
                    absolute_photo_path
                )

                uploaded_photo_path = (
                    absolute_photo_path
                )

                student.photo = (
                    "uploads/students/"
                    + unique_filename
                )

            # ====================================================
            # ENROLLMENT ARRAYS
            # ====================================================

            existing_enrollment_ids = (
                request.form.getlist(
                    "existing_enrollment_id[]"
                )
            )

            academic_year_ids = (
                request.form.getlist(
                    "academic_year_id[]"
                )
            )

            program_ids = (
                request.form.getlist(
                    "program_id[]"
                )
            )

            class_ids = (
                request.form.getlist(
                    "class_id[]"
                )
            )

            section_ids = (
                request.form.getlist(
                    "section_id[]"
                )
            )

            enrollment_dates = (
                request.form.getlist(
                    "enrollment_date[]"
                )
            )

            enrollment_statuses = (
                request.form.getlist(
                    "enrollment_status[]"
                )
            )

            enrollment_notes = (
                request.form.getlist(
                    "enrollment_notes[]"
                )
            )

            # ====================================================
            # DETERMINE NUMBER OF ENROLLMENT ROWS
            # ====================================================

            max_enrollment_rows = max(
                len(existing_enrollment_ids),
                len(academic_year_ids),
                len(program_ids),
                len(class_ids),
                len(section_ids),
                len(enrollment_dates),
                len(enrollment_statuses),
                len(enrollment_notes),
                0,
            )

            # ====================================================
            # EXISTING ENROLLMENT MAP
            # ====================================================

            existing_enrollment_map = {
                enrollment.id: enrollment
                for enrollment
                in list(student.enrollments)
            }

            submitted_existing_enrollment_ids = set()

            # ====================================================
            # ENROLLMENT RECORDS
            # ====================================================

            enrollment_records = []

            # Maps:
            # row index -> enrollment object
            enrollment_by_row = {}

            # Maps:
            # old enrollment id -> enrollment object
            enrollment_by_old_id = {}

            # ====================================================
            # PROCESS ENROLLMENTS
            # ====================================================

            for index in range(
                max_enrollment_rows
            ):

                # ------------------------------------------------
                # SAFE ARRAY ACCESS
                # ------------------------------------------------

                existing_raw = (
                    existing_enrollment_ids[index]
                    if index
                    < len(existing_enrollment_ids)
                    else ""
                )

                academic_year_raw = (
                    academic_year_ids[index]
                    if index
                    < len(academic_year_ids)
                    else ""
                )

                program_raw = (
                    program_ids[index]
                    if index
                    < len(program_ids)
                    else ""
                )

                class_raw = (
                    class_ids[index]
                    if index
                    < len(class_ids)
                    else ""
                )

                section_raw = (
                    section_ids[index]
                    if index
                    < len(section_ids)
                    else ""
                )

                enrollment_date_raw = (
                    enrollment_dates[index]
                    if index
                    < len(enrollment_dates)
                    else ""
                )

                enrollment_status_raw = (
                    enrollment_statuses[index]
                    if index
                    < len(enrollment_statuses)
                    else "active"
                )

                enrollment_note_raw = (
                    enrollment_notes[index]
                    if index
                    < len(enrollment_notes)
                    else ""
                )

                # ------------------------------------------------
                # EXISTING ID
                # ------------------------------------------------

                existing_id = _int_or_none(
                    existing_raw
                )

                # ------------------------------------------------
                # EMPTY ROW
                # ------------------------------------------------

                if not any(
                    [
                        academic_year_raw,
                        program_raw,
                        class_raw,
                        section_raw,
                        enrollment_date_raw,
                        enrollment_note_raw,
                        existing_id,
                    ]
                ):
                    continue

                # ------------------------------------------------
                # REQUIRED FIELDS
                # ------------------------------------------------

                academic_year_id = _int_or_none(
                    academic_year_raw
                )

                program_id = _int_or_none(
                    program_raw
                )

                class_id = _int_or_none(
                    class_raw
                )

                section_id = _int_or_none(
                    section_raw
                )

                if not academic_year_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Academic Year is required."
                    )

                if not program_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Program is required."
                    )

                if not class_id:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Class is required."
                    )

                # ------------------------------------------------
                # DATE
                # ------------------------------------------------

                enrollment_date = (
                    _parse_date(
                        enrollment_date_raw
                    )
                    or date.today()
                )

                # ------------------------------------------------
                # STATUS
                # ------------------------------------------------

                enrollment_status = (
                    _clean(
                        enrollment_status_raw
                    )
                    or "active"
                ).lower()

                if (
                    enrollment_status
                    not in valid_enrollment_statuses
                ):
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Invalid enrollment status."
                    )

                enrollment_note = (
                    _clean(
                        enrollment_note_raw
                    )
                    or None
                )

                # =================================================
                # ACADEMIC YEAR VALIDATION
                # =================================================

                academic_year = (
                    AcademicYear.query
                    .filter(
                        AcademicYear.id
                        == academic_year_id,
                        AcademicYear.institution_id
                        == new_institution_id,
                    )
                    .first()
                )

                if not academic_year:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Academic Year does not belong to the selected institution."
                    )

                # =================================================
                # PROGRAM VALIDATION
                # =================================================

                program = (
                    Program.query
                    .filter(
                        Program.id
                        == program_id,
                        Program.institution_id
                        == new_institution_id,
                        or_(
                            Program.branch_id
                            == new_branch_id,
                            Program.branch_id.is_(None),
                        ),
                    )
                    .first()
                )

                if not program:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Program does not belong to the selected institution/branch."
                    )

                # =================================================
                # CLASS VALIDATION
                # =================================================

                selected_class = (
                    Class.query
                    .filter(
                        Class.id
                        == class_id,
                        Class.institution_id
                        == new_institution_id,
                        Class.branch_id
                        == new_branch_id,
                    )
                    .first()
                )

                if not selected_class:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Class does not belong to the selected branch."
                    )

                # =================================================
                # CLASS → PROGRAM VALIDATION
                # =================================================

                class_program_id = getattr(
                    selected_class,
                    "program_id",
                    None,
                )

                if (
                    class_program_id is not None
                    and class_program_id
                    != program.id
                ):
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "Selected class does not belong to selected program."
                    )

                # =================================================
                # SECTION VALIDATION
                # =================================================

                section = None

                if section_id:

                    section = (
                        Section.query
                        .filter(
                            Section.id
                            == section_id,
                            Section.institution_id
                            == new_institution_id,
                            Section.branch_id
                            == new_branch_id,
                            Section.class_id
                            == class_id,
                        )
                        .first()
                    )

                    if not section:
                        raise ValueError(
                            f"Enrollment row {index + 1}: "
                            "Selected section does not belong to selected class."
                        )

                # =================================================
                # EXISTING ENROLLMENT
                # =================================================

                enrollment = None

                if existing_id:

                    enrollment = (
                        existing_enrollment_map
                        .get(existing_id)
                    )

                    if not enrollment:
                        raise ValueError(
                            f"Enrollment row {index + 1}: "
                            "Invalid existing enrollment."
                        )

                    submitted_existing_enrollment_ids.add(
                        existing_id
                    )

                # =================================================
                # DUPLICATE ACADEMIC YEAR
                # =================================================

                duplicate_query = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,
                        StudentEnrollment.academic_year_id
                        == academic_year.id,
                    )
                )

                if enrollment:
                    duplicate_query = (
                        duplicate_query
                        .filter(
                            StudentEnrollment.id
                            != enrollment.id
                        )
                    )

                duplicate_enrollment = (
                    duplicate_query.first()
                )

                if duplicate_enrollment:
                    raise ValueError(
                        f"Enrollment row {index + 1}: "
                        "This student already has another enrollment for the selected academic year."
                    )

                # =================================================
                # UPDATE EXISTING
                # =================================================

                if enrollment:

                    enrollment.institution_id = (
                        new_institution_id
                    )

                    enrollment.branch_id = (
                        new_branch_id
                    )

                    enrollment.student_id = (
                        student.id
                    )

                    enrollment.academic_year_id = (
                        academic_year.id
                    )

                    enrollment.program_id = (
                        program.id
                    )

                    enrollment.class_id = (
                        selected_class.id
                    )

                    enrollment.section_id = (
                        section.id
                        if section
                        else None
                    )

                    enrollment.enrollment_date = (
                        enrollment_date
                    )

                    enrollment.status = (
                        enrollment_status
                    )

                    enrollment.notes = (
                        enrollment_note
                    )

                # =================================================
                # CREATE NEW
                # =================================================

                else:

                    # --------------------------------------------
                    # Generate a safer enrollment number
                    # --------------------------------------------

                    base_enrollment_no = (
                        f"{student.admission_no}-E"
                    )

                    enrollment_no = (
                        base_enrollment_no
                        + str(index + 1)
                    )

                    # --------------------------------------------
                    # Avoid duplicate enrollment number
                    # --------------------------------------------

                    counter = 1

                    while (
                        StudentEnrollment.query
                        .filter(
                            StudentEnrollment.institution_id
                            == new_institution_id,
                            StudentEnrollment.enrollment_no
                            == enrollment_no,
                        )
                        .first()
                    ):

                        counter += 1

                        enrollment_no = (
                            f"{base_enrollment_no}"
                            f"{index + 1}-{counter}"
                        )

                    enrollment = StudentEnrollment(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        academic_year_id=(
                            academic_year.id
                        ),
                        program_id=(
                            program.id
                        ),
                        class_id=(
                            selected_class.id
                        ),
                        section_id=(
                            section.id
                            if section
                            else None
                        ),
                        enrollment_no=(
                            enrollment_no
                        ),
                        enrollment_date=(
                            enrollment_date
                        ),
                        status=(
                            enrollment_status
                        ),
                        notes=(
                            enrollment_note
                        ),
                    )

                    db.session.add(
                        enrollment
                    )

                # ------------------------------------------------
                # Keep mapping
                # ------------------------------------------------

                enrollment_by_row[
                    index
                ] = enrollment

                if existing_id:
                    enrollment_by_old_id[
                        existing_id
                    ] = enrollment

                enrollment_records.append(
                    {
                        "row_index": index,
                        "enrollment": enrollment,
                        "academic_year": academic_year,
                        "program": program,
                        "class": selected_class,
                        "section": section,
                    }
                )

            # ====================================================
            # REQUIRE ENROLLMENT
            # ====================================================

            if not enrollment_records:
                raise ValueError(
                    "Student must have at least one enrollment."
                )

            # ====================================================
            # FLUSH
            # ====================================================

            db.session.flush()

            # ====================================================
            # DELETE REMOVED ENROLLMENTS
            # ====================================================
            #
            # Charges use SET NULL, but before deletion we
            # explicitly detach them to avoid stale references.
            #

            for old_enrollment in list(
                student.enrollments
            ):

                if (
                    old_enrollment.id
                    not in submitted_existing_enrollment_ids
                    and old_enrollment.id
                    not in enrollment_by_old_id
                ):

                    # --------------------------------------------
                    # Detach charges
                    # --------------------------------------------

                    for charge in list(
                        old_enrollment.charges
                    ):
                        charge.enrollment_id = None

                        # If possible, attach to first enrollment.
                        if enrollment_records:
                            replacement = (
                                enrollment_records[0]
                                ["enrollment"]
                            )

                            charge.enrollment_id = (
                                replacement.id
                            )

                            charge.academic_year_id = (
                                replacement.academic_year_id
                            )

                    db.session.delete(
                        old_enrollment
                    )

            # ====================================================
            # FLUSH AGAIN
            # ====================================================

            db.session.flush()

            # ====================================================
            # FIRST ENROLLMENT
            # ====================================================

            first_record = (
                enrollment_records[0]
            )

            first_enrollment = (
                first_record["enrollment"]
            )

            first_academic_year = (
                first_record["academic_year"]
            )

            first_program = (
                first_record["program"]
            )

            # ====================================================
            # CHARGE FORM ARRAYS
            # ====================================================

            existing_charge_ids = (
                request.form.getlist(
                    "existing_charge_id[]"
                )
            )

            charge_types = (
                request.form.getlist(
                    "charge_type[]"
                )
            )

            charge_names = (
                request.form.getlist(
                    "charge_name[]"
                )
            )

            charge_amounts = (
                request.form.getlist(
                    "charge_amount[]"
                )
            )

            charge_discounts = (
                request.form.getlist(
                    "charge_discount[]"
                )
            )

            # ----------------------------------------------------
            # Support BOTH names:
            #
            # charge_paid[]
            # charge_paid_amount[]
            # ----------------------------------------------------

            charge_paid = (
                request.form.getlist(
                    "charge_paid[]"
                )
            )

            if not charge_paid:
                charge_paid = (
                    request.form.getlist(
                        "charge_paid_amount[]"
                    )
                )

            charge_due_dates = (
                request.form.getlist(
                    "charge_due_date[]"
                )
            )

            charge_descriptions = (
                request.form.getlist(
                    "charge_description[]"
                )
            )

            # ----------------------------------------------------
            # Support:
            #
            # charge_enrollment[]
            #
            # AND:
            #
            # charge_enrollment_index[]
            # ----------------------------------------------------

            charge_enrollment_values = (
                request.form.getlist(
                    "charge_enrollment[]"
                )
            )

            if not charge_enrollment_values:
                charge_enrollment_values = (
                    request.form.getlist(
                        "charge_enrollment_index[]"
                    )
                )

            # ====================================================
            # EXISTING CHARGE MAP
            # ====================================================

            existing_charge_map = {
                charge.id: charge
                for charge
                in list(student.charges)
            }

            # ====================================================
            # MANUAL CHARGE IDs SUBMITTED
            # ====================================================

            submitted_manual_charge_ids = set()

            for raw_charge_id in (
                existing_charge_ids
            ):

                charge_id = _int_or_none(
                    raw_charge_id
                )

                if charge_id:
                    submitted_manual_charge_ids.add(
                        charge_id
                    )

            # ====================================================
            # DELETE REMOVED MANUAL CHARGES
            # ====================================================
            #
            # Automatic:
            #   registration
            #   program_fee
            #
            # are protected and handled below.
            #

            for existing_charge in list(
                student.charges
            ):

                if (
                    existing_charge.charge_type
                    in {
                        "registration",
                        "program_fee",
                    }
                ):
                    continue

                if (
                    existing_charge.id
                    not in submitted_manual_charge_ids
                ):
                    db.session.delete(
                        existing_charge
                    )

            # ====================================================
            # REGISTRATION FEE
            # ====================================================

            registration_charge = (
                StudentCharge.query
                .filter(
                    StudentCharge.student_id
                    == student.id,
                    StudentCharge.charge_type
                    == "registration",
                )
                .order_by(
                    StudentCharge.id.asc()
                )
                .first()
            )

            if registration_charge:

                registration_charge.institution_id = (
                    new_institution_id
                )

                registration_charge.branch_id = (
                    new_branch_id
                )

                registration_charge.student_id = (
                    student.id
                )

                registration_charge.enrollment_id = (
                    first_enrollment.id
                )

                registration_charge.academic_year_id = (
                    first_academic_year.id
                )

                registration_charge.charge_type = (
                    "registration"
                )

                registration_charge.charge_name = (
                    "Registration Fee"
                )

                registration_charge.description = (
                    "Automatic registration fee"
                )

                registration_charge.amount = (
                    Decimal("5.00")
                )

                # Preserve existing discount/paid amount.
                if registration_charge.discount is None:
                    registration_charge.discount = (
                        Decimal("0.00")
                    )

                if registration_charge.paid_amount is None:
                    registration_charge.paid_amount = (
                        Decimal("0.00")
                    )

                if not registration_charge.due_date:
                    registration_charge.due_date = (
                        date.today()
                    )

            else:

                registration_charge = StudentCharge(
                    institution_id=(
                        new_institution_id
                    ),
                    branch_id=(
                        new_branch_id
                    ),
                    student_id=(
                        student.id
                    ),
                    enrollment_id=(
                        first_enrollment.id
                    ),
                    academic_year_id=(
                        first_academic_year.id
                    ),
                    charge_type=(
                        "registration"
                    ),
                    charge_name=(
                        "Registration Fee"
                    ),
                    description=(
                        "Automatic registration fee"
                    ),
                    amount=(
                        Decimal("5.00")
                    ),
                    discount=(
                        Decimal("0.00")
                    ),
                    paid_amount=(
                        Decimal("0.00")
                    ),
                    due_date=(
                        date.today()
                    ),
                    created_by=(
                        current_user.id
                    ),
                )

                db.session.add(
                    registration_charge
                )

            registration_charge.calculate_balance()

            # ====================================================
            # PROGRAM FEE
            # ====================================================

            program_price = _decimal(
                getattr(
                    first_program,
                    "price",
                    0,
                )
            )

            program_charge = (
                StudentCharge.query
                .filter(
                    StudentCharge.student_id
                    == student.id,
                    StudentCharge.charge_type
                    == "program_fee",
                )
                .order_by(
                    StudentCharge.id.asc()
                )
                .first()
            )

            if (
                program_price
                > Decimal("0.00")
            ):

                if program_charge:

                    program_charge.institution_id = (
                        new_institution_id
                    )

                    program_charge.branch_id = (
                        new_branch_id
                    )

                    program_charge.student_id = (
                        student.id
                    )

                    program_charge.enrollment_id = (
                        first_enrollment.id
                    )

                    program_charge.academic_year_id = (
                        first_academic_year.id
                    )

                    program_charge.charge_type = (
                        "program_fee"
                    )

                    program_charge.charge_name = (
                        "Program Fee"
                    )

                    program_charge.description = (
                        "Automatic program fee - "
                        + str(
                            getattr(
                                first_program,
                                "name",
                                "Program",
                            )
                        )
                    )

                    program_charge.amount = (
                        program_price
                    )

                    if program_charge.discount is None:
                        program_charge.discount = (
                            Decimal("0.00")
                        )

                    if program_charge.paid_amount is None:
                        program_charge.paid_amount = (
                            Decimal("0.00")
                        )

                    if not program_charge.due_date:
                        program_charge.due_date = (
                            date.today()
                        )

                else:

                    program_charge = StudentCharge(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        enrollment_id=(
                            first_enrollment.id
                        ),
                        academic_year_id=(
                            first_academic_year.id
                        ),
                        charge_type=(
                            "program_fee"
                        ),
                        charge_name=(
                            "Program Fee"
                        ),
                        description=(
                            "Automatic program fee - "
                            + str(
                                getattr(
                                    first_program,
                                    "name",
                                    "Program",
                                )
                            )
                        ),
                        amount=(
                            program_price
                        ),
                        discount=(
                            Decimal("0.00")
                        ),
                        paid_amount=(
                            Decimal("0.00")
                        ),
                        due_date=(
                            date.today()
                        ),
                        created_by=(
                            current_user.id
                        ),
                    )

                    db.session.add(
                        program_charge
                    )

                program_charge.calculate_balance()

            else:

                # ------------------------------------------------
                # No program price.
                #
                # Delete only if nothing has been paid.
                # ------------------------------------------------

                if program_charge:

                    paid = _decimal(
                        program_charge.paid_amount
                    )

                    if paid <= Decimal("0.00"):

                        db.session.delete(
                            program_charge
                        )

            # ====================================================
            # MANUAL CHARGES
            # ====================================================

            max_charge_rows = max(
                len(existing_charge_ids),
                len(charge_types),
                len(charge_names),
                len(charge_amounts),
                len(charge_discounts),
                len(charge_paid),
                len(charge_due_dates),
                len(charge_descriptions),
                len(charge_enrollment_values),
                0,
            )

            for index in range(
                max_charge_rows
            ):

                # ------------------------------------------------
                # SAFE VALUES
                # ------------------------------------------------

                raw_existing_charge_id = (
                    existing_charge_ids[index]
                    if index
                    < len(existing_charge_ids)
                    else ""
                )

                charge_type = _clean(
                    charge_types[index]
                    if index
                    < len(charge_types)
                    else ""
                ).lower()

                charge_name = _clean(
                    charge_names[index]
                    if index
                    < len(charge_names)
                    else ""
                )

                amount = _decimal(
                    charge_amounts[index]
                    if index
                    < len(charge_amounts)
                    else "0"
                )

                discount = _decimal(
                    charge_discounts[index]
                    if index
                    < len(charge_discounts)
                    else "0"
                )

                paid_amount = _decimal(
                    charge_paid[index]
                    if index
                    < len(charge_paid)
                    else "0"
                )

                due_date = _parse_date(
                    charge_due_dates[index]
                    if index
                    < len(charge_due_dates)
                    else ""
                )

                description = _clean(
                    charge_descriptions[index]
                    if index
                    < len(charge_descriptions)
                    else ""
                )

                enrollment_value = _clean(
                    charge_enrollment_values[index]
                    if index
                    < len(charge_enrollment_values)
                    else ""
                )

                existing_charge_id = (
                    _int_or_none(
                        raw_existing_charge_id
                    )
                )

                # ------------------------------------------------
                # EMPTY ROW
                # ------------------------------------------------

                if not any(
                    [
                        charge_type,
                        charge_name,
                        amount != Decimal("0.00"),
                        discount != Decimal("0.00"),
                        paid_amount != Decimal("0.00"),
                        due_date,
                        description,
                        enrollment_value,
                        existing_charge_id,
                    ]
                ):
                    continue

                # ------------------------------------------------
                # AUTOMATIC TYPES
                # ------------------------------------------------

                if charge_type in {
                    "registration",
                    "program_fee",
                }:
                    continue

                # ------------------------------------------------
                # DEFAULT TYPE
                # ------------------------------------------------

                if not charge_type:
                    charge_type = "other"

                if (
                    charge_type
                    not in valid_charge_types
                ):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Invalid charge type."
                    )

                # ------------------------------------------------
                # NAME
                # ------------------------------------------------

                if not charge_name:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Charge name is required."
                    )

                # ------------------------------------------------
                # AMOUNT
                # ------------------------------------------------

                if amount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Amount cannot be negative."
                    )

                # ------------------------------------------------
                # DISCOUNT
                # ------------------------------------------------

                if discount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Discount cannot be negative."
                    )

                if discount > amount:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Discount cannot be greater than amount."
                    )

                # ------------------------------------------------
                # PAID
                # ------------------------------------------------

                if paid_amount < Decimal("0.00"):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Paid amount cannot be negative."
                    )

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Paid amount cannot exceed net amount."
                    )

                # =================================================
                # FIND ATTACHED ENROLLMENT
                # =================================================

                charge_enrollment = None

                if enrollment_value:

                    enrollment_number = (
                        _int_or_none(
                            enrollment_value
                        )
                    )

                    if enrollment_number is None:
                        raise ValueError(
                            f"Charge row {index + 1}: "
                            "Invalid enrollment selection."
                        )

                    # ------------------------------------------------
                    # FIRST:
                    # Treat value as ROW INDEX.
                    #
                    # This matches the current edit template.
                    # ------------------------------------------------

                    if (
                        enrollment_number
                        in enrollment_by_row
                    ):

                        charge_enrollment = (
                            enrollment_by_row[
                                enrollment_number
                            ]
                        )

                    # ------------------------------------------------
                    # SECOND:
                    # Treat value as actual enrollment ID.
                    #
                    # This makes route compatible with a template
                    # that sends enrollment.id.
                    # ------------------------------------------------

                    else:

                        charge_enrollment = (
                            StudentEnrollment.query
                            .filter(
                                StudentEnrollment.id
                                == enrollment_number,
                                StudentEnrollment.student_id
                                == student.id,
                            )
                            .first()
                        )

                        if not charge_enrollment:

                            raise ValueError(
                                f"Charge row {index + 1}: "
                                "Selected enrollment does not exist."
                            )

                else:

                    # ------------------------------------------------
                    # Default to first enrollment
                    # ------------------------------------------------

                    charge_enrollment = (
                        first_enrollment
                    )

                # =================================================
                # VERIFY ENROLLMENT BELONGS TO STUDENT
                # =================================================

                if (
                    not charge_enrollment
                    or charge_enrollment.student_id
                    != student.id
                ):
                    raise ValueError(
                        f"Charge row {index + 1}: "
                        "Selected enrollment does not belong to this student."
                    )

                # =================================================
                # FIND EXISTING CHARGE
                # =================================================

                existing_charge = None

                if existing_charge_id:

                    existing_charge = (
                        existing_charge_map
                        .get(
                            existing_charge_id
                        )
                    )

                    if not existing_charge:
                        raise ValueError(
                            f"Charge row {index + 1}: "
                            "Invalid existing charge."
                        )

                    # --------------------------------------------
                    # Never allow automatic charge editing through
                    # manual charge rows.
                    # --------------------------------------------

                    if (
                        existing_charge.charge_type
                        in {
                            "registration",
                            "program_fee",
                        }
                    ):
                        continue

                # =================================================
                # UPDATE EXISTING MANUAL CHARGE
                # =================================================

                if existing_charge:

                    existing_charge.institution_id = (
                        new_institution_id
                    )

                    existing_charge.branch_id = (
                        new_branch_id
                    )

                    existing_charge.student_id = (
                        student.id
                    )

                    existing_charge.enrollment_id = (
                        charge_enrollment.id
                    )

                    existing_charge.academic_year_id = (
                        charge_enrollment.academic_year_id
                    )

                    existing_charge.charge_type = (
                        charge_type
                    )

                    existing_charge.charge_name = (
                        charge_name
                    )

                    existing_charge.description = (
                        description or None
                    )

                    existing_charge.amount = (
                        amount
                    )

                    existing_charge.discount = (
                        discount
                    )

                    existing_charge.paid_amount = (
                        paid_amount
                    )

                    existing_charge.due_date = (
                        due_date
                    )

                    existing_charge.calculate_balance()

                # =================================================
                # CREATE NEW MANUAL CHARGE
                # =================================================

                else:

                    new_charge = StudentCharge(
                        institution_id=(
                            new_institution_id
                        ),
                        branch_id=(
                            new_branch_id
                        ),
                        student_id=(
                            student.id
                        ),
                        enrollment_id=(
                            charge_enrollment.id
                        ),
                        academic_year_id=(
                            charge_enrollment
                            .academic_year_id
                        ),
                        charge_type=(
                            charge_type
                        ),
                        charge_name=(
                            charge_name
                        ),
                        description=(
                            description or None
                        ),
                        amount=(
                            amount
                        ),
                        discount=(
                            discount
                        ),
                        paid_amount=(
                            paid_amount
                        ),
                        due_date=(
                            due_date
                        ),
                        created_by=(
                            current_user.id
                        ),
                    )

                    new_charge.calculate_balance()

                    db.session.add(
                        new_charge
                    )

            # ====================================================
            # UPDATE TIMESTAMP
            # ====================================================

            student.updated_at = (
                datetime.utcnow()
            )

            # ====================================================
            # FINAL FLUSH
            # ============================================================

            db.session.flush()

            # ====================================================
            # COMMIT
            # ============================================================

            db.session.commit()

            # ====================================================
            # SUCCESS
            # ============================================================

            flash(
                f"Student '{student.full_name}' was updated successfully.",
                "success",
            )

            # ====================================================
            # REDIRECT
            # ============================================================

            if (
                "main.view_student"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.view_student",
                        student_id=student.id,
                    )
                )

            if (
                "main.student_profile"
                in current_app.view_functions
            ):

                return redirect(
                    url_for(
                        "main.student_profile",
                        student_id=student.id,
                    )
                )

            return redirect(
                url_for(
                    "main.all_students"
                )
            )

        # ========================================================
        # VALUE / VALIDATION ERROR
        # ========================================================

        except ValueError as exc:

            db.session.rollback()

            if (
                uploaded_photo_path
                and os.path.exists(
                    uploaded_photo_path
                )
            ):

                try:
                    os.remove(
                        uploaded_photo_path
                    )
                except OSError:
                    pass

            flash(
                f"Unable to update student. Error: {exc}",
                "danger",
            )

            return redirect(
                request.url
            )

        # ========================================================
        # DATABASE / GENERAL ERROR
        # ========================================================

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Error updating student %s",
                student_id,
            )

            if (
                uploaded_photo_path
                and os.path.exists(
                    uploaded_photo_path
                )
            ):

                try:
                    os.remove(
                        uploaded_photo_path
                    )
                except OSError:
                    pass

            flash(
                f"Unable to update student. Error: {exc}",
                "danger",
            )

            return redirect(
                request.url
            )

    # ============================================================
    # GET DATA
    # ============================================================

    # ============================================================
    # INSTITUTIONS
    # ============================================================

    if current_user_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == current_user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ============================================================
    # BRANCHES
    # ============================================================

    if current_user_role == "superadmin":

        branches = (
            Branch.query
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    elif current_user_role == "school_admin":

        branches = (
            Branch.query
            .filter(
                Branch.institution_id
                == current_user_institution_id
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    else:

        branches = (
            Branch.query
            .filter(
                Branch.id
                == current_user_branch_id,
                Branch.institution_id
                == current_user_institution_id,
            )
            .order_by(
                Branch.name.asc()
            )
            .all()
        )

    # ============================================================
    # PROGRAMS
    # ============================================================

    programs = (
        Program.query
        .filter(
            Program.institution_id
            == student.institution_id,
            or_(
                Program.branch_id
                == student.branch_id,
                Program.branch_id.is_(None),
            ),
        )
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ============================================================
    # CLASSES
    # ============================================================

    classes = (
        Class.query
        .filter(
            Class.institution_id
            == student.institution_id,
            Class.branch_id
            == student.branch_id,
        )
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ============================================================
    # SECTIONS
    # ============================================================

    sections = (
        Section.query
        .filter(
            Section.institution_id
            == student.institution_id,
            Section.branch_id
            == student.branch_id,
        )
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # ============================================================
    # ACADEMIC YEARS
    # ============================================================

    academic_years = (
        AcademicYear.query
        .filter(
            AcademicYear.institution_id
            == student.institution_id
        )
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ============================================================
    # COUNTRIES
    # ============================================================

    try:

        countries = get_all_countries()

    except Exception:

        countries = []

    # ============================================================
    # CURRENT INSTITUTION
    # ============================================================

    current_institution = (
        Institution.query
        .filter(
            Institution.id
            == student.institution_id
        )
        .first()
    )

    # ============================================================
    # CURRENT BRANCH
    # ============================================================

    current_branch = (
        Branch.query
        .filter(
            Branch.id
            == student.branch_id
        )
        .first()
    )

    # ============================================================
    # EXISTING ENROLLMENTS
    # ============================================================

    enrollments = (
        StudentEnrollment.query
        .filter(
            StudentEnrollment.student_id
            == student.id
        )
        .order_by(
            StudentEnrollment.id.asc()
        )
        .all()
    )

    # ============================================================
    # EXISTING CHARGES
    # ============================================================

    charges = (
        StudentCharge.query
        .filter(
            StudentCharge.student_id
            == student.id
        )
        .order_by(
            StudentCharge.id.asc()
        )
        .all()
    )

    # ============================================================
    # RENDER TEMPLATE
    # ============================================================

    return render_template(
        "backend/pages/students/edit_student.html",

        # --------------------------------------------------------
        # Student
        # --------------------------------------------------------

        student=student,

        # --------------------------------------------------------
        # Scope
        # --------------------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,
        classes=classes,
        sections=sections,
        academic_years=academic_years,

        # --------------------------------------------------------
        # Countries
        # --------------------------------------------------------

        countries=countries,
        all_countries=countries,

        # --------------------------------------------------------
        # Current institution / branch
        # --------------------------------------------------------

        current_institution=current_institution,
        current_branch=current_branch,

        current_institution_id=(
            student.institution_id
        ),

        current_branch_id=(
            student.branch_id
        ),

        current_role=current_user_role,

        # --------------------------------------------------------
        # Existing enrollments
        # --------------------------------------------------------

        enrollments=enrollments,

        # --------------------------------------------------------
        # Existing charges
        # --------------------------------------------------------

        charges=charges,

        # --------------------------------------------------------
        # Today
        # --------------------------------------------------------

        today=date.today().isoformat(),

        # --------------------------------------------------------
        # Logged-in user
        # --------------------------------------------------------

        user=current_user,
    )


# ============================================================
# TOGGLE STUDENT ACCOUNT STATUS
# ============================================================

@bp.route(
    "/students/<int:student_id>/toggle-status",
    methods=["POST"]
)
@login_required
def toggle_student_status(student_id):

    # ========================================================
    # ACCESS CONTROL
    # ========================================================

    allowed_roles = {
        "superadmin",
        "institution_admin",
        "branch_admin",
    }

    if getattr(current_user, "role", None) not in allowed_roles:

        flash(
            "You do not have permission to change student status.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )


    # ========================================================
    # GET STUDENT
    # ========================================================

    student = Student.query.get_or_404(student_id)


    # ========================================================
    # CURRENT USER
    # ========================================================

    current_role = getattr(
        current_user,
        "role",
        None
    )

    current_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    current_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )


    # ========================================================
    # INSTITUTION ADMIN ACCESS
    # ========================================================

    if current_role == "institution_admin":

        if student.institution_id != current_institution_id:

            flash(
                "You cannot change the status of a student from another institution.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )


    # ========================================================
    # BRANCH ADMIN ACCESS
    # ========================================================

    if current_role == "branch_admin":

        if (
            student.institution_id != current_institution_id
            or
            student.branch_id != current_branch_id
        ):

            flash(
                "You cannot change the status of this student.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )


    # ========================================================
    # TOGGLE ACCOUNT STATUS
    # ========================================================

    student.is_active = not student.is_active

    student.updated_at = datetime.utcnow()


    # ========================================================
    # SAVE
    # ========================================================

    try:

        db.session.commit()

        if student.is_active:

            flash(
                f"{student.full_name} account has been activated.",
                "success"
            )

        else:

            flash(
                f"{student.full_name} account has been deactivated.",
                "warning"
            )

    except Exception as e:

        db.session.rollback()

        current_app.logger.exception(
            "Failed to toggle student status: %s",
            e
        )

        flash(
            "Unable to update student account status.",
            "danger"
        )


    # ========================================================
    # RETURN
    # ========================================================

    return redirect(
        url_for("main.all_students")
    )


# ============================================================
# DELETE STUDENT
# ============================================================
@bp.route(
    "/students/<int:student_id>/delete",
    methods=["POST"]
)
@login_required
def delete_student(student_id):

    # ============================================================
    # ALLOWED ROLES
    # ============================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    if current_user.role not in allowed_roles:
        abort(403)

    # ============================================================
    # ROLE VALIDATION
    # ============================================================

    if current_user.role == "school_admin":
        if not current_user.institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )
            return redirect(url_for("main.all_students"))

    if current_user.role == "branch_admin":
        if (
            not current_user.institution_id
            or not current_user.branch_id
        ):
            flash(
                "Your account is not assigned to an institution and branch.",
                "danger"
            )
            return redirect(url_for("main.all_students"))

    # ============================================================
    # GET STUDENT
    # ============================================================

    student_query = (
        Student.query
        .filter(
            Student.id == student_id,
            Student.role == "student"
        )
    )

    # ============================================================
    # SECURITY SCOPE
    # ============================================================

    if current_user.role == "school_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id
        )

    elif current_user.role == "branch_admin":

        student_query = student_query.filter(
            Student.institution_id == current_user.institution_id,
            Student.branch_id == current_user.branch_id
        )

    # ============================================================
    # FETCH STUDENT
    # ============================================================

    student = student_query.first()

    if not student:
        flash(
            "Student not found or you do not have permission to delete this student.",
            "danger"
        )
        return redirect(url_for("main.all_students"))

    # ============================================================
    # KEEP NAME FOR SUCCESS MESSAGE
    # ============================================================

    student_name = (
        student.full_name
        or student.username
        or f"Student #{student.id}"
    )

    # ============================================================
    # DELETE EVERYTHING RELATED TO THE STUDENT
    # ============================================================

    try:

        # --------------------------------------------------------
        # 1. DELETE STUDENT CHARGES
        #
        # StudentCharge has:
        # student_id -> students.id
        # enrollment_id -> student_enrollments.id
        # --------------------------------------------------------

        StudentCharge.query.filter(
            StudentCharge.student_id == student.id
        ).delete(
            synchronize_session=False
        )

        # --------------------------------------------------------
        # 2. DELETE STUDENT ENROLLMENTS
        # --------------------------------------------------------

        StudentEnrollment.query.filter(
            StudentEnrollment.student_id == student.id
        ).delete(
            synchronize_session=False
        )

        # --------------------------------------------------------
        # 3. DELETE STUDENT
        # --------------------------------------------------------

        db.session.delete(student)

        # --------------------------------------------------------
        # 4. COMMIT EVERYTHING
        # --------------------------------------------------------

        db.session.commit()

        flash(
            f"Student '{student_name}' and all related enrollment and charge records were deleted successfully.",
            "success"
        )

    except Exception as exc:

        # --------------------------------------------------------
        # ROLLBACK
        # --------------------------------------------------------

        db.session.rollback()

        current_app.logger.exception(
            "Failed to delete student ID %s: %s",
            student_id,
            exc
        )

        flash(
            "Unable to delete the student. No changes were saved.",
            "danger"
        )

    # ============================================================
    # RETURN TO STUDENT LIST
    # ============================================================

    return redirect(
        url_for("main.all_students")
    )





# ============================================================
# STUDENT FULL IMPORT SAMPLE CSV
# Student + Enrollment + StudentCharge
# ============================================================
@bp.route(
    "/students/import/sample",
    methods=["GET"]
)
@login_required
def export_student_import_sample():

    import csv
    import io

    from flask import Response, abort, flash, redirect, url_for
    from sqlalchemy import or_

    # ============================================================
    # PERMISSION
    # ============================================================

    if not _student_can_manage():
        abort(403)

    # ============================================================
    # CURRENT USER
    # ============================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if not institution_id:
        flash(
            "Your account is not linked to an institution.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # ACADEMIC YEAR
    # ============================================================
    #
    # Priority:
    # 1. Current
    # 2. Active
    # 3. Latest
    #
    # ============================================================

    academic_year = None

    # ------------------------------------------------------------
    # Try current / active
    # ------------------------------------------------------------

    try:

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id == institution_id
            )
            .filter(
                or_(
                    AcademicYear.is_current.is_(True),
                    AcademicYear.status == "active"
                )
            )
            .order_by(
                AcademicYear.id.desc()
            )
            .first()
        )

    except Exception:

        academic_year = None

    # ------------------------------------------------------------
    # Fallback latest
    # ------------------------------------------------------------

    if not academic_year:

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.institution_id == institution_id
            )
            .order_by(
                AcademicYear.id.desc()
            )
            .first()
        )

    if not academic_year:

        flash(
            "No Academic Year was found for this institution.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # ACADEMIC YEAR DISPLAY VALUE
    # ============================================================

    academic_year_name = (
        getattr(
            academic_year,
            "name",
            None
        )
        or getattr(
            academic_year,
            "academic_year",
            None
        )
        or getattr(
            academic_year,
            "title",
            None
        )
        or getattr(
            academic_year,
            "year_name",
            None
        )
        or getattr(
            academic_year,
            "code",
            None
        )
        or str(academic_year.id)
    )

    # ============================================================
    # PROGRAM
    # ============================================================
    #
    # Program:
    #
    #   institution = current institution
    #
    # AND:
    #
    #   branch = current branch
    #
    # OR:
    #
    #   branch = NULL
    #
    # NULL = institution-wide program
    #
    # ============================================================

    program = None

    if branch_id:

        program_query = (
            Program.query
            .filter(
                Program.institution_id == institution_id
            )
            .filter(
                or_(
                    Program.branch_id == branch_id,
                    Program.branch_id.is_(None)
                )
            )
        )

        # --------------------------------------------------------
        # Prefer active
        # --------------------------------------------------------

        try:

            program = (
                program_query
                .filter(
                    Program.status == "active"
                )
                .order_by(
                    (Program.branch_id == branch_id).desc(),
                    Program.id.asc()
                )
                .first()
            )

        except Exception:

            program = None

        # --------------------------------------------------------
        # Fallback without status
        # --------------------------------------------------------

        if not program:

            program = (
                program_query
                .order_by(
                    (Program.branch_id == branch_id).desc(),
                    Program.id.asc()
                )
                .first()
            )

    else:

        # --------------------------------------------------------
        # Institution-level user
        # --------------------------------------------------------

        program_query = (
            Program.query
            .filter(
                Program.institution_id == institution_id
            )
        )

        try:

            program = (
                program_query
                .filter(
                    Program.status == "active"
                )
                .order_by(
                    Program.id.asc()
                )
                .first()
            )

        except Exception:

            program = None

        if not program:

            program = (
                program_query
                .order_by(
                    Program.id.asc()
                )
                .first()
            )

    if not program:

        flash(
            "No Program was found for this institution/branch.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ============================================================
    # PROGRAM DISPLAY NAME
    # ============================================================

    program_name = (
        getattr(
            program,
            "name",
            None
        )
        or getattr(
            program,
            "title",
            None
        )
        or getattr(
            program,
            "short_name",
            None
        )
        or getattr(
            program,
            "code",
            None
        )
        or str(program.id)
    )

    # ============================================================
    # CLASS
    # ============================================================
    #
    # CLASS IS NOT REQUIRED.
    #
    # We try several possibilities:
    #
    # 1. Class.program_id = Program.id
    # 2. Class branch = current branch
    # 3. Class institution = current institution
    #
    # If no class exists:
    #
    #   Class = ""
    #   Section = ""
    #
    # ============================================================

    student_class = None

    # ------------------------------------------------------------
    # Base class query
    # ------------------------------------------------------------

    class_query = (
        Class.query
        .filter(
            Class.institution_id == institution_id
        )
    )

    # ------------------------------------------------------------
    # Branch filtering
    # ------------------------------------------------------------

    if branch_id:

        class_query = (
            class_query
            .filter(
                or_(
                    Class.branch_id == branch_id,
                    Class.branch_id.is_(None)
                )
            )
        )

    # ============================================================
    # FIRST TRY:
    # CLASS -> PROGRAM
    # ============================================================

    if hasattr(Class, "program_id"):

        try:

            program_class_query = (
                class_query
                .filter(
                    Class.program_id == program.id
                )
            )

            # ----------------------------------------------------
            # Active first
            # ----------------------------------------------------

            try:

                student_class = (
                    program_class_query
                    .filter(
                        Class.status == "active"
                    )
                    .order_by(
                        (
                            Class.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Class.id.asc()
                    )
                    .first()
                )

            except Exception:

                student_class = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not student_class:

                student_class = (
                    program_class_query
                    .order_by(
                        Class.id.asc()
                    )
                    .first()
                )

        except Exception:

            student_class = None

    # ============================================================
    # SECOND TRY:
    # CLASS WITHOUT PROGRAM RELATIONSHIP
    # ============================================================
    #
    # If Class.program_id does not match anything, we still use
    # the real Class belonging to current branch.
    #
    # ============================================================

    if not student_class:

        try:

            # ----------------------------------------------------
            # Active class first
            # ----------------------------------------------------

            try:

                student_class = (
                    class_query
                    .filter(
                        Class.status == "active"
                    )
                    .order_by(
                        (
                            Class.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Class.id.asc()
                    )
                    .first()
                )

            except Exception:

                student_class = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not student_class:

                student_class = (
                    class_query
                    .order_by(
                        Class.id.asc()
                    )
                    .first()
                )

        except Exception:

            student_class = None

    # ============================================================
    # CLASS NAME
    # ============================================================

    class_name = ""

    if student_class:

        class_name = (
            getattr(
                student_class,
                "name",
                None
            )
            or getattr(
                student_class,
                "class_name",
                None
            )
            or getattr(
                student_class,
                "title",
                None
            )
            or getattr(
                student_class,
                "code",
                None
            )
            or str(student_class.id)
        )

    # ============================================================
    # SECTION
    # ============================================================
    #
    # SECTION IS OPTIONAL.
    #
    # If Class exists:
    #
    #     search Section.class_id
    #
    # If no section:
    #
    #     ""
    #
    # ============================================================

    section = None

    if student_class and hasattr(Section, "class_id"):

        try:

            section_query = (
                Section.query
                .filter(
                    Section.class_id == student_class.id
                )
                .filter(
                    Section.institution_id == institution_id
                )
            )

            # ----------------------------------------------------
            # Branch
            # ----------------------------------------------------

            if branch_id:

                section_query = (
                    section_query
                    .filter(
                        or_(
                            Section.branch_id == branch_id,
                            Section.branch_id.is_(None)
                        )
                    )
                )

            # ----------------------------------------------------
            # Active first
            # ----------------------------------------------------

            try:

                section = (
                    section_query
                    .filter(
                        Section.status == "active"
                    )
                    .order_by(
                        (
                            Section.branch_id == branch_id
                        ).desc()
                        if branch_id
                        else Section.id.asc()
                    )
                    .first()
                )

            except Exception:

                section = None

            # ----------------------------------------------------
            # Fallback
            # ----------------------------------------------------

            if not section:

                section = (
                    section_query
                    .order_by(
                        Section.id.asc()
                    )
                    .first()
                )

        except Exception:

            section = None

    # ============================================================
    # SECTION NAME
    # ============================================================

    section_name = ""

    if section:

        section_name = (
            getattr(
                section,
                "name",
                None
            )
            or getattr(
                section,
                "section_name",
                None
            )
            or getattr(
                section,
                "title",
                None
            )
            or getattr(
                section,
                "code",
                None
            )
            or str(section.id)
        )

    # ============================================================
    # EXCEL-SAFE PHONE NUMBERS
    # ============================================================

    sample_phone = '="0612345678"'

    sample_parent_phone = '="0611111111"'

    # ============================================================
    # CSV HEADERS
    # ============================================================

    headers = [

        # --------------------------------------------------------
        # STUDENT
        # --------------------------------------------------------

        "Admission No",
        "Roll No",
        "Username",
        "Email",
        "Full Name",
        "Gender",
        "Date of Birth",
        "Place of Birth",
        "Nationality",
        "Phone",
        "Address",
        "City",

        # --------------------------------------------------------
        # PARENT
        # --------------------------------------------------------

        "Parent Name",
        "Parent Phone",
        "Parent Email",
        "Parent Address",
        "Relationship to Student",

        # --------------------------------------------------------
        # STUDENT STATUS
        # --------------------------------------------------------

        "Student Status",
        "Student Notes",

        # --------------------------------------------------------
        # ENROLLMENT
        # --------------------------------------------------------

        "Academic Year",
        "Program",
        "Class",
        "Section",
        "Enrollment No",
        "Enrollment Date",
        "Enrollment Status",
        "Enrollment Notes",

        # --------------------------------------------------------
        # CHARGE
        # --------------------------------------------------------

        "Charge Type",
        "Charge Name",
        "Charge Description",
        "Amount",
        "Discount",
        "Paid Amount",
        "Due Date",
    ]

    # ============================================================
    # SAMPLE ROW
    # ============================================================

    sample_row = [

        # --------------------------------------------------------
        # STUDENT
        # --------------------------------------------------------

        "STU001",
        "R001",
        "STU001",
        "student001@example.com",
        "Ahmed Mohamed Ali",
        "Male",
        "2010-05-15",
        "Mogadishu",
        "Somali",

        # Excel-safe phone
        sample_phone,

        "Hodan",
        "Mogadishu",

        # --------------------------------------------------------
        # PARENT
        # --------------------------------------------------------

        "Mohamed Ali Hassan",

        # Excel-safe parent phone
        sample_parent_phone,

        "parent001@example.com",
        "Hodan, Mogadishu",
        "Father",

        # --------------------------------------------------------
        # STUDENT STATUS
        # --------------------------------------------------------

        "active",
        "New student registration",

        # --------------------------------------------------------
        # REAL DATABASE RELATIONSHIPS
        # --------------------------------------------------------

        academic_year_name,
        program_name,
        class_name,
        section_name,

        # --------------------------------------------------------
        # ENROLLMENT
        # --------------------------------------------------------

        "ENR001",
        "2026-09-20",
        "active",
        "First enrollment",

        # --------------------------------------------------------
        # CHARGE
        # --------------------------------------------------------

        "registration",
        "Registration Fee",
        "Student registration fee",
        "50.00",
        "0.00",
        "0.00",
        "2026-09-30",
    ]

    # ============================================================
    # CREATE CSV
    # ============================================================

    output = io.StringIO(
        newline=""
    )

    writer = csv.writer(
        output,
        delimiter=",",
        quotechar='"',
        quoting=csv.QUOTE_MINIMAL,
        lineterminator="\r\n"
    )

    # Header
    writer.writerow(headers)

    # Real-data sample
    writer.writerow(sample_row)

    # ============================================================
    # UTF-8 BOM
    # ============================================================

    csv_content = (
        "\ufeff"
        + output.getvalue()
    )

    output.close()

    # ============================================================
    # RESPONSE
    # ============================================================

    return Response(
        csv_content,
        mimetype="text/csv; charset=utf-8",
        headers={
            "Content-Disposition":
                "attachment; "
                "filename=student_import_sample.csv"
        }
    )


