# ============================================================
# IMPORT STUDENTS FULL CSV
# Student + Enrollment + StudentCharge
# ============================================================

@bp.route(
    "/students/import",
    methods=["POST"]
)
@login_required
def import_students_full():

    import csv
    import io
    import secrets
    from datetime import datetime
    from decimal import Decimal, InvalidOperation

    from flask import (
        request,
        redirect,
        url_for,
        flash,
        current_app,
    )

    # ========================================================
    # ACCESS CHECK
    # ========================================================

    if not _student_can_manage():
        abort(403)

    # ========================================================
    # GET CURRENT USER / INSTITUTION / BRANCH
    # ========================================================

    current_user_obj = current_user

    institution_id = getattr(
        current_user_obj,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user_obj,
        "branch_id",
        None
    )

    if not institution_id:
        flash(
            "Institution information could not be determined.",
            "danger"
        )
        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # FILE
    # ========================================================

    file = request.files.get("file")

    if not file or not file.filename:

        flash(
            "Please select a CSV file.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    if not file.filename.lower().endswith(".csv"):

        flash(
            "Only CSV files are allowed.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # READ FILE
    # ========================================================

    try:

        raw_data = file.read()

        if not raw_data:
            flash(
                "The CSV file is empty.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )

        # ----------------------------------------------------
        # UTF-8-SIG handles Excel BOM
        # ----------------------------------------------------

        text_data = raw_data.decode(
            "utf-8-sig"
        )

    except UnicodeDecodeError:

        flash(
            "CSV file must be UTF-8 encoded.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # CSV READER
    # ========================================================

    stream = io.StringIO(
        text_data,
        newline=""
    )

    reader = csv.DictReader(stream)

    if not reader.fieldnames:

        flash(
            "CSV file has no header row.",
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # REQUIRED COLUMNS
    # ========================================================

    required_columns = {

        "Admission No",
        "Username",
        "Full Name",

        "Academic Year",
        "Program",
        "Class",
        "Enrollment No",

        "Charge Type",
        "Charge Name",
        "Amount",
        "Discount",
        "Paid Amount",
    }

    actual_columns = {
        str(column).strip()
        for column in reader.fieldnames
        if column
    }

    missing_columns = (
        required_columns - actual_columns
    )

    if missing_columns:

        flash(
            "Missing CSV columns: "
            + ", ".join(
                sorted(missing_columns)
            ),
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # HELPER FUNCTIONS
    # ========================================================

    def clean(value):

        if value is None:
            return None

        value = str(value).strip()

        return value if value else None

    def parse_date(value, field_name):

        value = clean(value)

        if not value:
            return None

        formats = [
            "%Y-%m-%d",
            "%Y/%m/%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
        ]

        for fmt in formats:

            try:

                return datetime.strptime(
                    value,
                    fmt
                ).date()

            except ValueError:
                continue

        raise ValueError(
            f"{field_name} has invalid date "
            f"'{value}'. Use YYYY-MM-DD."
        )

    def decimal_value(
        value,
        field_name,
        default="0"
    ):

        value = clean(value)

        if not value:
            value = default

        try:

            amount = Decimal(
                value.replace(",", "")
            )

        except (
            InvalidOperation,
            ValueError
        ):

            raise ValueError(
                f"{field_name} has invalid amount "
                f"'{value}'."
            )

        if amount < 0:

            raise ValueError(
                f"{field_name} cannot be negative."
            )

        return amount.quantize(
            Decimal("0.01")
        )

    def normalize(value):

        value = clean(value)

        if not value:
            return ""

        return (
            value
            .strip()
            .lower()
        )

    # ========================================================
    # GENERIC MODEL NAME RESOLVER
    # ========================================================

    def resolve_model(
        model,
        value,
        model_name,
        institution_id=None,
        branch_id=None,
    ):

        value = clean(value)

        if not value:
            raise ValueError(
                f"{model_name} is required."
            )

        query = model.query

        # ----------------------------------------------------
        # Institution filter
        # ----------------------------------------------------

        if institution_id is not None:

            if hasattr(
                model,
                "institution_id"
            ):

                query = query.filter(
                    model.institution_id
                    == institution_id
                )

        # ----------------------------------------------------
        # Branch filter
        # ----------------------------------------------------

        if branch_id is not None:

            if hasattr(
                model,
                "branch_id"
            ):

                query = query.filter(
                    model.branch_id
                    == branch_id
                )

        # ----------------------------------------------------
        # Try exact fields
        # ----------------------------------------------------

        possible_fields = [
            "name",
            "title",
            "code",
            "label",
            "academic_year",
        ]

        for field_name in possible_fields:

            column = getattr(
                model,
                field_name,
                None
            )

            if column is None:
                continue

            obj = (
                query
                .filter(column == value)
                .first()
            )

            if obj:
                return obj

        # ----------------------------------------------------
        # Case-insensitive lookup
        # ----------------------------------------------------

        for field_name in possible_fields:

            column = getattr(
                model,
                field_name,
                None
            )

            if column is None:
                continue

            try:

                obj = (
                    query
                    .filter(
                        db.func.lower(column)
                        == normalize(value)
                    )
                    .first()
                )

                if obj:
                    return obj

            except Exception:
                continue

        raise ValueError(
            f"{model_name} '{value}' was not found."
        )

    # ========================================================
    # IMPORT COUNTERS
    # ========================================================

    created_students = 0
    updated_students = 0
    created_enrollments = 0
    created_charges = 0
    skipped_rows = 0

    errors = []

    # ========================================================
    # PROCESS CSV
    # ========================================================

    try:

        rows = list(reader)

        if not rows:

            flash(
                "CSV file contains no student records.",
                "danger"
            )

            return redirect(
                url_for("main.all_students")
            )

        # ====================================================
        # TRANSACTION
        # ====================================================

        for row_number, raw_row in enumerate(
            rows,
            start=2
        ):

            try:

                # --------------------------------------------
                # CLEAN ROW KEYS
                # --------------------------------------------

                row = {
                    str(key).strip(): clean(value)
                    for key, value in raw_row.items()
                    if key
                }

                # --------------------------------------------
                # STUDENT DATA
                # --------------------------------------------

                admission_no = clean(
                    row.get("Admission No")
                )

                username = clean(
                    row.get("Username")
                )

                full_name = clean(
                    row.get("Full Name")
                )

                if not admission_no:
                    raise ValueError(
                        "Admission No is required."
                    )

                if not username:
                    raise ValueError(
                        "Username is required."
                    )

                if not full_name:
                    raise ValueError(
                        "Full Name is required."
                    )

                # --------------------------------------------
                # VALIDATE STATUS
                # --------------------------------------------

                student_status = (
                    clean(
                        row.get("Student Status")
                    )
                    or "active"
                ).lower()

                allowed_student_statuses = {
                    "active",
                    "inactive",
                    "graduated",
                    "transferred",
                    "suspended",
                    "withdrawn",
                }

                if student_status not in (
                    allowed_student_statuses
                ):

                    raise ValueError(
                        f"Invalid Student Status "
                        f"'{student_status}'."
                    )

                # --------------------------------------------
                # FIND EXISTING STUDENT
                # --------------------------------------------

                student = (
                    Student.query
                    .filter(
                        Student.institution_id
                        == institution_id,
                        Student.admission_no
                        == admission_no,
                    )
                    .first()
                )

                # =================================================
                # CREATE STUDENT
                # =================================================

                if not student:

                    # --------------------------------------------
                    # Username collision check
                    # --------------------------------------------

                    username_exists = (
                        Student.query
                        .filter(
                            Student.username
                            == username
                        )
                        .first()
                    )

                    if username_exists:

                        raise ValueError(
                            f"Username '{username}' "
                            f"already exists."
                        )

                    # --------------------------------------------
                    # Email collision check
                    # --------------------------------------------

                    email = clean(
                        row.get("Email")
                    )

                    if email:

                        email_exists = (
                            Student.query
                            .filter(
                                Student.email
                                == email
                            )
                            .first()
                        )

                        if email_exists:

                            raise ValueError(
                                f"Email '{email}' "
                                f"already exists."
                            )

                    # --------------------------------------------
                    # Generate temporary password
                    # --------------------------------------------

                    temporary_password = (
                        "Stu@"
                        + secrets.token_hex(4)
                    )

                    student = Student(

                        institution_id=(
                            institution_id
                        ),

                        branch_id=(
                            branch_id
                            if branch_id
                            else getattr(
                                current_user_obj,
                                "branch_id",
                                None
                            )
                        ),

                        username=username,

                        email=email,

                        admission_no=(
                            admission_no
                        ),

                        roll_no=clean(
                            row.get("Roll No")
                        ),

                        full_name=full_name,

                        gender=clean(
                            row.get("Gender")
                        ),

                        date_of_birth=parse_date(
                            row.get(
                                "Date of Birth"
                            ),
                            "Date of Birth"
                        ),

                        place_of_birth=clean(
                            row.get(
                                "Place of Birth"
                            )
                        ),

                        nationality=clean(
                            row.get(
                                "Nationality"
                            )
                        ),

                        phone=clean(
                            row.get("Phone")
                        ),

                        address=clean(
                            row.get("Address")
                        ),

                        city=clean(
                            row.get("City")
                        ),

                        parent_name=clean(
                            row.get(
                                "Parent Name"
                            )
                        ),

                        parent_phone=clean(
                            row.get(
                                "Parent Phone"
                            )
                        ),

                        parent_email=clean(
                            row.get(
                                "Parent Email"
                            )
                        ),

                        parent_address=clean(
                            row.get(
                                "Parent Address"
                            )
                        ),

                        relationship_to_student=clean(
                            row.get(
                                "Relationship to Student"
                            )
                        ),

                        status=student_status,

                        notes=clean(
                            row.get(
                                "Student Notes"
                            )
                        ),

                        role="student",

                        is_active=(
                            student_status
                            == "active"
                        ),

                        is_verified=False,
                    )

                    student.set_password(
                        temporary_password
                    )

                    db.session.add(student)

                    db.session.flush()

                    created_students += 1

                # =================================================
                # EXISTING STUDENT
                # =================================================

                else:

                    # --------------------------------------------
                    # Access check
                    # --------------------------------------------

                    if not _student_has_access(
                        student
                    ):

                        raise ValueError(
                            f"Access denied for "
                            f"student '{admission_no}'."
                        )

                    # --------------------------------------------
                    # Update student information
                    # --------------------------------------------

                    student.branch_id = (
                        branch_id
                        if branch_id
                        else student.branch_id
                    )

                    if clean(
                        row.get("Roll No")
                    ):
                        student.roll_no = clean(
                            row.get("Roll No")
                        )

                    student.full_name = (
                        full_name
                    )

                    if clean(
                        row.get("Email")
                    ):

                        new_email = clean(
                            row.get("Email")
                        )

                        email_exists = (
                            Student.query
                            .filter(
                                Student.email
                                == new_email,
                                Student.id
                                != student.id,
                            )
                            .first()
                        )

                        if email_exists:

                            raise ValueError(
                                f"Email "
                                f"'{new_email}' "
                                f"already belongs "
                                f"to another student."
                            )

                        student.email = (
                            new_email
                        )

                    if clean(
                        row.get("Gender")
                    ):
                        student.gender = clean(
                            row.get("Gender")
                        )

                    dob = parse_date(
                        row.get(
                            "Date of Birth"
                        ),
                        "Date of Birth"
                    )

                    if dob:
                        student.date_of_birth = dob

                    student.place_of_birth = (
                        clean(
                            row.get(
                                "Place of Birth"
                            )
                        )
                        or student.place_of_birth
                    )

                    student.nationality = (
                        clean(
                            row.get(
                                "Nationality"
                            )
                        )
                        or student.nationality
                    )

                    student.phone = (
                        clean(
                            row.get("Phone")
                        )
                        or student.phone
                    )

                    student.address = (
                        clean(
                            row.get("Address")
                        )
                        or student.address
                    )

                    student.city = (
                        clean(
                            row.get("City")
                        )
                        or student.city
                    )

                    student.parent_name = (
                        clean(
                            row.get(
                                "Parent Name"
                            )
                        )
                        or student.parent_name
                    )

                    student.parent_phone = (
                        clean(
                            row.get(
                                "Parent Phone"
                            )
                        )
                        or student.parent_phone
                    )

                    student.parent_email = (
                        clean(
                            row.get(
                                "Parent Email"
                            )
                        )
                        or student.parent_email
                    )

                    student.parent_address = (
                        clean(
                            row.get(
                                "Parent Address"
                            )
                        )
                        or student.parent_address
                    )

                    student.relationship_to_student = (
                        clean(
                            row.get(
                                "Relationship to Student"
                            )
                        )
                        or student.relationship_to_student
                    )

                    student.status = (
                        student_status
                    )

                    student.is_active = (
                        student_status
                        == "active"
                    )

                    if clean(
                        row.get(
                            "Student Notes"
                        )
                    ):

                        student.notes = clean(
                            row.get(
                                "Student Notes"
                            )
                        )

                    db.session.flush()

                    updated_students += 1

                # =================================================
                # BRANCH
                # =================================================

                effective_branch_id = (
                    student.branch_id
                )

                if not effective_branch_id:

                    raise ValueError(
                        "Student branch could not "
                        "be determined."
                    )

                # =================================================
                # ACADEMIC YEAR
                # =================================================

                academic_year = resolve_model(
                    AcademicYear,
                    row.get(
                        "Academic Year"
                    ),
                    "Academic Year",
                    institution_id=(
                        institution_id
                    ),
                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # PROGRAM
                # =================================================

                program = resolve_model(
                    Program,
                    row.get("Program"),
                    "Program",
                    institution_id=(
                        institution_id
                    ),
                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # CLASS
                # =================================================

                class_obj = resolve_model(
                    Class,
                    row.get("Class"),
                    "Class",
                    institution_id=(
                        institution_id
                    ),
                    branch_id=(
                        effective_branch_id
                    ),
                )

                # =================================================
                # SECTION
                # =================================================

                section_value = clean(
                    row.get("Section")
                )

                section = None

                if section_value:

                    section = resolve_model(
                        Section,
                        section_value,
                        "Section",
                        institution_id=(
                            institution_id
                        ),
                        branch_id=(
                            effective_branch_id
                        ),
                    )

                # =================================================
                # ENROLLMENT
                # =================================================

                enrollment_no = clean(
                    row.get(
                        "Enrollment No"
                    )
                )

                if not enrollment_no:

                    raise ValueError(
                        "Enrollment No is required."
                    )

                enrollment_date = (
                    parse_date(
                        row.get(
                            "Enrollment Date"
                        ),
                        "Enrollment Date"
                    )
                    or date.today()
                )

                enrollment_status = (
                    clean(
                        row.get(
                            "Enrollment Status"
                        )
                    )
                    or "active"
                ).lower()

                allowed_enrollment_statuses = {
                    "active",
                    "completed",
                    "transferred",
                    "withdrawn",
                    "suspended",
                    "promoted",
                }

                if enrollment_status not in (
                    allowed_enrollment_statuses
                ):

                    raise ValueError(
                        f"Invalid Enrollment Status "
                        f"'{enrollment_status}'."
                    )

                # ------------------------------------------------
                # Find by student + academic year
                # ------------------------------------------------

                enrollment = (
                    StudentEnrollment.query
                    .filter(
                        StudentEnrollment.student_id
                        == student.id,

                        StudentEnrollment.academic_year_id
                        == academic_year.id,
                    )
                    .first()
                )

                if enrollment:

                    # --------------------------------------------
                    # Update existing enrollment
                    # --------------------------------------------

                    enrollment.branch_id = (
                        effective_branch_id
                    )

                    enrollment.program_id = (
                        program.id
                    )

                    enrollment.class_id = (
                        class_obj.id
                    )

                    enrollment.section_id = (
                        section.id
                        if section
                        else None
                    )

                    enrollment.enrollment_no = (
                        enrollment_no
                    )

                    enrollment.enrollment_date = (
                        enrollment_date
                    )

                    enrollment.status = (
                        enrollment_status
                    )

                    enrollment.notes = clean(
                        row.get(
                            "Enrollment Notes"
                        )
                    )

                    db.session.flush()

                else:

                    # --------------------------------------------
                    # Check enrollment number
                    # --------------------------------------------

                    enrollment_no_exists = (
                        StudentEnrollment.query
                        .filter(
                            StudentEnrollment
                            .institution_id
                            == institution_id,

                            StudentEnrollment
                            .enrollment_no
                            == enrollment_no,
                        )
                        .first()
                    )

                    if enrollment_no_exists:

                        raise ValueError(
                            f"Enrollment No "
                            f"'{enrollment_no}' "
                            f"already exists."
                        )

                    enrollment = (
                        StudentEnrollment(

                            institution_id=(
                                institution_id
                            ),

                            branch_id=(
                                effective_branch_id
                            ),

                            student_id=(
                                student.id
                            ),

                            academic_year_id=(
                                academic_year.id
                            ),

                            program_id=(
                                program.id
                            ),

                            class_id=(
                                class_obj.id
                            ),

                            section_id=(
                                section.id
                                if section
                                else None
                            ),

                            enrollment_no=(
                                enrollment_no
                            ),

                            enrollment_date=(
                                enrollment_date
                            ),

                            status=(
                                enrollment_status
                            ),

                            notes=clean(
                                row.get(
                                    "Enrollment Notes"
                                )
                            ),
                        )
                    )

                    db.session.add(
                        enrollment
                    )

                    db.session.flush()

                    created_enrollments += 1

                # =================================================
                # CHARGE
                # =================================================

                charge_type = (
                    clean(
                        row.get(
                            "Charge Type"
                        )
                    )
                    or "other"
                ).lower()

                allowed_charge_types = {
                    "registration",
                    "program_fee",
                    "tuition",
                    "exam",
                    "admission",
                    "id_card",
                    "uniform",
                    "books",
                    "transport",
                    "laboratory",
                    "library",
                    "certificate",
                    "other",
                }

                if charge_type not in (
                    allowed_charge_types
                ):

                    raise ValueError(
                        f"Invalid Charge Type "
                        f"'{charge_type}'."
                    )

                charge_name = clean(
                    row.get(
                        "Charge Name"
                    )
                )

                if not charge_name:

                    raise ValueError(
                        "Charge Name is required."
                    )

                amount = decimal_value(
                    row.get("Amount"),
                    "Amount"
                )

                discount = decimal_value(
                    row.get("Discount"),
                    "Discount"
                )

                paid_amount = decimal_value(
                    row.get("Paid Amount"),
                    "Paid Amount"
                )

                if discount > amount:

                    raise ValueError(
                        "Discount cannot be greater "
                        "than Amount."
                    )

                net_amount = (
                    amount - discount
                )

                if paid_amount > net_amount:

                    raise ValueError(
                        "Paid Amount cannot be "
                        "greater than Net Amount."
                    )

                balance = (
                    net_amount - paid_amount
                )

                if balance <= 0:

                    charge_status = "paid"

                elif paid_amount > 0:

                    charge_status = "partial"

                else:

                    charge_status = "unpaid"

                due_date = parse_date(
                    row.get("Due Date"),
                    "Due Date"
                )

                charge = StudentCharge(

                    institution_id=(
                        institution_id
                    ),

                    branch_id=(
                        effective_branch_id
                    ),

                    student_id=(
                        student.id
                    ),

                    enrollment_id=(
                        enrollment.id
                    ),

                    academic_year_id=(
                        academic_year.id
                    ),

                    charge_type=(
                        charge_type
                    ),

                    charge_name=(
                        charge_name
                    ),

                    description=clean(
                        row.get(
                            "Charge Description"
                        )
                    ),

                    amount=amount,

                    discount=discount,

                    net_amount=net_amount,

                    paid_amount=paid_amount,

                    balance=balance,

                    due_date=due_date,

                    status=charge_status,

                    created_by=(
                        current_user_obj.id
                        if getattr(
                            current_user_obj,
                            "id",
                            None
                        )
                        else None
                    ),
                )

                db.session.add(
                    charge
                )

                db.session.flush()

                created_charges += 1

            # ====================================================
            # ROW ERROR
            # ====================================================

            except Exception as row_error:

                errors.append(
                    f"Row {row_number}: "
                    f"{str(row_error)}"
                )

                # ----------------------------------------------
                # Entire import will rollback
                # ----------------------------------------------

                raise

        # ========================================================
        # COMMIT ALL
        # ========================================================

        db.session.commit()

    except Exception as exc:

        db.session.rollback()

        current_app.logger.exception(
            "Student full CSV import failed: %s",
            exc
        )

        # --------------------------------------------------------
        # Show useful row error
        # --------------------------------------------------------

        if errors:

            error_message = errors[0]

        else:

            error_message = str(exc)

        flash(
            "Import failed. No records were saved. "
            + error_message,
            "danger"
        )

        return redirect(
            url_for("main.all_students")
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        "Student import completed successfully. "
        f"Students created: {created_students}, "
        f"students updated: {updated_students}, "
        f"enrollments created: {created_enrollments}, "
        f"charges created: {created_charges}.",
        "success"
    )

    return redirect(
        url_for("main.all_students")
    )



# ============================================================
# EXAM ROLE SECURITY
# ============================================================

EXAM_MANAGE_ROLES = {
    "superadmin",
    "school_admin",
    "branch_admin",
}

EXAM_VIEW_ROLES = {
    "superadmin",
    "school_admin",
    "branch_admin",
    "teacher",
}


def _exam_can_manage():
    """
    Exam create/edit/delete access.
    """

    return getattr(current_user, "role", None) in EXAM_MANAGE_ROLES


def _exam_can_view():
    """
    Exam view access.
    """

    return getattr(current_user, "role", None) in EXAM_VIEW_ROLES


# ============================================================
# EXAM ACCESS FILTER
# ============================================================

def _exam_scope_query(query):
    """
    Restrict exams according to logged-in user's institution/branch.

    superadmin:
        Can see all exams.

    school_admin:
        Can see exams belonging to their institution.

    branch_admin / teacher:
        Can see exams belonging to their branch.
    """

    role = getattr(current_user, "role", None)

    if role == "superadmin":
        return query

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    if role == "school_admin":

        if not institution_id:
            return query.filter(
                db.literal(False)
            )

        return query.filter(
            Exam.institution_id == institution_id
        )

    if role in {
        "branch_admin",
        "teacher",
    }:

        if not institution_id or not branch_id:
            return query.filter(
                db.literal(False)
            )

        return query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    return query.filter(
        db.literal(False)
    )



# ============================================================
# ALL EXAMS
# ============================================================

@bp.route("/exams", methods=["GET"])
@login_required
def all_exams():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:

        flash(
            "You do not have permission to access examinations.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # SCHOOL ADMIN / BRANCH ADMIN MUST HAVE INSTITUTION
    # ========================================================

    if current_role in {
        "school_admin",
        "branch_admin",
    }:

        if not user_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # BRANCH ADMIN MUST HAVE BRANCH
    # ========================================================

    if current_role == "branch_admin":

        if not user_branch_id:

            flash(
                "Your account is not assigned to a branch.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

    # ========================================================
    # REQUEST FILTERS
    # ========================================================

    search = request.args.get(
        "search",
        "",
        type=str
    ).strip()

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    term_id = request.args.get(
        "term_id",
        type=int
    )

    exam_type = request.args.get(
        "exam_type",
        "",
        type=str
    ).strip()

    status = request.args.get(
        "status",
        "",
        type=str
    ).strip()

    # ========================================================
    # PER PAGE
    # ========================================================

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # PAGE
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    if page < 1:
        page = 1

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        Exam.query
        .options(
            db.joinedload(
                Exam.institution
            ),

            db.joinedload(
                Exam.branch
            ),

            db.joinedload(
                Exam.program
            ),

            db.joinedload(
                Exam.assessment_plan
            ),

            db.joinedload(
                Exam.academic_year
            ),

            db.joinedload(
                Exam.term
            ),
        )
    )

    # ========================================================
    # ROLE DATA SCOPE
    # ========================================================

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        if institution_id:

            query = query.filter(
                Exam.institution_id
                == institution_id
            )

        if branch_id:

            query = query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        # NEVER allow another institution
        query = query.filter(
            Exam.institution_id
            == user_institution_id
        )

        # If branch selected, it must belong
        # to this institution.
        if branch_id:

            valid_branch = (
                Branch.query
                .filter(
                    Branch.id == branch_id,
                    Branch.institution_id
                    == user_institution_id
                )
                .first()
            )

            if not valid_branch:

                flash(
                    "You do not have permission to access this branch.",
                    "danger"
                )

                return redirect(
                    url_for("main.all_exams")
                )

            query = query.filter(
                Exam.branch_id == branch_id
            )

        institution_id = user_institution_id

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        # Branch admin is locked to:
        #
        # institution_id = current user's institution
        # branch_id      = current user's branch

        query = query.filter(
            Exam.institution_id
            == user_institution_id,

            Exam.branch_id
            == user_branch_id
        )

        # Ignore manipulated URL values.
        institution_id = user_institution_id
        branch_id = user_branch_id

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_pattern = f"%{search}%"

        query = query.filter(
            db.or_(
                Exam.name.ilike(
                    search_pattern
                ),

                Exam.code.ilike(
                    search_pattern
                ),

                Exam.description.ilike(
                    search_pattern
                ),
            )
        )

    # ========================================================
    # PROGRAM FILTER
    # ========================================================

    if program_id:

        program_query = (
            Program.query
            .filter(
                Program.id == program_id
            )
        )

        # Non-superadmin cannot use
        # another institution's program.

        if current_role != "superadmin":

            program_query = program_query.filter(
                Program.institution_id
                == user_institution_id
            )

        elif institution_id:

            program_query = program_query.filter(
                Program.institution_id
                == institution_id
            )

        valid_program = (
            program_query.first()
        )

        if valid_program:

            query = query.filter(
                Exam.program_id
                == program_id
            )

        else:

            # Invalid program for this user's scope
            query = query.filter(
                db.false()
            )

    # ========================================================
    # ACADEMIC YEAR FILTER
    # ========================================================

    if academic_year_id:

        academic_year_query = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
        )

        if current_role != "superadmin":

            academic_year_query = (
                academic_year_query
                .filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        elif institution_id:

            academic_year_query = (
                academic_year_query
                .filter(
                    AcademicYear.institution_id
                    == institution_id
                )
            )

        valid_academic_year = (
            academic_year_query.first()
        )

        if valid_academic_year:

            query = query.filter(
                Exam.academic_year_id
                == academic_year_id
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # TERM FILTER
    # ========================================================

    if term_id:

        term_query = (
            Term.query
            .filter(
                Term.id == term_id
            )
        )

        if current_role != "superadmin":

            term_query = term_query.filter(
                Term.institution_id
                == user_institution_id
            )

        elif institution_id:

            term_query = term_query.filter(
                Term.institution_id
                == institution_id
            )

        if academic_year_id:

            term_query = term_query.filter(
                Term.academic_year_id
                == academic_year_id
            )

        valid_term = (
            term_query.first()
        )

        if valid_term:

            query = query.filter(
                Exam.term_id == term_id
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # EXAM TYPE
    # ========================================================

    allowed_exam_types = {
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    if exam_type:

        if exam_type in allowed_exam_types:

            query = query.filter(
                Exam.exam_type
                == exam_type
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    if status:

        if status in allowed_statuses:

            query = query.filter(
                Exam.status == status
            )

        else:

            query = query.filter(
                db.false()
            )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        Exam.start_date.asc().nullslast(),
        Exam.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    exams = pagination.items

    # ========================================================
    # INSTITUTIONS DROPDOWN
    # ========================================================

    if current_role == "superadmin":

        institutions = (
            Institution.query
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    else:

        institutions = (
            Institution.query
            .filter(
                Institution.id
                == user_institution_id
            )
            .order_by(
                Institution.name.asc()
            )
            .all()
        )

    # ========================================================
    # BRANCHES DROPDOWN
    # ========================================================

    if current_role == "superadmin":

        branch_query = Branch.query

        if institution_id:

            branch_query = (
                branch_query
                .filter(
                    Branch.institution_id
                    == institution_id
                )
            )

    elif current_role == "school_admin":

        branch_query = (
            Branch.query
            .filter(
                Branch.institution_id
                == user_institution_id
            )
        )

    else:

        # branch_admin sees ONLY own branch
        branch_query = (
            Branch.query
            .filter(
                Branch.id
                == user_branch_id,

                Branch.institution_id
                == user_institution_id
            )
        )

    branches = (
        branch_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    # ========================================================
    # PROGRAMS DROPDOWN
    # ========================================================

    program_query = Program.query

    if current_role != "superadmin":

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        program_query = (
            program_query
            .filter(
                Program.institution_id
                == institution_id
            )
        )

    programs = (
        program_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    # ========================================================
    # ACADEMIC YEARS DROPDOWN
    # ========================================================

    academic_year_query = (
        AcademicYear.query
    )

    if current_role != "superadmin":

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        academic_year_query = (
            academic_year_query
            .filter(
                AcademicYear.institution_id
                == institution_id
            )
        )

    academic_years = (
        academic_year_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    # ========================================================
    # TERMS DROPDOWN
    # ========================================================

    term_query = Term.query

    if current_role != "superadmin":

        term_query = (
            term_query
            .filter(
                Term.institution_id
                == user_institution_id
            )
        )

    elif institution_id:

        term_query = (
            term_query
            .filter(
                Term.institution_id
                == institution_id
            )
        )

    if academic_year_id:

        term_query = (
            term_query
            .filter(
                Term.academic_year_id
                == academic_year_id
            )
        )

    terms = (
        term_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # STATUS COUNTS
    #
    # Counts are based on USER'S DATA SCOPE,
    # not on arbitrary URL filters.
    # ========================================================

    count_query = Exam.query

    # --------------------------------------------------------
    # SUPERADMIN COUNT SCOPE
    # --------------------------------------------------------

    if current_role == "superadmin":

        if institution_id:

            count_query = count_query.filter(
                Exam.institution_id
                == institution_id
            )

        if branch_id:

            count_query = count_query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # SCHOOL ADMIN COUNT SCOPE
    # --------------------------------------------------------

    elif current_role == "school_admin":

        count_query = count_query.filter(
            Exam.institution_id
            == user_institution_id
        )

        if branch_id:

            count_query = count_query.filter(
                Exam.branch_id
                == branch_id
            )

    # --------------------------------------------------------
    # BRANCH ADMIN COUNT SCOPE
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        count_query = count_query.filter(
            Exam.institution_id
            == user_institution_id,

            Exam.branch_id
            == user_branch_id
        )

    # ========================================================
    # COUNTS
    # ========================================================

    total_count = (
        count_query
        .count()
    )

    draft_count = (
        count_query
        .filter(
            Exam.status == "draft"
        )
        .count()
    )

    scheduled_count = (
        count_query
        .filter(
            Exam.status == "scheduled"
        )
        .count()
    )

    ongoing_count = (
        count_query
        .filter(
            Exam.status == "ongoing"
        )
        .count()
    )

    completed_count = (
        count_query
        .filter(
            Exam.status == "completed"
        )
        .count()
    )

    published_count = (
        count_query
        .filter(
            Exam.status == "published"
        )
        .count()
    )

    cancelled_count = (
        count_query
        .filter(
            Exam.status == "cancelled"
        )
        .count()
    )

    # ========================================================
    # EXAM TYPES
    # ========================================================

    exam_types = [
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    ]

    # ========================================================
    # STATUSES
    # ========================================================

    statuses = [
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    ]

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "backend/pages/exams/all_exams.html",

        # ----------------------------------------------------
        # DATA
        # ----------------------------------------------------

        exams=exams,
        pagination=pagination,

        # ----------------------------------------------------
        # CURRENT ROLE
        # ----------------------------------------------------

        current_role=current_role,
        user=current_user,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        institution_id=(
            institution_id
        ),

        branch_id=(
            branch_id
        ),

        program_id=(
            program_id
        ),

        academic_year_id=(
            academic_year_id
        ),

        term_id=(
            term_id
        ),

        exam_type=(
            exam_type
        ),

        status=(
            status
        ),

        per_page=(
            per_page
        ),

        # ----------------------------------------------------
        # DROPDOWNS
        # ----------------------------------------------------

        institutions=institutions,

        branches=branches,

        programs=programs,

        academic_years=academic_years,

        terms=terms,

        # ----------------------------------------------------
        # OPTIONS
        # ----------------------------------------------------

        exam_types=exam_types,

        statuses=statuses,

        # ----------------------------------------------------
        # STATISTICS
        # ----------------------------------------------------

        total_count=total_count,

        draft_count=draft_count,

        scheduled_count=scheduled_count,

        ongoing_count=ongoing_count,

        completed_count=completed_count,

        published_count=published_count,

        cancelled_count=cancelled_count,
    )




# ============================================================
# ADD EXAM
# ============================================================
# ============================================================
# ADD EXAM
# ============================================================

@bp.route(
    "/exams/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # ROLE / USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # EXAM TYPE
    # ========================================================

    allowed_exam_types = {
        "term",
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    # ========================================================
    # EXAM STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    # ========================================================
    # GET DATA FOR FORM
    # ========================================================

    institutions_query = Institution.query

    branches_query = Branch.query

    programs_query = Program.query

    assessment_plans_query = AssessmentPlan.query

    academic_years_query = AcademicYear.query

    terms_query = Term.query

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if current_role != "superadmin":

        if not user_institution_id:
            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        institutions_query = institutions_query.filter(
            Institution.id == user_institution_id
        )

        branches_query = branches_query.filter(
            Branch.institution_id == user_institution_id
        )

        programs_query = programs_query.filter(
            Program.institution_id == user_institution_id
        )

        # ----------------------------------------------------
        # Assessment Plans
        # ----------------------------------------------------

        if hasattr(
            AssessmentPlan,
            "institution_id"
        ):
            assessment_plans_query = (
                assessment_plans_query.filter(
                    AssessmentPlan.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # Academic Years
        # ----------------------------------------------------

        if hasattr(
            AcademicYear,
            "institution_id"
        ):
            academic_years_query = (
                academic_years_query.filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # Branch Admin
        # ----------------------------------------------------

        if (
            current_role == "branch_admin"
            and user_branch_id
        ):

            branches_query = branches_query.filter(
                Branch.id == user_branch_id
            )

            # Programs may either have:
            #
            # 1. branch_id = current branch
            # 2. branch_id = NULL
            #
            # NULL means the program can be used
            # in multiple branches.

            programs_query = programs_query.filter(
                db.or_(
                    Program.branch_id == user_branch_id,
                    Program.branch_id.is_(None)
                )
            )

    # ========================================================
    # EXECUTE GET QUERIES
    # ========================================================

    institutions = (
        institutions_query
        .order_by(Institution.name.asc())
        .all()
    )

    branches = (
        branches_query
        .order_by(Branch.name.asc())
        .all()
    )

    programs = (
        programs_query
        .order_by(Program.name.asc())
        .all()
    )

    assessment_plans = (
        assessment_plans_query
        .order_by(AssessmentPlan.name.asc())
        .all()
    )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    terms = (
        terms_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # GET FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        # ----------------------------------------------------
        # OPTIONAL ASSESSMENT PLAN
        # ----------------------------------------------------

        assessment_plan_id = request.form.get(
            "assessment_plan_id",
            type=int
        )

        # Empty string should become None
        if not assessment_plan_id:
            assessment_plan_id = None

        # ----------------------------------------------------
        # ACADEMIC YEAR
        # ----------------------------------------------------

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        # ----------------------------------------------------
        # TERM
        # ----------------------------------------------------

        term_id = request.form.get(
            "term_id",
            type=int
        )

        # ----------------------------------------------------
        # EXAM INFORMATION
        # ----------------------------------------------------

        name = (
            request.form.get("name", "")
            .strip()
        )

        code = (
            request.form.get("code", "")
            .strip()
            .upper()
        )

        exam_type = (
            request.form.get(
                "exam_type",
                "term"
            )
            .strip()
            .lower()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        # ----------------------------------------------------
        # DATES
        # ----------------------------------------------------

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
        )

        # ----------------------------------------------------
        # STATUS
        # ----------------------------------------------------

        status = (
            request.form.get(
                "status",
                "draft"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        if not institution_id:
            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not branch_id:
            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not program_id:
            flash(
                "Please select a program.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not academic_year_id:
            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        if not name:
            flash(
                "Exam name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # EXAM TYPE VALIDATION
        # ====================================================

        if exam_type not in allowed_exam_types:

            flash(
                "Invalid exam type selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # STATUS VALIDATION
        # ====================================================

        if status not in allowed_statuses:

            flash(
                "Invalid exam status selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GET INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # USER INSTITUTION SECURITY
        # ====================================================

        if (
            current_role != "superadmin"
            and institution.id != user_institution_id
        ):

            abort(403)

        # ====================================================
        # GET BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution.id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # BRANCH ADMIN SECURITY
        # ====================================================

        if (
            current_role == "branch_admin"
            and user_branch_id
            and branch.id != user_branch_id
        ):

            abort(403)

        # ====================================================
        # GET PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if program.institution_id != institution.id:

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # PROGRAM → BRANCH
        #
        # branch_id = NULL means multi-branch program
        # ====================================================

        if (
            getattr(program, "branch_id", None)
            and program.branch_id != branch.id
        ):

            flash(
                "Selected program is not available in this branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GET ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution.id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        # ====================================================
        # OPTIONAL TERM VALIDATION
        # ====================================================

        term = None

        if term_id:

            term = (
                Term.query
                .filter(
                    Term.id == term_id
                )
                .first()
            )

            if not term:

                flash(
                    "Selected term was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

            # ------------------------------------------------
            # TERM → ACADEMIC YEAR
            # ------------------------------------------------

            if hasattr(
                Term,
                "academic_year_id"
            ):

                if (
                    term.academic_year_id
                    != academic_year.id
                ):

                    flash(
                        "Selected term does not belong to the selected academic year.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # OPTIONAL ASSESSMENT PLAN
        # ====================================================

        assessment_plan = None

        if assessment_plan_id:

            assessment_plan = (
                AssessmentPlan.query
                .filter(
                    AssessmentPlan.id
                    == assessment_plan_id
                )
                .first()
            )

            if not assessment_plan:

                flash(
                    "Selected assessment plan was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

            # ------------------------------------------------
            # ASSESSMENT PLAN → INSTITUTION
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "institution_id"
            ):

                if (
                    assessment_plan.institution_id
                    != institution.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected institution.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

            # ------------------------------------------------
            # ASSESSMENT PLAN → PROGRAM
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "program_id"
            ):

                if (
                    assessment_plan.program_id
                    != program.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected program.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:
                parsed_start_date = datetime.strptime(
                    start_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                flash(
                    "Invalid start date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        if end_date:

            try:
                parsed_end_date = datetime.strptime(
                    end_date,
                    "%Y-%m-%d"
                ).date()

            except ValueError:

                flash(
                    "Invalid end date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/add_exam.html",
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            flash(
                "End date cannot be earlier than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # GENERATE CODE IF EMPTY
        # ====================================================

        if not code:

            # ------------------------------------------------
            # PROGRAM CODE
            # ------------------------------------------------

            program_code = (
                getattr(
                    program,
                    "code",
                    None
                )
                or getattr(
                    program,
                    "short_name",
                    None
                )
                or getattr(
                    program,
                    "name",
                    "PRG"
                )
            )

            # ------------------------------------------------
            # ACADEMIC YEAR CODE
            # ------------------------------------------------

            year_code = (
                getattr(
                    academic_year,
                    "name",
                    None
                )
                or getattr(
                    academic_year,
                    "code",
                    None
                )
                or getattr(
                    academic_year,
                    "academic_year",
                    None
                )
                or str(
                    academic_year.id
                )
            )

            # ------------------------------------------------
            # EXAM TYPE CODE
            # ------------------------------------------------

            exam_type_codes = {
                "term": "TERM",
                "monthly": "MON",
                "bi_monthly": "BIM",
                "quarterly": "QTR",
                "semester": "SEM",
                "midterm": "MID",
                "final": "FIN",
                "annual": "ANN",
                "mock": "MOCK",
                "entrance": "ENT",
                "supplementary": "SUP",
                "resit": "RES",
                "special": "SPC",
            }

            type_code = exam_type_codes.get(
                exam_type,
                exam_type.upper()[:5]
            )

            # ------------------------------------------------
            # CLEAN CODE
            # ------------------------------------------------

            import re

            program_code = re.sub(
                r"[^A-Z0-9]+",
                "-",
                str(
                    program_code
                ).upper()
            ).strip("-")

            if not program_code:
                program_code = "PRG"

            program_code = program_code[:12]

            year_code = re.sub(
                r"[^A-Z0-9]+",
                "-",
                str(
                    year_code
                ).upper()
            ).strip("-")

            if not year_code:
                year_code = str(
                    academic_year.id
                )

            # ------------------------------------------------
            # BASE CODE
            # ------------------------------------------------

            base_code = (
                f"{program_code}-"
                f"{type_code}-"
                f"{year_code}"
            )

            # ------------------------------------------------
            # UNIQUE SEQUENCE
            # ------------------------------------------------

            sequence = 1

            while True:

                generated_code = (
                    f"{base_code}-"
                    f"{sequence:03d}"
                )

                existing_exam = (
                    Exam.query
                    .filter(
                        Exam.code
                        == generated_code
                    )
                    .first()
                )

                if not existing_exam:
                    code = generated_code
                    break

                sequence += 1

                if sequence > 9999:

                    flash(
                        "Unable to generate a unique exam code.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/add_exam.html",
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                    )

        # ====================================================
        # CODE DUPLICATE CHECK
        # ====================================================

        existing_code = (
            Exam.query
            .filter(
                db.func.upper(
                    Exam.code
                ) == code.upper()
            )
            .first()
        )

        if existing_code:

            flash(
                f"Exam code '{code}' already exists.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

        # ====================================================
        # CREATE EXAM
        # ====================================================

        exam = Exam(
            institution_id=institution.id,
            branch_id=branch.id,
            program_id=program.id,

            # Optional
            assessment_plan_id=(
                assessment_plan.id
                if assessment_plan
                else None
            ),

            academic_year_id=academic_year.id,

            # Optional
            term_id=(
                term.id
                if term
                else None
            ),

            name=name,
            code=code,
            exam_type=exam_type,
            description=(
                description
                if description
                else None
            ),

            start_date=parsed_start_date,
            end_date=parsed_end_date,

            status=status,
        )

        # ====================================================
        # OPTIONAL USER CREATOR
        # ====================================================
        #
        # Only enable this section if Exam model has
        # created_by / created_by_id.
        #
        # Example:
        #
        # exam.created_by = current_user.id
        #
        # ====================================================

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(exam)

            db.session.commit()

            flash(
                f"Exam '{exam.name}' was created successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_exams"
                )
            )

        except Exception as e:

            db.session.rollback()

            current_app.logger.exception(
                "Error while creating exam"
            )

            flash(
                "An error occurred while creating the exam. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/add_exam.html",
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/exams/add_exam.html",

        # ----------------------------------------------
        # ORGANIZATION
        # ----------------------------------------------

        institutions=institutions,
        branches=branches,
        programs=programs,

        # ----------------------------------------------
        # OPTIONAL ASSESSMENT PLANS
        # ----------------------------------------------

        assessment_plans=assessment_plans,

        # ----------------------------------------------
        # ACADEMIC PERIOD
        # ----------------------------------------------

        academic_years=academic_years,
        terms=terms,

        # ----------------------------------------------
        # EXTRA
        # ----------------------------------------------

        allowed_exam_types=allowed_exam_types,
        allowed_statuses=allowed_statuses,
        user=current_user
    )




# ============================================================
# GENERATE EXAM CODE
# ============================================================

@bp.route(
    "/exams/generate-code",
    methods=["GET"]
)
@login_required
def generate_exam_code():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # GET REQUEST PARAMETERS
    # ========================================================

    institution_id = request.args.get(
        "institution_id",
        type=int
    )

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    program_id = request.args.get(
        "program_id",
        type=int
    )

    academic_year_id = request.args.get(
        "academic_year_id",
        type=int
    )

    exam_type = (
        request.args.get(
            "exam_type",
            "term"
        )
        .strip()
        .lower()
    )

    # ========================================================
    # REQUIRED DATA
    # ========================================================

    if not institution_id:
        return {
            "success": False,
            "message": "Institution is required."
        }, 400

    if not branch_id:
        return {
            "success": False,
            "message": "Branch is required."
        }, 400

    if not program_id:
        return {
            "success": False,
            "message": "Program is required."
        }, 400

    if not academic_year_id:
        return {
            "success": False,
            "message": "Academic year is required."
        }, 400

    # ========================================================
    # INSTITUTION
    # ========================================================

    institution = (
        Institution.query
        .filter_by(
            id=institution_id
        )
        .first()
    )

    if not institution:
        return {
            "success": False,
            "message": "Institution not found."
        }, 404

    # ========================================================
    # BRANCH
    # ========================================================

    branch = (
        Branch.query
        .filter_by(
            id=branch_id
        )
        .first()
    )

    if not branch:
        return {
            "success": False,
            "message": "Branch not found."
        }, 404

    # Branch must belong to institution
    if branch.institution_id != institution.id:
        return {
            "success": False,
            "message": "Selected branch does not belong to the selected institution."
        }, 400

    # ========================================================
    # PROGRAM
    # ========================================================

    program = (
        Program.query
        .filter_by(
            id=program_id
        )
        .first()
    )

    if not program:
        return {
            "success": False,
            "message": "Program not found."
        }, 404

    # Program must belong to institution
    if program.institution_id != institution.id:
        return {
            "success": False,
            "message": "Selected program does not belong to the selected institution."
        }, 400

    # ========================================================
    # PROGRAM BRANCH VALIDATION
    # ========================================================

    # Program.branch_id can be NULL because
    # the program may be available to multiple branches.

    if (
        getattr(program, "branch_id", None)
        and program.branch_id != branch.id
    ):
        return {
            "success": False,
            "message": "Selected program is not available in this branch."
        }, 400

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    academic_year = (
        AcademicYear.query
        .filter_by(
            id=academic_year_id
        )
        .first()
    )

    if not academic_year:
        return {
            "success": False,
            "message": "Academic year not found."
        }, 404

    # ========================================================
    # YEAR CODE
    # ========================================================

    year_code = None

    # Try common academic-year fields
    if hasattr(academic_year, "name"):
        year_code = academic_year.name

    elif hasattr(academic_year, "code"):
        year_code = academic_year.code

    elif hasattr(academic_year, "academic_year"):
        year_code = academic_year.academic_year

    else:
        year_code = str(academic_year_id)

    # Clean year
    year_code = str(
        year_code
    ).strip().upper()

    # ========================================================
    # PROGRAM CODE
    # ========================================================

    program_code = getattr(
        program,
        "code",
        None
    )

    if not program_code:
        program_code = getattr(
            program,
            "short_name",
            None
        )

    if not program_code:
        program_code = getattr(
            program,
            "name",
            "PRG"
        )

    # ========================================================
    # EXAM TYPE CODE
    # ========================================================

    exam_type_codes = {

        "term": "TERM",

        "monthly": "MON",

        "bi_monthly": "BIM",

        "quarterly": "QTR",

        "semester": "SEM",

        "midterm": "MID",

        "final": "FIN",

        "annual": "ANN",

        "mock": "MOCK",

        "entrance": "ENT",

        "supplementary": "SUP",

        "resit": "RES",

        "special": "SPC",

    }

    type_code = exam_type_codes.get(
        exam_type,
        exam_type.upper()[:5]
    )

    # ========================================================
    # CLEAN PROGRAM CODE
    # ========================================================

    import re

    program_code = re.sub(
        r"[^A-Z0-9]+",
        "-",
        str(program_code).upper()
    ).strip("-")

    if not program_code:
        program_code = "PRG"

    # Keep code manageable
    program_code = program_code[:12]

    # ========================================================
    # CLEAN YEAR CODE
    # ========================================================

    year_code = re.sub(
        r"[^A-Z0-9]+",
        "-",
        year_code
    ).strip("-")

    if not year_code:
        year_code = str(
            getattr(
                academic_year,
                "id",
                academic_year_id
            )
        )

    # ========================================================
    # BASE CODE
    # ========================================================

    base_code = (
        f"{program_code}-"
        f"{type_code}-"
        f"{year_code}"
    )

    # ========================================================
    # FIND NEXT NUMBER
    # ========================================================

    sequence = 1

    while True:

        generated_code = (
            f"{base_code}-"
            f"{sequence:03d}"
        )

        # ====================================================
        # CHECK DUPLICATE
        # ====================================================

        existing_exam = (
            Exam.query
            .filter(
                Exam.code == generated_code
            )
            .first()
        )

        if not existing_exam:
            break

        sequence += 1

        # Safety protection
        if sequence > 9999:

            return {
                "success": False,
                "message": "Unable to generate a unique exam code."
            }, 500

    # ========================================================
    # RETURN JSON
    # ========================================================

    return {
        "success": True,
        "code": generated_code
    }, 200



# ============================================================
# VIEW EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>",
    methods=["GET"]
)
@login_required
def view_exam(exam_id):

    if not _exam_can_view():
        abort(403)

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    return render_template(
        "backend/pages/exams/view_exam.html",
        exam=exam,
    )


