# EDIT EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam(exam_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # USER SCOPE
    # ========================================================

    user_institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    user_branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # GET EXAM
    # ========================================================

    exam = (
        Exam.query
        .filter(
            Exam.id == exam_id
        )
        .first()
    )

    if not exam:
        flash(
            "Exam not found.",
            "danger"
        )

        return redirect(
            url_for("main.all_exams")
        )

    # ========================================================
    # EXAM INSTITUTION SECURITY
    # ========================================================

    if (
        current_role != "superadmin"
        and user_institution_id
        and exam.institution_id
        != user_institution_id
    ):
        abort(403)

    # ========================================================
    # BRANCH ADMIN SECURITY
    # ========================================================

    if (
        current_role == "branch_admin"
        and user_branch_id
        and exam.branch_id != user_branch_id
    ):
        abort(403)

    # ========================================================
    # ALLOWED EXAM TYPES
    # ========================================================

    allowed_exam_types = {
        "term",
        "monthly",
        "bi_monthly",
        "quarterly",
        "semester",
        "midterm",
        "final",
        "annual",
        "mock",
        "entrance",
        "supplementary",
        "resit",
        "special",
    }

    # ========================================================
    # ALLOWED STATUS
    # ========================================================

    allowed_statuses = {
        "draft",
        "scheduled",
        "ongoing",
        "completed",
        "cancelled",
        "published",
    }

    # ========================================================
    # FORM DATA
    # ========================================================

    institutions_query = Institution.query
    branches_query = Branch.query
    programs_query = Program.query
    assessment_plans_query = AssessmentPlan.query
    academic_years_query = AcademicYear.query
    terms_query = Term.query

    # ========================================================
    # USER SCOPE
    # ========================================================

    if current_role != "superadmin":

        if not user_institution_id:

            flash(
                "Your account is not assigned to an institution.",
                "danger"
            )

            return redirect(
                url_for("main.dashboard")
            )

        # ----------------------------------------------------
        # INSTITUTIONS
        # ----------------------------------------------------

        institutions_query = (
            institutions_query.filter(
                Institution.id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # BRANCHES
        # ----------------------------------------------------

        branches_query = (
            branches_query.filter(
                Branch.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # PROGRAMS
        # ----------------------------------------------------

        programs_query = (
            programs_query.filter(
                Program.institution_id
                == user_institution_id
            )
        )

        # ----------------------------------------------------
        # ASSESSMENT PLANS
        # ----------------------------------------------------

        if hasattr(
            AssessmentPlan,
            "institution_id"
        ):

            assessment_plans_query = (
                assessment_plans_query.filter(
                    AssessmentPlan.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # ACADEMIC YEARS
        # ----------------------------------------------------

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            academic_years_query = (
                academic_years_query.filter(
                    AcademicYear.institution_id
                    == user_institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        if (
            current_role == "branch_admin"
            and user_branch_id
        ):

            branches_query = (
                branches_query.filter(
                    Branch.id
                    == user_branch_id
                )
            )

            programs_query = (
                programs_query.filter(
                    or_(
                        Program.branch_id
                        == user_branch_id,

                        Program.branch_id.is_(None)
                    )
                )
            )

    # ========================================================
    # EXECUTE QUERIES
    # ========================================================

    institutions = (
        institutions_query
        .order_by(
            Institution.name.asc()
        )
        .all()
    )

    branches = (
        branches_query
        .order_by(
            Branch.name.asc()
        )
        .all()
    )

    programs = (
        programs_query
        .order_by(
            Program.name.asc()
        )
        .all()
    )

    assessment_plans = (
        assessment_plans_query
        .order_by(
            AssessmentPlan.name.asc()
        )
        .all()
    )

    academic_years = (
        academic_years_query
        .order_by(
            AcademicYear.id.desc()
        )
        .all()
    )

    terms = (
        terms_query
        .order_by(
            Term.id.desc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # FORM VALUES
        # ====================================================

        institution_id = request.form.get(
            "institution_id",
            type=int
        )

        branch_id = request.form.get(
            "branch_id",
            type=int
        )

        program_id = request.form.get(
            "program_id",
            type=int
        )

        assessment_plan_id = request.form.get(
            "assessment_plan_id",
            type=int
        )

        if not assessment_plan_id:
            assessment_plan_id = None

        academic_year_id = request.form.get(
            "academic_year_id",
            type=int
        )

        term_id = request.form.get(
            "term_id",
            type=int
        )

        if not term_id:
            term_id = None

        name = (
            request.form.get(
                "name",
                ""
            )
            .strip()
        )

        code = (
            request.form.get(
                "code",
                ""
            )
            .strip()
            .upper()
        )

        exam_type = (
            request.form.get(
                "exam_type",
                "term"
            )
            .strip()
            .lower()
        )

        description = (
            request.form.get(
                "description",
                ""
            )
            .strip()
        )

        start_date = (
            request.form.get(
                "start_date",
                ""
            )
            .strip()
        )

        end_date = (
            request.form.get(
                "end_date",
                ""
            )
            .strip()
        )

        status = (
            request.form.get(
                "status",
                "draft"
            )
            .strip()
            .lower()
        )

        # ====================================================
        # BASIC VALIDATION
        # ====================================================

        if not institution_id:

            flash(
                "Please select an institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not branch_id:

            flash(
                "Please select a branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not program_id:

            flash(
                "Please select a program.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not academic_year_id:

            flash(
                "Please select an academic year.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        if not name:

            flash(
                "Exam name is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # EXAM TYPE
        # ====================================================

        if exam_type not in allowed_exam_types:

            flash(
                "Invalid exam type selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # STATUS
        # ====================================================

        if status not in allowed_statuses:

            flash(
                "Invalid exam status selected.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION
        # ====================================================

        institution = (
            Institution.query
            .filter(
                Institution.id
                == institution_id
            )
            .first()
        )

        if not institution:

            flash(
                "Selected institution was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # INSTITUTION SCOPE
        # ====================================================

        if (
            current_role != "superadmin"
            and institution.id
            != user_institution_id
        ):
            abort(403)

        # ====================================================
        # BRANCH
        # ====================================================

        branch = (
            Branch.query
            .filter(
                Branch.id == branch_id
            )
            .first()
        )

        if not branch:

            flash(
                "Selected branch was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH → INSTITUTION
        # ====================================================

        if branch.institution_id != institution.id:

            flash(
                "Selected branch does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # BRANCH ADMIN SCOPE
        # ====================================================

        if (
            current_role == "branch_admin"
            and user_branch_id
            and branch.id != user_branch_id
        ):
            abort(403)

        # ====================================================
        # PROGRAM
        # ====================================================

        program = (
            Program.query
            .filter(
                Program.id == program_id
            )
            .first()
        )

        if not program:

            flash(
                "Selected program was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → INSTITUTION
        # ====================================================

        if program.institution_id != institution.id:

            flash(
                "Selected program does not belong to the selected institution.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # PROGRAM → BRANCH
        #
        # NULL = available to multiple branches
        # ====================================================

        if (
            getattr(
                program,
                "branch_id",
                None
            )
            and program.branch_id
            != branch.id
        ):

            flash(
                "Selected program is not available in this branch.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR
        # ====================================================

        academic_year = (
            AcademicYear.query
            .filter(
                AcademicYear.id
                == academic_year_id
            )
            .first()
        )

        if not academic_year:

            flash(
                "Selected academic year was not found.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # ACADEMIC YEAR → INSTITUTION
        # ====================================================

        if hasattr(
            AcademicYear,
            "institution_id"
        ):

            if (
                academic_year.institution_id
                != institution.id
            ):

                flash(
                    "Selected academic year does not belong to the selected institution.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        # ====================================================
        # TERM - OPTIONAL
        # ====================================================

        term = None

        if term_id:

            term = (
                Term.query
                .filter(
                    Term.id == term_id
                )
                .first()
            )

            if not term:

                flash(
                    "Selected term was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # TERM → ACADEMIC YEAR
            # ------------------------------------------------

            if hasattr(
                Term,
                "academic_year_id"
            ):

                if (
                    term.academic_year_id
                    != academic_year.id
                ):

                    flash(
                        "Selected term does not belong to the selected academic year.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # ASSESSMENT PLAN - OPTIONAL
        # ====================================================

        assessment_plan = None

        if assessment_plan_id:

            assessment_plan = (
                AssessmentPlan.query
                .filter(
                    AssessmentPlan.id
                    == assessment_plan_id
                )
                .first()
            )

            if not assessment_plan:

                flash(
                    "Selected assessment plan was not found.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

            # ------------------------------------------------
            # PLAN → INSTITUTION
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "institution_id"
            ):

                if (
                    assessment_plan.institution_id
                    != institution.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected institution.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

            # ------------------------------------------------
            # PLAN → PROGRAM
            # ------------------------------------------------

            if hasattr(
                AssessmentPlan,
                "program_id"
            ):

                if (
                    assessment_plan.program_id
                    != program.id
                ):

                    flash(
                        "Selected assessment plan does not belong to the selected program.",
                        "danger"
                    )

                    return render_template(
                        "backend/pages/exams/edit_exam.html",
                        exam=exam,
                        institutions=institutions,
                        branches=branches,
                        programs=programs,
                        assessment_plans=assessment_plans,
                        academic_years=academic_years,
                        terms=terms,
                        allowed_exam_types=allowed_exam_types,
                        allowed_statuses=allowed_statuses,
                    )

        # ====================================================
        # DATE VALIDATION
        # ====================================================

        parsed_start_date = None
        parsed_end_date = None

        if start_date:

            try:

                parsed_start_date = (
                    datetime.strptime(
                        start_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid start date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if end_date:

            try:

                parsed_end_date = (
                    datetime.strptime(
                        end_date,
                        "%Y-%m-%d"
                    ).date()
                )

            except ValueError:

                flash(
                    "Invalid end date.",
                    "danger"
                )

                return render_template(
                    "backend/pages/exams/edit_exam.html",
                    exam=exam,
                    institutions=institutions,
                    branches=branches,
                    programs=programs,
                    assessment_plans=assessment_plans,
                    academic_years=academic_years,
                    terms=terms,
                    allowed_exam_types=allowed_exam_types,
                    allowed_statuses=allowed_statuses,
                )

        if (
            parsed_start_date
            and parsed_end_date
            and parsed_end_date < parsed_start_date
        ):

            flash(
                "End date cannot be earlier than start date.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # CODE VALIDATION
        # ====================================================

        if not code:

            flash(
                "Exam code is required.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # DUPLICATE CODE CHECK
        #
        # Ignore current exam itself
        # ====================================================

        duplicate_exam = (
            Exam.query
            .filter(
                db.func.upper(
                    Exam.code
                ) == code.upper(),

                Exam.id != exam.id
            )
            .first()
        )

        if duplicate_exam:

            flash(
                f"Exam code '{code}' is already used by another exam.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

        # ====================================================
        # UPDATE EXAM
        # ====================================================

        exam.institution_id = institution.id

        exam.branch_id = branch.id

        exam.program_id = program.id

        # Optional
        exam.assessment_plan_id = (
            assessment_plan.id
            if assessment_plan
            else None
        )

        exam.academic_year_id = (
            academic_year.id
        )

        # Optional
        exam.term_id = (
            term.id
            if term
            else None
        )

        exam.name = name

        exam.code = code

        exam.exam_type = exam_type

        exam.description = (
            description
            if description
            else None
        )

        exam.start_date = parsed_start_date

        exam.end_date = parsed_end_date

        exam.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

            flash(
                f"Exam '{exam.name}' was updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "main.all_exams"
                )
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                "Error while updating exam"
            )

            flash(
                "An error occurred while updating the exam. Please try again.",
                "danger"
            )

            return render_template(
                "backend/pages/exams/edit_exam.html",
                exam=exam,
                institutions=institutions,
                branches=branches,
                programs=programs,
                assessment_plans=assessment_plans,
                academic_years=academic_years,
                terms=terms,
                allowed_exam_types=allowed_exam_types,
                allowed_statuses=allowed_statuses,
            )

    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "backend/pages/exams/edit_exam.html",

        exam=exam,

        institutions=institutions,

        branches=branches,

        programs=programs,

        assessment_plans=assessment_plans,

        academic_years=academic_years,

        terms=terms,

        allowed_exam_types=allowed_exam_types,

        allowed_statuses=allowed_statuses,
        user=current_user
    )




# ============================================================
# DELETE EXAM
# ============================================================

@bp.route(
    "/exams/<int:exam_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam(exam_id):

    if not _exam_can_manage():
        abort(403)

    # --------------------------------------------------------
    # GET EXAM WITH USER SCOPE
    # --------------------------------------------------------

    query = _exam_scope_query(
        Exam.query
    )

    exam = (
        query
        .filter(
            Exam.id == exam_id
        )
        .first_or_404()
    )

    try:

        db.session.delete(
            exam
        )

        db.session.commit()

        flash(
            "Exam deleted successfully.",
            "success"
        )

    except Exception as e:

        db.session.rollback()

        flash(
            "This exam cannot be deleted because it may already have related examination records.",
            "danger"
        )

    return redirect(
        url_for(
            "main.all_exams"
        )
    )





# ============================================================
# EXAM SUBJECT ROUTES
# ============================================================

# ============================================================
# ROLE PERMISSION
# ============================================================

def _exam_subject_can_manage():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }


# ============================================================
# ROLE PERMISSION - VIEW
# ============================================================

def _exam_subject_can_view():

    role = getattr(
        current_user,
        "role",
        None
    )

    return role in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }


# ============================================================
# HELPER
# CURRENT USER INSTITUTION / BRANCH SCOPE
# ============================================================

def _exam_subject_scope_query(query):

    role = getattr(
        current_user,
        "role",
        None
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if role == "superadmin":
        return query

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    if role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:
            return query.filter(False)

        return query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    # --------------------------------------------------------
    # OTHER ROLES
    # --------------------------------------------------------

    return query.filter(False)


# ============================================================
# ADD EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/add",
    methods=["GET", "POST"]
)
@login_required
def add_exam_subject():

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # EXAM QUERY
    # ========================================================

    exams_query = (
        Exam.query
        .join(
            Program,
            Program.id == Exam.program_id
        )
    )

    # --------------------------------------------------------
    # SUPERADMIN
    # --------------------------------------------------------

    if current_role == "superadmin":

        pass

    # --------------------------------------------------------
    # SCHOOL ADMIN
    # --------------------------------------------------------

    elif current_role == "school_admin":

        if not institution_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    # --------------------------------------------------------
    # BRANCH ADMIN
    # --------------------------------------------------------

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # EXAM
        # ====================================================

        exam_id = request.form.get(
            "exam_id",
            type=int
        )

        if not exam_id:

            flash(
                "Please select an exam.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # LOAD EXAM WITH SECURITY
        # ====================================================

        exam_query = Exam.query.filter(
            Exam.id == exam_id
        )

        if current_role == "school_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id
            )

        elif current_role == "branch_admin":

            exam_query = exam_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

        exam = exam_query.first()

        if not exam:

            flash(
                "The selected exam does not exist or you do not have permission to manage it.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # PROGRAM
        # ====================================================

        if not exam.program_id:

            flash(
                "The selected exam has no program assigned.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        program = (
            Program.query
            .filter(
                Program.id == exam.program_id
            )
            .first()
        )

        if not program:

            flash(
                "The program assigned to this exam was not found.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject"
                )
            )

        # ====================================================
        # SUBJECT IDS
        #
        # Accept BOTH:
        #
        # subject_ids[]
        # subject_id[]
        #
        # This prevents template naming mismatch.
        # ====================================================

        subject_ids = request.form.getlist(
            "subject_ids[]"
        )

        if not subject_ids:

            subject_ids = request.form.getlist(
                "subject_id[]"
            )

        # ====================================================
        # CLASS IDS
        # ====================================================

        class_ids = request.form.getlist(
            "class_ids[]"
        )

        if not class_ids:

            class_ids = request.form.getlist(
                "class_id[]"
            )

        # ====================================================
        # SECTION IDS
        # ====================================================

        section_ids = request.form.getlist(
            "section_ids[]"
        )

        if not section_ids:

            section_ids = request.form.getlist(
                "section_id[]"
            )

        # ====================================================
        # TEACHER IDS
        # ====================================================

        teacher_ids = request.form.getlist(
            "teacher_ids[]"
        )

        if not teacher_ids:

            teacher_ids = request.form.getlist(
                "teacher_id[]"
            )

        # ====================================================
        # MAX MARKS
        # ====================================================

        max_marks_list = request.form.getlist(
            "max_marks[]"
        )

        # ====================================================
        # PASS MARKS
        # ====================================================

        pass_marks_list = request.form.getlist(
            "pass_marks[]"
        )

        # ====================================================
        # WEIGHT
        # ====================================================

        weight_list = request.form.getlist(
            "weight[]"
        )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        display_order_list = request.form.getlist(
            "display_order[]"
        )

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # CHECK SUBJECT ROWS
        # ====================================================

        if not subject_ids:

            flash(
                "Please add at least one subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # ROW COUNT
        # ====================================================

        row_count = len(subject_ids)

        # ====================================================
        # NORMALIZE LIST LENGTHS
        # ========================================================

        def normalize_list(
            values,
            count,
            default_value=""
        ):

            values = list(values)

            if len(values) < count:

                values.extend(
                    [default_value]
                    * (
                        count
                        - len(values)
                    )
                )

            elif len(values) > count:

                values = values[:count]

            return values

        class_ids = normalize_list(
            class_ids,
            row_count,
            ""
        )

        section_ids = normalize_list(
            section_ids,
            row_count,
            ""
        )

        teacher_ids = normalize_list(
            teacher_ids,
            row_count,
            ""
        )

        max_marks_list = normalize_list(
            max_marks_list,
            row_count,
            "100"
        )

        pass_marks_list = normalize_list(
            pass_marks_list,
            row_count,
            "50"
        )

        weight_list = normalize_list(
            weight_list,
            row_count,
            "100"
        )

        display_order_list = normalize_list(
            display_order_list,
            row_count,
            ""
        )

        # ====================================================
        # VALID PROGRAM SUBJECTS
        #
        # Subject must belong to:
        #
        # Exam.program_id
        #
        # AND
        #
        # Exam.institution_id
        # ====================================================

        valid_subject_query = (
            Subject.query
            .filter(
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        #
        # branch_id NULL = shared subject
        # ----------------------------------------------------

        if exam.branch_id:

            valid_subject_query = (
                valid_subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        valid_subjects = (
            valid_subject_query
            .all()
        )

        valid_subject_map = {
            int(subject.id): subject
            for subject in valid_subjects
        }

        # ====================================================
        # VALID PROGRAM CLASSES
        # ====================================================

        valid_classes_query = (
            Class.query
            .filter(
                Class.program_id == exam.program_id,
                Class.institution_id == exam.institution_id
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.branch_id == exam.branch_id
                )
            )

        # ----------------------------------------------------
        # Academic Year
        # ----------------------------------------------------

        if exam.academic_year_id:

            valid_classes_query = (
                valid_classes_query
                .filter(
                    Class.academic_year_id ==
                    exam.academic_year_id
                )
            )

        valid_classes = (
            valid_classes_query
            .all()
        )

        valid_class_map = {
            int(item.id): item
            for item in valid_classes
        }

        # ====================================================
        # VALID SECTIONS
        # ====================================================

        valid_class_ids = list(
            valid_class_map.keys()
        )

        valid_section_map = {}

        if valid_class_ids:

            valid_sections = (
                Section.query
                .filter(
                    Section.class_id.in_(
                        valid_class_ids
                    )
                )
                .all()
            )

            valid_section_map = {
                int(section.id): section
                for section in valid_sections
            }

        # ====================================================
        # VALID TEACHERS
        #
        # Teacher must be assigned through TeacherSubject.
        #
        # Program:
        #
        # Exam
        #   ↓
        # Program
        #   ↓
        # TeacherSubject
        #   ↓
        # Teacher
        # ====================================================

        valid_teacher_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.institution_id ==
                exam.institution_id,

                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.institution_id ==
                exam.institution_id,

                TeacherSubject.program_id ==
                exam.program_id,

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if exam.branch_id:

            valid_teacher_query = (
                valid_teacher_query
                .filter(
                    Teacher.branch_id ==
                    exam.branch_id
                )
                .filter(
                    db.or_(
                        TeacherSubject.branch_id ==
                        exam.branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        valid_teachers = (
            valid_teacher_query
            .distinct()
            .all()
        )

        valid_teacher_map = {
            int(teacher.id): teacher
            for teacher in valid_teachers
        }

        # ====================================================
        # EXISTING EXAM SUBJECTS
        # ====================================================

        existing_rows = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id ==
                exam.id
            )
            .all()
        )

        existing_combinations = set()

        for item in existing_rows:

            existing_combinations.add(
                (
                    int(item.subject_id),

                    int(item.class_id)
                    if item.class_id is not None
                    else None,

                    int(item.section_id)
                    if item.section_id is not None
                    else None
                )
            )

        # ====================================================
        # REQUEST DUPLICATES
        # ====================================================

        request_combinations = set()

        # ====================================================
        # NEW OBJECTS
        # ====================================================

        new_exam_subjects = []

        # ====================================================
        # PROCESS EACH ROW
        # ====================================================

        for index in range(row_count):

            row_number = index + 1

            # ==================================================
            # SUBJECT
            # ==================================================

            raw_subject_id = (
                subject_ids[index]
                if index < len(subject_ids)
                else ""
            )

            raw_subject_id = (
                str(raw_subject_id).strip()
            )

            if not raw_subject_id:

                flash(
                    f"Please select a subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            try:

                subject_id = int(
                    raw_subject_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid subject on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            subject = valid_subject_map.get(
                subject_id
            )

            if not subject:

                flash(
                    f"Subject on row {row_number} does not belong to the selected exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CLASS
            # ==================================================

            raw_class_id = (
                class_ids[index]
                if index < len(class_ids)
                else ""
            )

            raw_class_id = (
                str(raw_class_id).strip()
                if raw_class_id
                else ""
            )

            class_id = None
            selected_class = None

            if raw_class_id:

                try:

                    class_id = int(
                        raw_class_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid class on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                selected_class = (
                    valid_class_map.get(
                        class_id
                    )
                )

                if not selected_class:

                    flash(
                        f"Class on row {row_number} does not belong to the selected exam program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # SECTION
            # ==================================================

            raw_section_id = (
                section_ids[index]
                if index < len(section_ids)
                else ""
            )

            raw_section_id = (
                str(raw_section_id).strip()
                if raw_section_id
                else ""
            )

            section_id = None

            if raw_section_id:

                # ----------------------------------------------
                # Section requires Class
                # ----------------------------------------------

                if not class_id:

                    flash(
                        f"Please select a class before selecting a section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                try:

                    section_id = int(
                        raw_section_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid section on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                section = (
                    valid_section_map.get(
                        section_id
                    )
                )

                if not section:

                    flash(
                        f"Section on row {row_number} is not valid.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                if int(section.class_id) != int(
                    class_id
                ):

                    flash(
                        f"Section on row {row_number} does not belong to the selected class.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # TEACHER
            # ==================================================

            raw_teacher_id = (
                teacher_ids[index]
                if index < len(teacher_ids)
                else ""
            )

            raw_teacher_id = (
                str(raw_teacher_id).strip()
                if raw_teacher_id
                else ""
            )

            teacher_id = None

            if raw_teacher_id:

                try:

                    teacher_id = int(
                        raw_teacher_id
                    )

                except (
                    TypeError,
                    ValueError
                ):

                    flash(
                        f"Invalid teacher on row {row_number}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                teacher = valid_teacher_map.get(
                    teacher_id
                )

                if not teacher:

                    flash(
                        f"Teacher on row {row_number} is not assigned to the selected program.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

                # ----------------------------------------------
                # Verify TeacherSubject
                # Program + Subject
                # ----------------------------------------------

                teacher_assignment_query = (
                    TeacherSubject.query
                    .filter(
                        TeacherSubject.teacher_id ==
                        teacher_id,

                        TeacherSubject.program_id ==
                        exam.program_id,

                        TeacherSubject.subject_id ==
                        subject_id,

                        TeacherSubject.institution_id ==
                        exam.institution_id,

                        TeacherSubject.status ==
                        "active"
                    )
                )

                # ------------------------------------------------
                # Branch assignment
                # ------------------------------------------------

                if exam.branch_id:

                    teacher_assignment_query = (
                        teacher_assignment_query
                        .filter(
                            db.or_(
                                TeacherSubject.branch_id ==
                                exam.branch_id,

                                TeacherSubject.branch_id.is_(None)
                            )
                        )
                    )

                teacher_assignment = (
                    teacher_assignment_query
                    .first()
                )

                # ------------------------------------------------
                # If no subject-specific assignment exists,
                # allow program-level assignment.
                # ------------------------------------------------

                if not teacher_assignment:

                    teacher_assignment_query = (
                        TeacherSubject.query
                        .filter(
                            TeacherSubject.teacher_id ==
                            teacher_id,

                            TeacherSubject.program_id ==
                            exam.program_id,

                            TeacherSubject.institution_id ==
                            exam.institution_id,

                            TeacherSubject.status ==
                            "active",

                            db.or_(
                                TeacherSubject.subject_id.is_(None),
                                TeacherSubject.subject_id ==
                                subject_id
                            )
                        )
                    )

                    if exam.branch_id:

                        teacher_assignment_query = (
                            teacher_assignment_query
                            .filter(
                                db.or_(
                                    TeacherSubject.branch_id ==
                                    exam.branch_id,

                                    TeacherSubject.branch_id.is_(None)
                                )
                            )
                        )

                    teacher_assignment = (
                        teacher_assignment_query
                        .first()
                    )

                if not teacher_assignment:

                    flash(
                        f"{teacher.full_name} is not assigned to {subject.name}.",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.add_exam_subject",
                            exam_id=exam.id
                        )
                    )

            # ==================================================
            # MAX MARKS
            # ==================================================

            raw_max_marks = (
                max_marks_list[index]
                if index < len(max_marks_list)
                else "100"
            )

            try:

                max_marks = float(
                    raw_max_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if max_marks <= 0:

                flash(
                    f"Maximum marks must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # PASS MARKS
            # ==================================================

            raw_pass_marks = (
                pass_marks_list[index]
                if index < len(pass_marks_list)
                else "50"
            )

            try:

                pass_marks = float(
                    raw_pass_marks
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid pass marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks < 0:

                flash(
                    f"Pass marks cannot be negative on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if pass_marks > max_marks:

                flash(
                    f"Pass marks cannot exceed maximum marks on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # WEIGHT
            # ==================================================

            raw_weight = (
                weight_list[index]
                if index < len(weight_list)
                else "100"
            )

            try:

                weight = float(
                    raw_weight
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    f"Invalid weight on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            if weight <= 0:

                flash(
                    f"Weight must be greater than zero on row {row_number}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # DISPLAY ORDER
            # ==================================================

            raw_display_order = (
                display_order_list[index]
                if index < len(display_order_list)
                else ""
            )

            try:

                display_order = int(
                    raw_display_order
                )

            except (
                TypeError,
                ValueError
            ):

                display_order = (
                    index + 1
                )

            if display_order <= 0:

                display_order = (
                    index + 1
                )

            # ==================================================
            # DUPLICATE KEY
            #
            # exam + subject + class + section
            # ==================================================

            combination = (
                subject_id,
                class_id,
                section_id
            )

            # ==================================================
            # DUPLICATE IN CURRENT REQUEST
            # ==================================================

            if combination in request_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} is duplicated on row {row_number} for {class_text}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            request_combinations.add(
                combination
            )

            # ==================================================
            # DUPLICATE IN DATABASE
            # ==================================================

            if combination in existing_combinations:

                class_text = (
                    selected_class.name
                    if selected_class
                    else "All Classes"
                )

                flash(
                    f"{subject.name} already exists for {class_text}.",
                    "warning"
                )

                return redirect(
                    url_for(
                        "main.add_exam_subject",
                        exam_id=exam.id
                    )
                )

            # ==================================================
            # CREATE EXAM SUBJECT
            # ==================================================

            exam_subject = ExamSubject(
                exam_id=exam.id,

                subject_id=subject_id,

                class_id=class_id,

                section_id=section_id,

                teacher_id=teacher_id,

                max_marks=max_marks,

                pass_marks=pass_marks,

                weight=weight,

                display_order=display_order,

                status=status
            )

            new_exam_subjects.append(
                exam_subject
            )

        # ====================================================
        # NOTHING TO SAVE
        # ====================================================

        if not new_exam_subjects:

            flash(
                "No exam subjects were prepared.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SAVE ALL
        # ====================================================

        try:

            db.session.add_all(
                new_exam_subjects
            )

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to create multiple exam subjects: %s",
                exc
            )

            flash(
                "An error occurred while adding the exam subjects. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.add_exam_subject",
                    exam_id=exam.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            f"{len(new_exam_subjects)} exam subject(s) added successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects",
                exam_id=exam.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # AVAILABLE PROGRAM IDS
    # ========================================================

    program_ids = list({
        int(exam.program_id)
        for exam in exams
        if exam.program_id
    })

    # ========================================================
    # SUBJECTS
    #
    # IMPORTANT:
    # All subjects belonging to available programs.
    # ========================================================

    subjects = []

    if program_ids:

        subjects_query = (
            Subject.query
            .filter(
                Subject.program_id.in_(
                    program_ids
                ),
                Subject.status == "active"
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            subjects_query = (
                subjects_query
                .filter(
                    Subject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        #
        # NULL branch = shared subject
        # ----------------------------------------------------

        if current_role == "branch_admin":

            subjects_query = (
                subjects_query
                .filter(
                    db.or_(
                        Subject.branch_id ==
                        branch_id,

                        Subject.branch_id.is_(None)
                    )
                )
            )

        subjects = (
            subjects_query
            .order_by(
                Subject.name.asc()
            )
            .all()
        )

    # ========================================================
    # CLASSES
    # ========================================================

    classes = []

    if program_ids:

        classes_query = (
            Class.query
            .filter(
                Class.program_id.in_(
                    program_ids
                )
            )
        )

        # ----------------------------------------------------
        # Institution
        # ----------------------------------------------------

        if current_role != "superadmin":

            classes_query = (
                classes_query
                .filter(
                    Class.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # Branch
        # ----------------------------------------------------

        if current_role == "branch_admin":

            classes_query = (
                classes_query
                .filter(
                    Class.branch_id ==
                    branch_id
                )
            )

        classes = (
            classes_query
            .order_by(
                Class.name.asc()
            )
            .all()
        )

    # ========================================================
    # SECTIONS
    # ========================================================

    sections = []

    available_class_ids = [
        int(item.id)
        for item in classes
    ]

    if available_class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    available_class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # TEACHERS
    #
    # ONLY PROGRAM ASSIGNED TEACHERS
    #
    # NOT ALL BRANCH TEACHERS
    # ========================================================

    teachers = []

    if program_ids:

        teachers_query = (
            Teacher.query
            .join(
                TeacherSubject,
                TeacherSubject.teacher_id ==
                Teacher.id
            )
            .filter(
                Teacher.is_active.is_(True),

                Teacher.status == "active",

                TeacherSubject.program_id.in_(
                    program_ids
                ),

                TeacherSubject.status == "active"
            )
        )

        # ----------------------------------------------------
        # SUPERADMIN
        # ----------------------------------------------------

        if current_role == "superadmin":

            pass

        # ----------------------------------------------------
        # SCHOOL ADMIN
        # ----------------------------------------------------

        elif current_role == "school_admin":

            if not institution_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    TeacherSubject.institution_id ==
                    institution_id
                )
            )

        # ----------------------------------------------------
        # BRANCH ADMIN
        # ----------------------------------------------------

        elif current_role == "branch_admin":

            if not institution_id or not branch_id:
                abort(403)

            teachers_query = (
                teachers_query
                .filter(
                    Teacher.institution_id ==
                    institution_id,

                    Teacher.branch_id ==
                    branch_id,

                    db.or_(
                        TeacherSubject.branch_id ==
                        branch_id,

                        TeacherSubject.branch_id.is_(None)
                    )
                )
            )

        teachers = (
            teachers_query
            .distinct()
            .order_by(
                Teacher.full_name.asc()
            )
            .all()
        )

    # ========================================================
    # SELECTED EXAM
    # ========================================================

    selected_exam_id = request.args.get(
        "exam_id",
        type=int
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/add_exam_subject.html",

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        selected_exam_id=selected_exam_id,

        user=current_user
    )




# ============================================================
# VIEW SINGLE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>",
    methods=["GET"]
)
@login_required
def view_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # SCOPE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        query = query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        # Teacher can see only subjects assigned to them.
        teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if teacher_id:

            query = query.filter(
                ExamSubject.teacher_id == teacher_id
            )

        else:

            query = query.filter(False)

    exam_subject = query.first()

    if not exam_subject:
        abort(404)

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/view_exam_subject.html",
        exam_subject=exam_subject,
    )


# ============================================================
# ALL EXAM SUBJECTS
# ============================================================

@bp.route(
    "/exam-subjects",
    methods=["GET"]
)
@login_required
def all_exam_subjects():

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_view():
        abort(403)

    # ========================================================
    # CURRENT ROLE
    # ========================================================

    role = getattr(
        current_user,
        "role",
        None
    )

    # ========================================================
    # FILTERS
    # ========================================================

    search = (
        request.args.get(
            "search",
            ""
        )
        .strip()
    )

    status = (
        request.args.get(
            "status",
            ""
        )
        .strip()
        .lower()
    )

    exam_id = request.args.get(
        "exam_id",
        type=int
    )

    subject_id = request.args.get(
        "subject_id",
        type=int
    )

    class_id = request.args.get(
        "class_id",
        type=int
    )

    section_id = request.args.get(
        "section_id",
        type=int
    )

    teacher_id = request.args.get(
        "teacher_id",
        type=int
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    page = request.args.get(
        "page",
        1,
        type=int
    )

    per_page = request.args.get(
        "per_page",
        25,
        type=int
    )

    allowed_per_page = {
        10,
        25,
        50,
        100,
    }

    if per_page not in allowed_per_page:
        per_page = 25

    # ========================================================
    # BASE QUERY
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .join(
            Subject,
            Subject.id == ExamSubject.subject_id
        )
    )

    # ========================================================
    # ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        # Superadmin can see everything.
        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            query = query.filter(False)

        else:

            query = query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            query = query.filter(False)

        else:

            query = query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        query = query.filter(False)

    # ========================================================
    # SEARCH
    # ========================================================

    if search:

        search_term = f"%{search}%"

        query = query.filter(
            db.or_(
                Exam.name.ilike(search_term),
                Exam.code.ilike(search_term),
                Subject.name.ilike(search_term),
                Subject.code.ilike(search_term),
            )
        )

    # ========================================================
    # STATUS
    # ========================================================

    if status:

        query = query.filter(
            ExamSubject.status == status
        )

    # ========================================================
    # EXAM
    # ========================================================

    if exam_id:

        query = query.filter(
            ExamSubject.exam_id == exam_id
        )

    # ========================================================
    # SUBJECT
    # ========================================================

    if subject_id:

        query = query.filter(
            ExamSubject.subject_id == subject_id
        )

    # ========================================================
    # CLASS
    # ========================================================

    if class_id:

        query = query.filter(
            ExamSubject.class_id == class_id
        )

    # ========================================================
    # SECTION
    # ========================================================

    if section_id:

        query = query.filter(
            ExamSubject.section_id == section_id
        )

    # ========================================================
    # TEACHER
    # ========================================================

    if teacher_id:

        query = query.filter(
            ExamSubject.teacher_id == teacher_id
        )

    # ========================================================
    # ORDER
    # ========================================================

    query = query.order_by(
        ExamSubject.display_order.asc(),
        ExamSubject.id.desc()
    )

    # ========================================================
    # PAGINATION
    # ========================================================

    pagination = query.paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    # ========================================================
    # FILTER DATA
    # ========================================================

    # --------------------------------------------------------
    # EXAMS
    # --------------------------------------------------------

    exams_query = Exam.query

    if role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id
        )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        exams_query = exams_query.filter(
            Exam.institution_id == institution_id,
            Exam.branch_id == branch_id
        )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            exams_query = (
                exams_query
                .join(
                    ExamSubject,
                    ExamSubject.exam_id == Exam.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            exams_query = exams_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
        "teacher",
    }:

        exams_query = exams_query.filter(False)

    exams = (
        exams_query
        .order_by(
            Exam.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SUBJECTS
    # --------------------------------------------------------

    subjects_query = Subject.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            subjects_query = (
                subjects_query
                .join(
                    ExamSubject,
                    ExamSubject.subject_id == Subject.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            subjects_query = subjects_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        subjects_query = subjects_query.filter(False)

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # CLASSES
    # --------------------------------------------------------

    classes_query = Class.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            classes_query = (
                classes_query
                .join(
                    ExamSubject,
                    ExamSubject.class_id == Class.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            classes_query = classes_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        classes_query = classes_query.filter(False)

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # SECTIONS
    # --------------------------------------------------------

    sections_query = Section.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            sections_query = (
                sections_query
                .join(
                    ExamSubject,
                    ExamSubject.section_id == Section.id
                )
                .filter(
                    ExamSubject.teacher_id ==
                    current_teacher_id
                )
                .distinct()
            )

        else:

            sections_query = sections_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        sections_query = sections_query.filter(False)

    sections = (
        sections_query
        .order_by(
            Section.name.asc()
        )
        .all()
    )

    # --------------------------------------------------------
    # TEACHERS
    # --------------------------------------------------------

    teachers_query = Teacher.query

    if role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if current_teacher_id:

            teachers_query = teachers_query.filter(
                Teacher.id == current_teacher_id
            )

        else:

            teachers_query = teachers_query.filter(False)

    elif role not in {
        "superadmin",
        "school_admin",
        "branch_admin",
    }:

        teachers_query = teachers_query.filter(False)

    teachers = (
        teachers_query
        .order_by(
            Teacher.full_name.asc()
            if hasattr(Teacher, "full_name")
            else Teacher.id.asc()
        )
        .all()
    )

    # ========================================================
    # STATISTICS
    # ========================================================

    # --------------------------------------------------------
    # Statistics query
    #
    # IMPORTANT:
    # We use the same ROLE SCOPE but do NOT use the
    # user's current filters.
    # --------------------------------------------------------

    stats_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
    )

    # ========================================================
    # STATISTICS ROLE SCOPE
    # ========================================================

    if role == "superadmin":

        pass

    elif role == "school_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        if not institution_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id
            )

    elif role == "branch_admin":

        institution_id = getattr(
            current_user,
            "institution_id",
            None
        )

        branch_id = getattr(
            current_user,
            "branch_id",
            None
        )

        if not institution_id or not branch_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )

    elif role == "teacher":

        current_teacher_id = getattr(
            current_user,
            "teacher_id",
            None
        )

        if not current_teacher_id:

            stats_query = stats_query.filter(False)

        else:

            stats_query = stats_query.filter(
                ExamSubject.teacher_id ==
                current_teacher_id
            )

    else:

        stats_query = stats_query.filter(False)

    # ========================================================
    # TOTAL
    # ========================================================

    total_exam_subjects = (
        stats_query
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # ACTIVE
    # ========================================================

    active_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "active"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # INACTIVE
    # ========================================================

    inactive_exam_subjects = (
        stats_query
        .filter(
            ExamSubject.status == "inactive"
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER ASSIGNED
    # ========================================================

    exam_subjects_with_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # TEACHER NOT ASSIGNED
    # ========================================================

    exam_subjects_without_teacher = (
        stats_query
        .filter(
            ExamSubject.teacher_id.is_(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # CLASS ASSIGNED
    # ========================================================

    exam_subjects_with_class = (
        stats_query
        .filter(
            ExamSubject.class_id.isnot(None)
        )
        .with_entities(
            db.func.count(
                ExamSubject.id
            )
        )
        .scalar()
        or 0
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/exam_subjects/all_exam_subjects.html",

        # ----------------------------------------------------
        # MAIN DATA
        # ----------------------------------------------------

        exam_subjects=pagination.items,

        pagination=pagination,

        # ----------------------------------------------------
        # FILTER DATA
        # ----------------------------------------------------

        exams=exams,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        # ----------------------------------------------------
        # FILTER VALUES
        # ----------------------------------------------------

        search=search,

        status=status,

        selected_exam_id=exam_id,

        selected_subject_id=subject_id,

        selected_class_id=class_id,

        selected_section_id=section_id,

        selected_teacher_id=teacher_id,

        selected_status=status,

        per_page=per_page,

        # ----------------------------------------------------
        # STATISTICS
        # ----------------------------------------------------

        total_exam_subjects=total_exam_subjects,

        active_exam_subjects=active_exam_subjects,

        inactive_exam_subjects=inactive_exam_subjects,

        exam_subjects_with_teacher=
            exam_subjects_with_teacher,

        exam_subjects_without_teacher=
            exam_subjects_without_teacher,

        exam_subjects_with_class=
            exam_subjects_with_class,

        # ----------------------------------------------------
        # CURRENT USER
        # ----------------------------------------------------

        user=current_user
    )


# ============================================================
# EDIT EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/edit",
    methods=["GET", "POST"]
)
@login_required
def edit_exam_subject(exam_subject_id):

    # ========================================================
    # ROLE SECURITY
    # ========================================================

    allowed_roles = {
        "superadmin",
        "school_admin",
        "branch_admin",
    }

    current_role = getattr(
        current_user,
        "role",
        None
    )

    if current_role not in allowed_roles:
        abort(403)

    # ========================================================
    # CURRENT USER SCOPE
    # ========================================================

    institution_id = getattr(
        current_user,
        "institution_id",
        None
    )

    branch_id = getattr(
        current_user,
        "branch_id",
        None
    )

    # ========================================================
    # LOAD EXAM SUBJECT
    # ========================================================

    exam_subject_query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    # ========================================================
    # INSTITUTION / BRANCH SECURITY
    # ========================================================

    if current_role == "school_admin":

        if not institution_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id
            )
        )

    elif current_role == "branch_admin":

        if not institution_id or not branch_id:
            abort(403)

        exam_subject_query = (
            exam_subject_query
            .filter(
                Exam.institution_id == institution_id,
                Exam.branch_id == branch_id
            )
        )

    # ========================================================
    # GET EXAM SUBJECT
    # ========================================================

    exam_subject = (
        exam_subject_query
        .first()
    )

    if not exam_subject:
        abort(404)

    # ========================================================
    # EXAM
    # ========================================================

    exam = exam_subject.exam

    if not exam:
        abort(404)

    # ========================================================
    # PROGRAM
    # ========================================================

    if not exam.program_id:
        flash(
            "The exam has no program assigned.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    program = (
        Program.query
        .filter(
            Program.id == exam.program_id
        )
        .first()
    )

    if not program:
        flash(
            "The program assigned to this exam was not found.",
            "danger"
        )

        return redirect(
            url_for(
                "main.all_exam_subjects"
            )
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # SUBJECT
        # ====================================================

        raw_subject_id = request.form.get(
            "subject_id"
        )

        raw_subject_id = (
            str(raw_subject_id).strip()
            if raw_subject_id
            else ""
        )

        if not raw_subject_id:

            flash(
                "Please select a subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        try:

            subject_id = int(
                raw_subject_id
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid subject.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # VALID SUBJECT
        #
        # Subject must belong to:
        #
        # Exam.program_id
        # Exam.institution_id
        #
        # Branch can be:
        #
        #   exam.branch_id
        #   NULL/shared
        # ====================================================

        subject_query = (
            Subject.query
            .filter(
                Subject.id == subject_id,
                Subject.program_id == exam.program_id,
                Subject.institution_id == exam.institution_id,
                Subject.status == "active"
            )
        )

        if exam.branch_id:

            subject_query = (
                subject_query
                .filter(
                    db.or_(
                        Subject.branch_id == exam.branch_id,
                        Subject.branch_id.is_(None)
                    )
                )
            )

        subject = (
            subject_query
            .first()
        )

        if not subject:

            flash(
                "The selected subject does not belong to the selected exam program.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # CLASS
        # ====================================================

        raw_class_id = request.form.get(
            "class_id"
        )

        raw_class_id = (
            str(raw_class_id).strip()
            if raw_class_id
            else ""
        )

        class_id = None
        selected_class = None

        if raw_class_id:

            try:

                class_id = int(
                    raw_class_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            class_query = (
                Class.query
                .filter(
                    Class.id == class_id,
                    Class.program_id == exam.program_id,
                    Class.institution_id == exam.institution_id
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                class_query = (
                    class_query
                    .filter(
                        Class.branch_id == exam.branch_id
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                class_query = (
                    class_query
                    .filter(
                        Class.academic_year_id ==
                        exam.academic_year_id
                    )
                )

            selected_class = (
                class_query
                .first()
            )

            if not selected_class:

                flash(
                    "The selected class does not belong to the exam program.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # SECTION
        # ====================================================

        raw_section_id = request.form.get(
            "section_id"
        )

        raw_section_id = (
            str(raw_section_id).strip()
            if raw_section_id
            else ""
        )

        section_id = None
        selected_section = None

        if raw_section_id:

            # ------------------------------------------------
            # Section requires class
            # ------------------------------------------------

            if not class_id:

                flash(
                    "Please select a class before selecting a section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            try:

                section_id = int(
                    raw_section_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid section.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            selected_section = (
                Section.query
                .filter(
                    Section.id == section_id,
                    Section.class_id == class_id
                )
                .first()
            )

            if not selected_section:

                flash(
                    "The selected section does not belong to the selected class.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # TEACHER
        # ====================================================

        raw_teacher_id = request.form.get(
            "teacher_id"
        )

        raw_teacher_id = (
            str(raw_teacher_id).strip()
            if raw_teacher_id
            else ""
        )

        teacher_id = None
        teacher = None

        if raw_teacher_id:

            try:

                teacher_id = int(
                    raw_teacher_id
                )

            except (
                TypeError,
                ValueError
            ):

                flash(
                    "Invalid teacher.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Teacher base validation
            # ------------------------------------------------

            teacher_query = (
                Teacher.query
                .filter(
                    Teacher.id == teacher_id,
                    Teacher.institution_id ==
                    exam.institution_id,
                    Teacher.is_active.is_(True),
                    Teacher.status == "active"
                )
            )

            if exam.branch_id:

                teacher_query = (
                    teacher_query
                    .filter(
                        Teacher.branch_id ==
                        exam.branch_id
                    )
                )

            teacher = (
                teacher_query
                .first()
            )

            if not teacher:

                flash(
                    "The selected teacher is not available for this exam.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # TeacherSubject
            #
            # Program + Subject
            # ------------------------------------------------

            teacher_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            # ------------------------------------------------
            # Branch
            # ------------------------------------------------

            if exam.branch_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Academic Year
            # ------------------------------------------------

            if exam.academic_year_id:

                teacher_assignment_query = (
                    teacher_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            teacher_assignment = (
                teacher_assignment_query
                .first()
            )

            if not teacher_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

            # ------------------------------------------------
            # Class / Section compatibility
            #
            # TeacherSubject class_id NULL
            # = program-wide assignment
            #
            # TeacherSubject section_id NULL
            # = all sections
            # ------------------------------------------------

            compatible_assignment_query = (
                TeacherSubject.query
                .filter(
                    TeacherSubject.teacher_id ==
                    teacher_id,

                    TeacherSubject.program_id ==
                    exam.program_id,

                    TeacherSubject.institution_id ==
                    exam.institution_id,

                    TeacherSubject.status ==
                    "active",

                    db.or_(
                        TeacherSubject.subject_id.is_(None),
                        TeacherSubject.subject_id ==
                        subject_id
                    )
                )
            )

            if exam.branch_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.branch_id ==
                            exam.branch_id,

                            TeacherSubject.branch_id.is_(None)
                        )
                    )
                )

            if exam.academic_year_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.academic_year_id ==
                            exam.academic_year_id,

                            TeacherSubject.academic_year_id.is_(None)
                        )
                    )
                )

            # ------------------------------------------------
            # Class compatibility
            # ------------------------------------------------

            if class_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.class_id.is_(None),
                            TeacherSubject.class_id ==
                            class_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.class_id.is_(None)
                    )
                )

            # ------------------------------------------------
            # Section compatibility
            # ------------------------------------------------

            if section_id:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        db.or_(
                            TeacherSubject.section_id.is_(None),
                            TeacherSubject.section_id ==
                            section_id
                        )
                    )
                )

            else:

                compatible_assignment_query = (
                    compatible_assignment_query
                    .filter(
                        TeacherSubject.section_id.is_(None)
                    )
                )

            compatible_assignment = (
                compatible_assignment_query
                .first()
            )

            if not compatible_assignment:

                flash(
                    f"{teacher.full_name} is not assigned to the selected class/section for {subject.name}.",
                    "danger"
                )

                return redirect(
                    url_for(
                        "main.edit_exam_subject",
                        exam_subject_id=exam_subject.id
                    )
                )

        # ====================================================
        # MAX MARKS
        # ====================================================

        raw_max_marks = request.form.get(
            "max_marks",
            "100"
        )

        try:

            max_marks = float(
                raw_max_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if max_marks <= 0:

            flash(
                "Maximum marks must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # PASS MARKS
        # ====================================================

        raw_pass_marks = request.form.get(
            "pass_marks",
            "50"
        )

        try:

            pass_marks = float(
                raw_pass_marks
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid pass marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks < 0:

            flash(
                "Pass marks cannot be negative.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if pass_marks > max_marks:

            flash(
                "Pass marks cannot exceed maximum marks.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # WEIGHT
        # ====================================================

        raw_weight = request.form.get(
            "weight",
            "100"
        )

        try:

            weight = float(
                raw_weight
            )

        except (
            TypeError,
            ValueError
        ):

            flash(
                "Invalid weight.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        if weight <= 0:

            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # DISPLAY ORDER
        # ====================================================

        raw_display_order = request.form.get(
            "display_order",
            "1"
        )

        try:

            display_order = int(
                raw_display_order
            )

        except (
            TypeError,
            ValueError
        ):

            display_order = 1

        if display_order <= 0:

            display_order = 1

        # ====================================================
        # STATUS
        # ====================================================

        status = request.form.get(
            "status",
            "active"
        )

        status = (
            status.strip().lower()
            if status
            else "active"
        )

        if status not in {
            "active",
            "inactive"
        }:

            status = "active"

        # ====================================================
        # DUPLICATE PROTECTION
        #
        # exam + subject + class + section
        #
        # EXCLUDE CURRENT RECORD
        # ====================================================

        duplicate_query = (
            ExamSubject.query
            .filter(
                ExamSubject.exam_id == exam.id,

                ExamSubject.subject_id ==
                subject_id,

                ExamSubject.id !=
                exam_subject.id
            )
        )

        # ----------------------------------------------------
        # Class
        # ----------------------------------------------------

        if class_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.class_id ==
                    class_id
                )
            )

        # ----------------------------------------------------
        # Section
        # ----------------------------------------------------

        if section_id is None:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id.is_(None)
                )
            )

        else:

            duplicate_query = (
                duplicate_query
                .filter(
                    ExamSubject.section_id ==
                    section_id
                )
            )

        duplicate = (
            duplicate_query
            .first()
        )

        if duplicate:

            class_text = (
                selected_class.name
                if selected_class
                else "All Classes"
            )

            section_text = (
                selected_section.name
                if selected_section
                else "All Sections"
            )

            flash(
                f"{subject.name} already exists for {class_text} / {section_text}.",
                "warning"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # UPDATE
        # ====================================================

        exam_subject.subject_id = subject_id
        exam_subject.class_id = class_id
        exam_subject.section_id = section_id
        exam_subject.teacher_id = teacher_id
        exam_subject.max_marks = max_marks
        exam_subject.pass_marks = pass_marks
        exam_subject.weight = weight
        exam_subject.display_order = display_order
        exam_subject.status = status

        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.commit()

        except Exception as exc:

            db.session.rollback()

            current_app.logger.exception(
                "Failed to update exam subject %s: %s",
                exam_subject_id,
                exc
            )

            flash(
                "An error occurred while updating the exam subject. No changes were saved.",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_exam_subject",
                    exam_subject_id=exam_subject.id
                )
            )

        # ====================================================
        # SUCCESS
        # ====================================================

        flash(
            "Exam subject updated successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.view_exam_subject",
                exam_subject_id=exam_subject.id
            )
        )

    # ========================================================
    # GET DATA
    # ========================================================

    # ========================================================
    # SUBJECTS
    #
    # Only subjects belonging to this exam's program.
    # ========================================================

    subjects_query = (
        Subject.query
        .filter(
            Subject.program_id == exam.program_id,
            Subject.institution_id == exam.institution_id,
            Subject.status == "active"
        )
    )

    if exam.branch_id:

        subjects_query = (
            subjects_query
            .filter(
                db.or_(
                    Subject.branch_id == exam.branch_id,
                    Subject.branch_id.is_(None)
                )
            )
        )

    subjects = (
        subjects_query
        .order_by(
            Subject.name.asc()
        )
        .all()
    )

    # ========================================================
    # CLASSES
    #
    # Optional.
    #
    # Some programs have no classes.
    # ========================================================

    classes_query = (
        Class.query
        .filter(
            Class.program_id == exam.program_id,
            Class.institution_id == exam.institution_id
        )
    )

    if exam.branch_id:

        classes_query = (
            classes_query
            .filter(
                Class.branch_id == exam.branch_id
            )
        )

    if exam.academic_year_id:

        classes_query = (
            classes_query
            .filter(
                Class.academic_year_id ==
                exam.academic_year_id
            )
        )

    classes = (
        classes_query
        .order_by(
            Class.name.asc()
        )
        .all()
    )

    # ========================================================
    # SECTIONS
    # ========================================================

    class_ids = [
        int(item.id)
        for item in classes
    ]

    sections = []

    if class_ids:

        sections = (
            Section.query
            .filter(
                Section.class_id.in_(
                    class_ids
                )
            )
            .order_by(
                Section.name.asc()
            )
            .all()
        )

    # ========================================================
    # PROGRAM TEACHERS
    #
    # IMPORTANT:
    # NOT ALL BRANCH TEACHERS.
    #
    # Only teachers assigned to:
    #
    # Exam Program
    #      ↓
    # TeacherSubject
    #      ↓
    # Teacher
    # ========================================================

    teachers_query = (
        Teacher.query
        .join(
            TeacherSubject,
            TeacherSubject.teacher_id ==
            Teacher.id
        )
        .filter(
            Teacher.institution_id ==
            exam.institution_id,

            Teacher.is_active.is_(True),

            Teacher.status == "active",

            TeacherSubject.institution_id ==
            exam.institution_id,

            TeacherSubject.program_id ==
            exam.program_id,

            TeacherSubject.status ==
            "active"
        )
    )

    # ========================================================
    # BRANCH
    # ========================================================

    if exam.branch_id:

        teachers_query = (
            teachers_query
            .filter(
                Teacher.branch_id ==
                exam.branch_id,

                db.or_(
                    TeacherSubject.branch_id ==
                    exam.branch_id,

                    TeacherSubject.branch_id.is_(None)
                )
            )
        )

    # ========================================================
    # ACADEMIC YEAR
    # ========================================================

    if exam.academic_year_id:

        teachers_query = (
            teachers_query
            .filter(
                db.or_(
                    TeacherSubject.academic_year_id ==
                    exam.academic_year_id,

                    TeacherSubject.academic_year_id.is_(None)
                )
            )
        )

    teachers = (
        teachers_query
        .distinct()
        .order_by(
            Teacher.full_name.asc()
        )
        .all()
    )

    # ========================================================
    # RENDER
    # ========================================================

    return render_template(
        "backend/pages/exam_subjects/edit_exam_subject.html",

        exam_subject=exam_subject,

        exam=exam,

        program=program,

        subjects=subjects,

        classes=classes,

        sections=sections,

        teachers=teachers,

        user=current_user
    )




# ============================================================
# DELETE EXAM SUBJECT
# ============================================================

@bp.route(
    "/exam-subjects/<int:exam_subject_id>/delete",
    methods=["POST"]
)
@login_required
def delete_exam_subject(exam_subject_id):

    # ========================================================
    # SECURITY
    # ========================================================

    if not _exam_subject_can_manage():
        abort(403)

    # ========================================================
    # LOAD WITH SCOPE
    # ========================================================

    query = (
        ExamSubject.query
        .join(
            Exam,
            Exam.id == ExamSubject.exam_id
        )
        .filter(
            ExamSubject.id == exam_subject_id
        )
    )

    query = _exam_subject_scope_query(
        query
    )

    exam_subject = query.first()

    if not exam_subject:
        abort(404)

    # ========================================================
    # DELETE
    # ========================================================

    try:

        db.session.delete(
            exam_subject
        )

        db.session.commit()

        flash(
            "Exam subject deleted successfully.",
            "success"
        )

    except Exception:

        db.session.rollback()

        flash(
            "Unable to delete exam subject.",
            "danger"
        )

    # ========================================================
    # REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "main.all_exam_subjects"
        )
    )







































#---------------------------------------
#---- Route: Ending |  Logout Sections ----
#---------------------------------------
@bp.route("/logout")
def logout():

    if current_user.is_authenticated:

        user = User.query.get(current_user.id)

        if user:
            user.auth_status = "logout"
            user.session_token = None
            user.last_seen = datetime.utcnow()

            try:
                db.session.commit()
            except Exception:
                db.session.rollback()
                current_app.logger.exception("Logout update error")

        logout_user()

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.login")
    )


# ---------------------------------------
# ---- Route: Teacher Logout ------------
# ---------------------------------------

@bp.route("/teacher/logout")
def teacher_logout():

    # Get current teacher from session
    teacher_id = session.get("teacher_id")

    if teacher_id:

        teacher = Teacher.query.get(teacher_id)

        if teacher:
            teacher.last_active = datetime.utcnow()

            try:
                db.session.commit()

            except Exception:
                db.session.rollback()

                current_app.logger.exception(
                    "Teacher logout update error"
                )

        # IMPORTANT:
        # Remove ONLY teacher session data.
        # Do NOT use session.clear()
        # because Admin/User Flask-Login session
        # must remain untouched.

        session.pop("teacher_id", None)
        session.pop("teacher_role", None)
        session.pop("teacher_institution_id", None)
        session.pop("teacher_branch_id", None)

        flash(
            "You have been logged out successfully.",
            "success"
        )

    else:

        flash(
            "You are already logged out.",
            "info"
        )

    return redirect(
        url_for("main.teacher_login")
    )

    



